const g=2,n="dao-duc",i="Đạo đức lớp 2",h="internal",t=[{id:"que-huong-em",title:"Quê hương em",lessons:[{id:"dd2-ve-dep-que-huong",title:"Bài 1: Vẻ đẹp quê hương em",weeks:[1,2],learn:[{title:"Quê hương là gì?",text:"Quê hương là nơi em sinh ra, lớn lên, có gia đình, xóm làng, bạn bè thân thuộc.",example:"🏡 🌾 🏞️"},{title:"Quê hương tươi đẹp",text:"Mỗi miền quê có vẻ đẹp riêng: cánh đồng lúa, dòng sông, núi đồi, bãi biển, phố phường.",example:"🌾 🏞️ ⛰️ 🏖️ 🏙️"},{title:"Con người quê hương",text:"Người dân quê hương chăm chỉ, hiếu khách, yêu thương, giúp đỡ nhau.",example:"👩‍🌾 🧑‍🔧 🤝"}],practice:[{questions:[{id:"dd2-ve-dep-que-huong-01",type:"mc",q:"Quê hương là nơi nào?",emoji:"🏡",explain:"Quê hương là nơi em sinh ra, lớn lên, gắn bó.",options:["Nơi em chỉ đi qua một lần","Nơi em sinh ra và lớn lên","Nơi trong truyện cổ tích"],answer:1},{id:"dd2-ve-dep-que-huong-02",type:"tf",q:"Mỗi miền quê đều có vẻ đẹp riêng.",emoji:"🌾",explain:"Có quê đồng lúa, có quê miền biển, có quê miền núi.",answer:!0},{id:"dd2-ve-dep-que-huong-03",type:"mc",q:"Cảnh nào thường thấy ở làng quê?",emoji:"🌾",explain:"Cánh đồng lúa là cảnh quen thuộc ở nhiều làng quê Việt Nam.",options:["Cánh đồng lúa xanh","Tàu vũ trụ bay lên","Tảng băng trôi trên biển"],answer:0},{id:"dd2-ve-dep-que-huong-04",type:"tf",q:"Chỉ quê hương có núi cao mới là quê hương đẹp.",emoji:"⛰️",explain:"Quê hương nào cũng đẹp theo cách riêng.",answer:!1},{id:"dd2-ve-dep-que-huong-05",type:"mc",q:"Người dân quê em làm nghề trồng lúa được gọi là gì?",emoji:"👩‍🌾",explain:"Người trồng lúa, trồng rau là nông dân.",options:["Phi công","Thủy thủ","Nông dân"],answer:2},{id:"dd2-ve-dep-que-huong-06",type:"mc",q:"Quê hương miền biển thường có gì?",emoji:"🏖️",explain:"Miền biển có bãi cát, thuyền đánh cá.",options:["Ruộng bậc thang trên núi","Sa mạc cát","Bãi cát và thuyền đánh cá"],answer:2},{id:"dd2-ve-dep-que-huong-07",type:"tf",q:"Thành phố nơi em sinh ra cũng là quê hương của em.",emoji:"🏙️",explain:"Quê hương có thể là làng quê hoặc thành phố.",answer:!0},{id:"dd2-ve-dep-que-huong-08",type:"mc",q:"Người dân quê hương em thường như thế nào?",emoji:"🤝",explain:"Người dân quê hương chăm chỉ và đoàn kết.",options:["Chăm chỉ, yêu thương nhau","Lười biếng, hay cãi nhau","Không quen biết ai"],answer:0},{id:"dd2-ve-dep-que-huong-09",type:"tf",q:"Em không cần biết gì về quê hương mình.",emoji:"🔍",explain:"Em tìm hiểu để thêm yêu quê hương.",answer:!1}]},{questions:[{id:"dd2-ve-dep-que-huong-10",type:"match",q:"Nối miền quê với cảnh đẹp.",emoji:"🗺️",explain:"Mỗi nơi có cảnh đẹp riêng.",pairs:[["Miền núi","Ruộng bậc thang"],["Miền biển","Bãi cát, sóng biển"],["Đồng bằng","Cánh đồng lúa rộng"],["Thành phố","Phố phường, công viên"]]},{id:"dd2-ve-dep-que-huong-11",type:"multi",q:"Điều gì làm nên vẻ đẹp quê hương?",emoji:"🏞️",explain:"Thiên nhiên, con người, món ăn làm nên vẻ đẹp quê hương; rác thải làm xấu quê hương.",options:["Cảnh thiên nhiên","Con người chăm chỉ, thân thiện","Rác thải khắp nơi","Những món ăn quen thuộc"],answers:[0,1,3]},{id:"dd2-ve-dep-que-huong-12",type:"mc",q:"Vì sao em tự hào về quê hương?",emoji:"❤️",explain:"Em tự hào về cảnh đẹp và con người quê hương.",options:["Vì quê hương lớn nhất thế giới","Vì quê hương có cảnh đẹp, người tốt","Vì quê hương không ai biết"],answer:1},{id:"dd2-ve-dep-que-huong-13",type:"tf",q:"Giới thiệu với bạn về quê mình là việc làm thể hiện tình yêu quê hương.",emoji:"🗣️",explain:"Giới thiệu quê hương cho thấy em tự hào về quê mình.",answer:!0},{id:"dd2-ve-dep-que-huong-14",type:"mc",q:"Để biết thêm về quê hương, em có thể làm gì?",emoji:"👴",explain:"Ông bà, bố mẹ kể cho em nhiều điều về quê hương.",options:["Hỏi ông bà, bố mẹ về quê hương","Không hỏi ai, tự đoán là xong","Chỉ ngồi chơi điện thoại cả ngày"],answer:0},{id:"dd2-ve-dep-que-huong-15",type:"tf",q:"Quê của bạn khác quê mình thì quê bạn xấu hơn.",emoji:"🙅",explain:"Quê hương nào cũng đáng quý, em tôn trọng quê hương của bạn.",answer:!1},{id:"dd2-ve-dep-que-huong-16",type:"order",q:"Sắp xếp các bước giới thiệu quê hương với bạn.",emoji:"🏡",explain:"Giới thiệu tên, cảnh đẹp, con người rồi mời bạn đến thăm.",items:["Nói tên quê hương","Kể cảnh đẹp ở quê","Kể về con người, món ăn","Mời bạn về thăm quê"]},{id:"dd2-ve-dep-que-huong-17",type:"mc",q:"Bạn Hà kể: “Quê mình có con sông hiền hòa, chiều chiều trẻ con ra thả diều.” Quê Hà có cảnh gì?",emoji:"🏞️",explain:"Hà kể về con sông quê mình.",options:["Biển cả","Núi tuyết","Dòng sông"],answer:2},{id:"dd2-ve-dep-que-huong-18",type:"tf",q:"Món ăn quen thuộc ở quê cũng là một nét đẹp của quê hương.",emoji:"🍲",explain:"Món ăn quê hương gắn với kỷ niệm của mỗi người.",answer:!0}]},{questions:[{id:"dd2-ve-dep-que-huong-19",type:"mc",q:"Bạn mới chuyển trường hỏi về quê em. Em nên làm gì?",emoji:"👋",explain:"Kể về quê hương giúp bạn hiểu và em thêm tự hào.",options:["Nói quê mình chẳng có gì hay để kể","Vui vẻ kể về cảnh đẹp, con người quê mình","Quay mặt đi, không trả lời câu hỏi của bạn"],answer:1},{id:"dd2-ve-dep-que-huong-20",type:"mc",q:"Nam nói: “Quê tớ ở miền núi, chẳng đẹp bằng thành phố.” Em nói gì với Nam?",emoji:"⛰️",explain:"Quê hương nào cũng có vẻ đẹp riêng.",options:["Đúng rồi, quê cậu xấu, chẳng có gì để ngắm","Miền núi có rừng xanh, ruộng bậc thang đẹp lắm","Kệ cậu, tớ không quan tâm chuyện quê cậu"],answer:1},{id:"dd2-ve-dep-que-huong-21",type:"tf",q:"Vy vẽ tranh cánh đồng quê nội để tặng ông bà. Vy thể hiện tình yêu quê hương.",emoji:"🎨",explain:"Vẽ tranh quê hương là một cách thể hiện tình yêu quê.",answer:!0},{id:"dd2-ve-dep-que-huong-22",type:"multi",q:"Bạn Phúc muốn giới thiệu quê mình ở miền biển. Phúc có thể kể gì?",emoji:"🌊",explain:"Đồi chè trên núi cao là cảnh ở miền núi, trung du.",options:["Bãi biển, sóng xanh","Thuyền đánh cá","Các món hải sản","Đồi chè trên núi cao"],answers:[0,1,2]},{id:"dd2-ve-dep-que-huong-23",type:"mc",q:"Vịnh Hạ Long, một cảnh đẹp nổi tiếng, nằm ở tỉnh nào?",emoji:"⛵",explain:"Vịnh Hạ Long ở tỉnh Quảng Ninh.",options:["Quảng Ninh","Cà Mau","Điện Biên"],answer:0},{id:"dd2-ve-dep-que-huong-24",type:"order",q:"Sắp xếp các việc Lan chuẩn bị bài giới thiệu quê hương.",emoji:"📷",explain:"Tìm hiểu, chuẩn bị tranh ảnh, tập kể rồi giới thiệu.",items:["Hỏi bố mẹ về quê hương","Tìm tranh ảnh quê hương","Tập kể trước gương","Kể cho cả lớp nghe"]},{id:"dd2-ve-dep-que-huong-25",type:"tf",q:"Bạn Dũng chê giọng nói của bạn từ miền khác đến. Dũng làm vậy là đúng.",emoji:"🗣️",explain:"Mỗi vùng có giọng nói riêng, em tôn trọng các bạn.",answer:!1},{id:"dd2-ve-dep-que-huong-26",type:"mc",q:"Em đi chơi xa và nhớ quê. Đó là cảm xúc gì?",emoji:"🥺",explain:"Nhớ quê là vì em yêu, gắn bó với quê hương.",options:["Ghét quê hương","Sợ quê hương","Nhớ quê hương"],answer:2},{id:"dd2-ve-dep-que-huong-27",type:"fill",q:"Nơi em sinh ra và lớn lên là quê …",emoji:"🏡",explain:"Nơi em sinh ra và lớn lên là quê hương.",answer:["hương","huong"],loose:!0}]}],challenge:{questions:[{id:"dd2-ve-dep-que-huong-28",type:"match",q:"Nối việc làm với điều nó thể hiện.",emoji:"💚",explain:"Những việc làm nhỏ thể hiện tình yêu quê hương.",pairs:[["Kể về quê hương cho bạn","Tự hào"],["Tôn trọng quê của bạn","Tôn trọng"],["Hỏi ông bà về quê","Muốn tìm hiểu"]]},{id:"dd2-ve-dep-que-huong-29",type:"mc",q:"Lớp tổ chức “Ngày hội quê em”. Ngọc có thể góp gì?",emoji:"🎉",explain:"Chia sẻ về quê mình giúp ngày hội thêm vui.",options:["Ở nhà, không tham gia ngày hội của lớp","Chê quê của bạn không đẹp bằng quê mình","Mang tranh ảnh, kể về món ăn quê mình"],answer:2},{id:"dd2-ve-dep-que-huong-19",type:"mc",q:"Bạn mới chuyển trường hỏi về quê em. Em nên làm gì?",emoji:"👋",explain:"Kể về quê hương giúp bạn hiểu và em thêm tự hào.",options:["Nói quê mình chẳng có gì hay để kể","Vui vẻ kể về cảnh đẹp, con người quê mình","Quay mặt đi, không trả lời câu hỏi của bạn"],answer:1},{id:"dd2-ve-dep-que-huong-20",type:"mc",q:"Nam nói: “Quê tớ ở miền núi, chẳng đẹp bằng thành phố.” Em nói gì với Nam?",emoji:"⛰️",explain:"Quê hương nào cũng có vẻ đẹp riêng.",options:["Đúng rồi, quê cậu xấu, chẳng có gì để ngắm","Miền núi có rừng xanh, ruộng bậc thang đẹp lắm","Kệ cậu, tớ không quan tâm chuyện quê cậu"],answer:1},{id:"dd2-ve-dep-que-huong-23",type:"mc",q:"Vịnh Hạ Long, một cảnh đẹp nổi tiếng, nằm ở tỉnh nào?",emoji:"⛵",explain:"Vịnh Hạ Long ở tỉnh Quảng Ninh.",options:["Quảng Ninh","Cà Mau","Điện Biên"],answer:0},{id:"dd2-ve-dep-que-huong-25",type:"tf",q:"Bạn Dũng chê giọng nói của bạn từ miền khác đến. Dũng làm vậy là đúng.",emoji:"🗣️",explain:"Mỗi vùng có giọng nói riêng, em tôn trọng các bạn.",answer:!1}]},summary:["Quê hương là nơi em sinh ra và lớn lên.","Mỗi miền quê có vẻ đẹp riêng của thiên nhiên và con người.","Em tự hào về quê hương mình."]},{id:"dd2-yeu-que-huong",title:"Bài 2: Em yêu quê hương",weeks:[3,4],learn:[{title:"Yêu quê hương",text:"Em yêu quê hương bằng những việc làm nhỏ: giữ sạch đường làng, ngõ phố, chăm sóc cây xanh.",example:"🧹 🌳 🏡"},{title:"Kính trọng người dân quê",text:"Em lễ phép, chào hỏi người lớn tuổi, giúp đỡ hàng xóm.",example:"🙇 👵"},{title:"Học tập thật tốt",text:"Chăm ngoan, học giỏi để sau này góp sức xây dựng quê hương.",example:"📚 🌟"}],practice:[{questions:[{id:"dd2-yeu-que-huong-01",type:"tf",q:"Giữ sạch đường làng, ngõ phố là yêu quê hương.",emoji:"🧹",explain:"Giữ sạch nơi mình sống là một cách yêu quê hương.",answer:!0},{id:"dd2-yeu-que-huong-02",type:"mc",q:"Việc nào thể hiện tình yêu quê hương?",emoji:"🌳",explain:"Chăm sóc cây xanh làm quê hương thêm đẹp.",options:["Trồng và chăm sóc cây xanh","Vứt rác xuống dòng sông của làng","Bẻ cành cây ven đường để chơi"],answer:0},{id:"dd2-yeu-que-huong-03",type:"tf",q:"Vứt rác xuống ao làng không ảnh hưởng gì.",emoji:"🗑️",explain:"Rác làm ô nhiễm ao làng, quê hương kém đẹp.",answer:!1},{id:"dd2-yeu-que-huong-04",type:"mc",q:"Gặp các cụ già trong xóm, em làm gì?",emoji:"👵",explain:"Lễ phép với người lớn là nét đẹp của người dân quê.",options:["Đi qua không nhìn","Lễ phép chào hỏi","Trêu chọc"],answer:1},{id:"dd2-yeu-que-huong-05",type:"mc",q:"Học sinh có thể làm gì để xây dựng quê hương sau này?",emoji:"📚",explain:"Học giỏi hôm nay để mai sau xây dựng quê hương.",options:["Chăm ngoan, học giỏi","Bỏ học đi chơi","Không quan tâm việc gì"],answer:0},{id:"dd2-yeu-que-huong-06",type:"tf",q:"Tham gia dọn vệ sinh xóm cùng mọi người là việc làm tốt.",emoji:"🧤",explain:"Đó là việc làm thể hiện tình yêu quê hương.",answer:!0},{id:"dd2-yeu-que-huong-07",type:"mc",q:"Nhà văn hóa của xóm là của ai?",emoji:"🏛️",explain:"Của chung thì mọi người cùng giữ gìn.",options:["Của riêng một nhà","Không của ai","Của chung mọi người"],answer:2},{id:"dd2-yeu-que-huong-08",type:"tf",q:"Chỉ người lớn mới cần yêu quê hương.",emoji:"🧒",explain:"Trẻ em cũng yêu quê hương bằng việc làm vừa sức.",answer:!1},{id:"dd2-yeu-que-huong-09",type:"mc",q:"Bạn nào thể hiện tình yêu quê hương?",emoji:"♻️",explain:"Nhặt rác giữ sạch quê hương là việc đáng khen.",options:["Bạn Tùng hái trộm hoa ở vườn hoa của xóm mình","Bạn Khoa nhặt rác ở bờ sông cùng đoàn thiếu nhi","Bạn Bình vẽ bậy lên bức tường nhà văn hóa xóm"],answer:1}]},{questions:[{id:"dd2-yeu-que-huong-10",type:"match",q:"Nối việc làm với lợi ích cho quê hương.",emoji:"🌱",explain:"Việc nhỏ của em góp phần làm quê hương đẹp hơn.",pairs:[["Trồng cây xanh","Quê thêm mát, thêm đẹp"],["Nhặt rác bờ sông","Sông sạch hơn"],["Chào hỏi hàng xóm","Xóm làng thân thiện"]]},{id:"dd2-yeu-que-huong-11",type:"multi",q:"Việc nào em có thể làm để yêu quê hương?",emoji:"🏡",explain:"Viết vẽ lên tường làm xấu của chung.",options:["Tưới cây ở sân nhà văn hóa","Giữ sạch ngõ xóm","Viết vẽ lên tường nhà văn hóa","Tham gia lễ hội ở địa phương cùng gia đình"],answers:[0,1,3]},{id:"dd2-yeu-que-huong-12",type:"mc",q:"Vì sao cần giữ gìn cảnh đẹp quê hương?",emoji:"🏞️",explain:"Cảnh đẹp quê hương là của chung, ai cũng cần giữ.",options:["Để được người lớn thưởng thật nhiều tiền","Để quê hương luôn sạch đẹp cho mọi người","Vì ở nhà buồn quá, không có việc gì làm"],answer:1},{id:"dd2-yeu-que-huong-13",type:"tf",q:"Thấy bạn bẻ cành hoa ở vườn hoa chung, em khuyên bạn dừng lại.",emoji:"🌸",explain:"Khuyên bạn giúp giữ gìn của chung.",answer:!0},{id:"dd2-yeu-que-huong-14",type:"order",q:"Sắp xếp việc em làm khi tham gia trồng cây ở xóm.",emoji:"🌱",explain:"Đào hố, đặt cây, lấp đất rồi tưới nước.",items:["Đào hố","Đặt cây con xuống hố","Lấp đất, nén chặt","Tưới nước cho cây"]},{id:"dd2-yeu-que-huong-15",type:"mc",q:"Người thân ở xa về thăm quê. Em có thể làm gì?",emoji:"🚶",explain:"Giới thiệu cảnh đẹp quê là thể hiện tình yêu quê hương.",options:["Dẫn người thân đi thăm cảnh đẹp ở quê","Không nói chuyện, chỉ ngồi xem ti vi","Trốn trong phòng đến khi người thân về"],answer:0},{id:"dd2-yeu-que-huong-16",type:"tf",q:"Làm ồn ào, xả rác khi đi lễ hội quê là không sao.",emoji:"🎏",explain:"Đi lễ hội, em giữ trật tự và vệ sinh chung.",answer:!1},{id:"dd2-yeu-que-huong-17",type:"mc",q:"Đi học xa nhà, em có thể làm gì khi nhớ quê?",emoji:"📞",explain:"Hỏi thăm người thân là cách giữ gắn bó với quê.",options:["Quên luôn quê hương và người thân ở quê","Nói với bạn rằng quê mình không đẹp","Gọi điện hỏi thăm người thân ở quê"],answer:2},{id:"dd2-yeu-que-huong-18",type:"tf",q:"Giúp đỡ hàng xóm khi họ gặp khó khăn là nét đẹp của người dân quê.",emoji:"🤝",explain:"Tình làng nghĩa xóm làm quê hương ấm áp.",answer:!0}]},{questions:[{id:"dd2-yeu-que-huong-19",type:"mc",q:"Chủ nhật, xóm em tổ chức dọn vệ sinh đường làng. Em làm gì?",emoji:"🧹",explain:"Tham gia việc chung là yêu quê hương.",options:["Ngủ ở nhà vì hôm nay là ngày nghỉ","Đứng xem mọi người làm một lúc rồi bỏ đi","Xin phép bố mẹ đi cùng, làm việc vừa sức"],answer:2},{id:"dd2-yeu-que-huong-20",type:"mc",q:"Minh thấy bạn ném đá vào cây xoài ở sân đình. Minh nên làm gì?",emoji:"🥭",explain:"Cây ở sân đình là của chung, em bảo vệ cây.",options:["Khuyên bạn dừng lại vì làm hỏng cây","Nhặt đá ném cùng bạn cho vui","Cười với bạn rồi lặng lẽ đi chỗ khác"],answer:0},{id:"dd2-yeu-que-huong-21",type:"tf",q:"Chi đi du lịch, Chi nói với bạn bè mới: “Quê mình có món bánh rất ngon, mời bạn về thăm!”. Chi tự hào về quê hương.",emoji:"🥮",explain:"Giới thiệu và mời bạn về thăm quê là thể hiện tự hào.",answer:!0},{id:"dd2-yeu-que-huong-22",type:"multi",q:"Em có thể làm gì để giữ con sông quê luôn sạch?",emoji:"🏞️",explain:"Đổ nước bẩn xuống sông làm ô nhiễm sông.",options:["Không vứt rác xuống sông","Nhắc mọi người bỏ rác đúng nơi","Tham gia nhặt rác ven sông cùng người lớn","Đổ nước bẩn xuống sông"],answers:[0,1,2]},{id:"dd2-yeu-que-huong-23",type:"mc",q:"Bà kể: “Ngày xưa đường làng ta là đường đất, nay đã đổ bê tông.” Vì sao quê hương đổi mới?",emoji:"🛣️",explain:"Quê hương đổi mới nhờ công sức của mọi người.",options:["Tự nhiên mà có, không cần ai làm cả","Nhờ người dân chăm chỉ góp sức xây dựng","Nhờ có nhiều người vứt rác ra đường làng"],answer:1},{id:"dd2-yeu-que-huong-24",type:"order",q:"Sắp xếp việc Khoa làm khi thấy rác ở ngõ xóm.",emoji:"🧤",explain:"Đeo găng, nhặt rác, bỏ đúng nơi và rửa tay.",items:["Đeo găng tay","Nhặt rác bỏ vào túi","Bỏ túi rác vào thùng rác","Rửa tay sạch sẽ"]},{id:"dd2-yeu-que-huong-25",type:"tf",q:"Thấy cột đèn ở ngõ bị hỏng, em lấy đá ném vỡ nốt cho vui.",emoji:"💡",explain:"Em báo người lớn để sửa, không phá hỏng của chung.",answer:!1},{id:"dd2-yeu-que-huong-26",type:"mc",q:"Lớp em tổ chức thi vẽ “Quê hương em”. Em nên vẽ gì?",emoji:"🖼️",explain:"Vẽ cảnh nơi mình sống thể hiện tình yêu quê hương.",options:["Cảnh đẹp nơi em sống","Cảnh trong phim hoạt hình","Một nơi em chưa từng nghe"],answer:0},{id:"dd2-yeu-que-huong-27",type:"fill",q:"Trồng cây, nhặt rác, chào hỏi hàng xóm là thể hiện tình yêu quê …",emoji:"💚",explain:"Đó là những việc làm thể hiện tình yêu quê hương.",answer:["hương","huong"],loose:!0}]}],challenge:{questions:[{id:"dd2-yeu-que-huong-28",type:"match",q:"Nối tình huống với cách làm đúng.",emoji:"🏡",explain:"Em yêu quê hương bằng việc làm cụ thể.",pairs:[["Thấy rác ven sông","Nhặt bỏ vào thùng cùng người lớn"],["Gặp cụ già trong xóm","Lễ phép chào hỏi"],["Bạn bẻ cây ở vườn chung","Khuyên bạn dừng lại"],["Đi lễ hội quê","Giữ trật tự, vệ sinh"]]},{id:"dd2-yeu-que-huong-29",type:"mc",q:"Một bạn nói: “Mình còn nhỏ, chẳng làm được gì cho quê hương.” Em nói gì?",emoji:"💪",explain:"Trẻ em cũng góp sức bằng những việc vừa sức.",options:["Đúng rồi, mình còn nhỏ nên không làm gì cả","Cứ để người lớn lo hết mọi việc cho quê","Bạn có thể học tốt và giữ sạch nơi mình sống"],answer:2},{id:"dd2-yeu-que-huong-19",type:"mc",q:"Chủ nhật, xóm em tổ chức dọn vệ sinh đường làng. Em làm gì?",emoji:"🧹",explain:"Tham gia việc chung là yêu quê hương.",options:["Ngủ ở nhà vì hôm nay là ngày nghỉ","Đứng xem mọi người làm một lúc rồi bỏ đi","Xin phép bố mẹ đi cùng, làm việc vừa sức"],answer:2},{id:"dd2-yeu-que-huong-20",type:"mc",q:"Minh thấy bạn ném đá vào cây xoài ở sân đình. Minh nên làm gì?",emoji:"🥭",explain:"Cây ở sân đình là của chung, em bảo vệ cây.",options:["Khuyên bạn dừng lại vì làm hỏng cây","Nhặt đá ném cùng bạn cho vui","Cười với bạn rồi lặng lẽ đi chỗ khác"],answer:0},{id:"dd2-yeu-que-huong-22",type:"multi",q:"Em có thể làm gì để giữ con sông quê luôn sạch?",emoji:"🏞️",explain:"Đổ nước bẩn xuống sông làm ô nhiễm sông.",options:["Không vứt rác xuống sông","Nhắc mọi người bỏ rác đúng nơi","Tham gia nhặt rác ven sông cùng người lớn","Đổ nước bẩn xuống sông"],answers:[0,1,2]},{id:"dd2-yeu-que-huong-25",type:"tf",q:"Thấy cột đèn ở ngõ bị hỏng, em lấy đá ném vỡ nốt cho vui.",emoji:"💡",explain:"Em báo người lớn để sửa, không phá hỏng của chung.",answer:!1}]},summary:["Em yêu quê hương bằng việc làm phù hợp với lứa tuổi.","Em giữ gìn cảnh quan, giúp đỡ mọi người ở quê.","Em chăm học để mai sau xây dựng quê hương."]}]},{id:"kinh-trong-thay-co",title:"Kính trọng thầy giáo, cô giáo",lessons:[{id:"dd2-kinh-trong-thay-co",title:"Bài 3: Kính trọng, biết ơn thầy cô",weeks:[5,7],learn:[{title:"Công ơn thầy cô",text:"Thầy cô dạy em kiến thức, dạy em cách sống tốt và luôn quan tâm em.",example:"👩‍🏫 📖 ❤️"},{title:"Kính trọng thầy cô",text:"Em lễ phép chào hỏi, lắng nghe, vâng lời thầy cô. Em không nói trống không.",example:"🙇 “Em chào thầy ạ!”"},{title:"Biết ơn thầy cô",text:"Em chăm học, thăm hỏi thầy cô, làm thiệp, nói lời chúc vào ngày 20 tháng 11.",example:"💐 💌"}],practice:[{questions:[{id:"dd2-kinh-trong-thay-co-01",type:"mc",q:"Thầy cô dạy em điều gì?",emoji:"📖",explain:"Thầy cô dạy em kiến thức và điều hay lẽ phải.",options:["Cách trêu chọc các bạn trong lớp","Kiến thức và cách sống tốt","Cách nói dối để khỏi bị nhắc"],answer:1},{id:"dd2-kinh-trong-thay-co-02",type:"tf",q:"Nói trống không với thầy cô là lễ phép.",emoji:"💬",explain:"Em nói đủ câu, có “ạ”, “thưa” khi nói với thầy cô.",answer:!1},{id:"dd2-kinh-trong-thay-co-03",type:"mc",q:"Ngày Nhà giáo Việt Nam là ngày nào?",emoji:"💐",explain:"Ngày 20 tháng 11 là ngày Nhà giáo Việt Nam.",options:["Ngày 1 tháng 6","Ngày 20 tháng 11","Ngày 8 tháng 3"],answer:1},{id:"dd2-kinh-trong-thay-co-04",type:"mc",q:"Câu nào nói với thầy cô lễ phép?",emoji:"✋",explain:"Có “thưa”, “ạ” là lời nói lễ phép.",options:["Thưa cô, em xin phép phát biểu ạ!","Cô ơi, em nói đây, cô nghe em này!","Này cô! Em muốn nói, cô nghe đi!"],answer:0},{id:"dd2-kinh-trong-thay-co-05",type:"tf",q:"Chăm ngoan, học giỏi là cách thể hiện lòng biết ơn thầy cô.",emoji:"🌟",explain:"Thầy cô vui nhất khi em tiến bộ.",answer:!0},{id:"dd2-kinh-trong-thay-co-06",type:"mc",q:"Thầy cô giảng bài, em làm gì?",emoji:"👂",explain:"Lắng nghe là tôn trọng thầy cô.",options:["Làm việc riêng","Nói chuyện với bạn","Chú ý lắng nghe"],answer:2},{id:"dd2-kinh-trong-thay-co-07",type:"tf",q:"Thầy cô cũ đã không còn dạy em nên em không cần chào nữa.",emoji:"👨‍🏫",explain:"Em luôn kính trọng, biết ơn thầy cô đã dạy mình.",answer:!1},{id:"dd2-kinh-trong-thay-co-08",type:"mc",q:"Cô nhắc nhở khi em làm sai. Em nên làm gì?",emoji:"🙇",explain:"Cô nhắc nhở vì muốn em tiến bộ.",options:["Giận cô, không nói chuyện","Cãi lại cô cho bằng được","Lắng nghe và sửa lỗi"],answer:2},{id:"dd2-kinh-trong-thay-co-09",type:"mc",q:"Ngoài thầy cô giáo, ai cũng chăm lo cho em ở trường?",emoji:"🏫",explain:"Em cũng kính trọng các cô bác nhân viên trong trường.",options:["Bác bảo vệ, cô nhân viên","Người lạ đi ngoài đường","Nhân vật trong phim hoạt hình"],answer:0}]},{questions:[{id:"dd2-kinh-trong-thay-co-10",type:"match",q:"Nối việc làm với điều nó thể hiện.",emoji:"💐",explain:"Mỗi việc làm nhỏ đều thể hiện sự kính trọng, biết ơn.",pairs:[["Chào hỏi lễ phép","Kính trọng"],["Làm thiệp tặng cô","Biết ơn"],["Làm bài đầy đủ","Vâng lời"],["Lắng nghe thầy giảng","Tôn trọng"]]},{id:"dd2-kinh-trong-thay-co-11",type:"multi",q:"Việc nào thể hiện lòng biết ơn thầy cô?",emoji:"💌",explain:"Nói xấu thầy cô là thiếu tôn trọng.",options:["Thăm hỏi khi thầy cô bị ốm","Tự làm thiệp chúc mừng ngày 20 tháng 11","Nói xấu thầy cô","Cố gắng học tốt"],answers:[0,1,3]},{id:"dd2-kinh-trong-thay-co-12",type:"mc",q:"Vì sao em cần biết ơn thầy cô?",emoji:"❤️",explain:"Thầy cô dạy em nên người, em biết ơn.",options:["Vì thầy cô hay cho em nhiều quà và kẹo ngon","Vì thầy cô tận tình dạy dỗ em nên người","Vì bố mẹ bắt em phải nói như vậy"],answer:1},{id:"dd2-kinh-trong-thay-co-13",type:"tf",q:"Món quà quý nhất với thầy cô là sự chăm ngoan, tiến bộ của học trò.",emoji:"🎁",explain:"Thầy cô vui khi học trò tiến bộ.",answer:!0},{id:"dd2-kinh-trong-thay-co-14",type:"order",q:"Sắp xếp việc em làm khi muốn hỏi thầy giáo sau giờ học.",emoji:"❓",explain:"Chào, xin phép, hỏi rồi cảm ơn là lễ phép.",items:["Chào thầy","Xin phép hỏi thầy","Nói rõ điều chưa hiểu","Cảm ơn thầy"]},{id:"dd2-kinh-trong-thay-co-15",type:"mc",q:"Đưa đồ cho thầy cô, em đưa thế nào?",emoji:"🙌",explain:"Đưa bằng hai tay là lễ phép.",options:["Bằng hai tay","Ném lên bàn","Một tay, vừa đưa vừa chạy"],answer:0},{id:"dd2-kinh-trong-thay-co-16",type:"tf",q:"Bạn Vy nhại giọng cô giáo để trêu các bạn. Đó là đùa vô hại.",emoji:"🙊",explain:"Nhại giọng thầy cô là thiếu tôn trọng.",answer:!1},{id:"dd2-kinh-trong-thay-co-17",type:"mc",q:"Lời chúc nào phù hợp ngày 20 tháng 11?",emoji:"🌷",explain:"Chúc thầy cô sức khỏe, niềm vui là lời chúc đẹp.",options:["Chúc cô ra đề kiểm tra thật dễ!","Chúc cô cho cả lớp nghỉ học!","Chúc cô luôn mạnh khỏe, vui vẻ!"],answer:2},{id:"dd2-kinh-trong-thay-co-18",type:"tf",q:"Gặp thầy cô ngoài đường, em vẫn lễ phép chào.",emoji:"🚶",explain:"Ở đâu em cũng lễ phép với thầy cô.",answer:!0}]},{questions:[{id:"dd2-kinh-trong-thay-co-19",type:"mc",q:"Cô giáo đang chấm bài, Bình muốn hỏi bài. Bình nên làm gì?",emoji:"📝",explain:"Chờ cô rảnh và hỏi lễ phép là tôn trọng cô.",options:["Chạy đến giật áo cô ngay","Chờ cô rảnh rồi lễ phép hỏi","Hét to: Cô ơi! Cô ơi!"],answer:1},{id:"dd2-kinh-trong-thay-co-20",type:"mc",q:"Cô giáo năm lớp 1 bị ốm. Lan có thể làm gì?",emoji:"💐",explain:"Thăm hỏi thầy cô cũ là biết ơn.",options:["Không quan tâm vì cô không dạy mình nữa","Cùng bố mẹ đến thăm hoặc gửi lời hỏi thăm cô","Kể chuyện cô ốm để trêu"],answer:1},{id:"dd2-kinh-trong-thay-co-21",type:"tf",q:"Tổ em tự làm tờ báo tường chúc mừng thầy cô ngày 20 tháng 11. Đó là việc làm thể hiện lòng biết ơn.",emoji:"📰",explain:"Tự làm báo tường thể hiện tình cảm với thầy cô.",answer:!0},{id:"dd2-kinh-trong-thay-co-22",type:"multi",q:"Thấy bạn nói chuyện riêng khi cô giảng bài, em có thể làm gì?",emoji:"🤫",explain:"Nói chuyện riêng làm cả hai không hiểu bài.",options:["Nhắc bạn nhỏ nhẹ","Tập trung nghe cô giảng","Nói chuyện cùng bạn","Giờ ra chơi, rủ bạn cùng lắng nghe cô hơn"],answers:[0,1,3]},{id:"dd2-kinh-trong-thay-co-23",type:"mc",q:"Thầy giáo bê chồng vở nặng lên cầu thang. Tùng nên làm gì?",emoji:"📚",explain:"Giúp thầy việc vừa sức là biết quan tâm.",options:["Xin phép mang giúp thầy vài quyển","Chạy vượt lên trước thầy cho nhanh","Đứng nhìn thầy bê một mình"],answer:0},{id:"dd2-kinh-trong-thay-co-24",type:"order",q:"Sắp xếp việc lớp em làm để tri ân thầy cô ngày 20 tháng 11.",emoji:"🎤",explain:"Bàn bạc, phân công, thực hiện và nói lời chúc.",items:["Bàn bạc ý tưởng","Phân công làm thiệp, tập văn nghệ","Tặng thiệp, biểu diễn","Nói lời chúc thầy cô"]},{id:"dd2-kinh-trong-thay-co-25",type:"tf",q:"Thấy bạn nói không đúng về cô giáo, Hà nói theo cho vui.",emoji:"🗯️",explain:"Hà nên khuyên bạn không nói như vậy.",answer:!1},{id:"dd2-kinh-trong-thay-co-26",type:"mc",q:"Cô giao bài khó, Phúc chưa làm được. Phúc nên làm gì?",emoji:"🤔",explain:"Cố gắng và hỏi cô là biết tôn trọng công sức của cô.",options:["Nói to là cô giao bài khó quá","Bỏ đó không làm, chờ bạn làm xong","Cố gắng làm, hỏi cô chỗ chưa hiểu"],answer:2},{id:"dd2-kinh-trong-thay-co-27",type:"fill",q:"Ngày 20 tháng 11 là ngày Nhà … Việt Nam.",emoji:"💐",explain:"Ngày 20 tháng 11 là ngày Nhà giáo Việt Nam.",answer:["giáo","giao"],loose:!0}]}],challenge:{questions:[{id:"dd2-kinh-trong-thay-co-28",type:"match",q:"Nối tình huống với lời nói phù hợp.",emoji:"💬",explain:"Lời chào, cảm ơn, xin lỗi thể hiện sự lễ phép.",pairs:[["Gặp thầy buổi sáng","Em chào thầy ạ!"],["Được cô giảng lại bài","Em cảm ơn cô ạ!"],["Nộp bài muộn","Em xin lỗi cô ạ!"]]},{id:"dd2-kinh-trong-thay-co-29",type:"mc",q:"Ra trường nhiều năm, chị của Nam vẫn về thăm cô giáo cũ. Việc đó thể hiện điều gì?",emoji:"🎓",explain:"Biết ơn thầy cô là tình cảm lâu dài.",options:["Muốn được điểm cao","Không có việc gì làm","Lòng biết ơn thầy cô"],answer:2},{id:"dd2-kinh-trong-thay-co-19",type:"mc",q:"Cô giáo đang chấm bài, Bình muốn hỏi bài. Bình nên làm gì?",emoji:"📝",explain:"Chờ cô rảnh và hỏi lễ phép là tôn trọng cô.",options:["Chạy đến giật áo cô ngay","Chờ cô rảnh rồi lễ phép hỏi","Hét to: Cô ơi! Cô ơi!"],answer:1},{id:"dd2-kinh-trong-thay-co-20",type:"mc",q:"Cô giáo năm lớp 1 bị ốm. Lan có thể làm gì?",emoji:"💐",explain:"Thăm hỏi thầy cô cũ là biết ơn.",options:["Không quan tâm vì cô không dạy mình nữa","Cùng bố mẹ đến thăm hoặc gửi lời hỏi thăm cô","Kể chuyện cô ốm để trêu"],answer:1},{id:"dd2-kinh-trong-thay-co-23",type:"mc",q:"Thầy giáo bê chồng vở nặng lên cầu thang. Tùng nên làm gì?",emoji:"📚",explain:"Giúp thầy việc vừa sức là biết quan tâm.",options:["Xin phép mang giúp thầy vài quyển","Chạy vượt lên trước thầy cho nhanh","Đứng nhìn thầy bê một mình"],answer:0},{id:"dd2-kinh-trong-thay-co-26",type:"mc",q:"Cô giao bài khó, Phúc chưa làm được. Phúc nên làm gì?",emoji:"🤔",explain:"Cố gắng và hỏi cô là biết tôn trọng công sức của cô.",options:["Nói to là cô giao bài khó quá","Bỏ đó không làm, chờ bạn làm xong","Cố gắng làm, hỏi cô chỗ chưa hiểu"],answer:2}]},summary:["Thầy cô dạy dỗ, quan tâm, chăm lo cho em.","Em lễ phép, vâng lời, chăm học để thầy cô vui.","Em biết ơn cả thầy cô đang dạy và thầy cô đã dạy mình."]}]},{id:"yeu-quy-ban-be",title:"Yêu quý bạn bè",lessons:[{id:"dd2-yeu-quy-ban-be",title:"Bài 4: Yêu quý bạn bè",weeks:[8,10],learn:[{title:"Bạn bè quanh em",text:"Bạn bè cùng học, cùng chơi, cùng chia sẻ niềm vui, nỗi buồn.",example:"👫 🏫 🎈"},{title:"Thể hiện tình bạn",text:"Em quan tâm, giúp đỡ, chia sẻ với bạn; vui khi bạn vui, an ủi khi bạn buồn.",example:"🤝 🫂"},{title:"Không phân biệt",text:"Em chơi với tất cả các bạn, không chê bai, không bắt nạt ai.",example:"🙅 😢  ·  😊 🤗"}],practice:[{questions:[{id:"dd2-yeu-quy-ban-be-01",type:"tf",q:"Bạn bè cần quan tâm, giúp đỡ nhau.",emoji:"🤝",explain:"Quan tâm, giúp đỡ làm tình bạn thêm đẹp.",answer:!0},{id:"dd2-yeu-quy-ban-be-02",type:"mc",q:"Bạn đang buồn, em làm gì?",emoji:"😢",explain:"An ủi bạn là biết quan tâm.",options:["Hỏi han, an ủi bạn","Trêu cho bạn khóc","Mặc kệ, đi chơi tiếp"],answer:0},{id:"dd2-yeu-quy-ban-be-03",type:"tf",q:"Chỉ chơi với bạn học giỏi, không chơi với bạn khác.",emoji:"👫",explain:"Em chơi hòa đồng với tất cả các bạn.",answer:!1},{id:"dd2-yeu-quy-ban-be-04",type:"mc",q:"Bạn được điểm tốt, em nói gì?",emoji:"🎉",explain:"Vui với niềm vui của bạn là bạn tốt.",options:["Chắc bạn chép bài!","Chúc mừng bạn nhé!","Có gì đâu mà vui"],answer:1},{id:"dd2-yeu-quy-ban-be-05",type:"mc",q:"Việc nào là bắt nạt bạn?",emoji:"🚫",explain:"Xô đẩy, giật đồ là bắt nạt, em không làm.",options:["Xô đẩy, giật đồ của bạn","Rủ bạn cùng chơi nhảy dây","Cho bạn mượn bút để viết"],answer:0},{id:"dd2-yeu-quy-ban-be-06",type:"tf",q:"Chia sẻ đồ chơi với bạn giúp tình bạn thêm thân.",emoji:"🧸",explain:"Chia sẻ làm mọi người cùng vui.",answer:!0},{id:"dd2-yeu-quy-ban-be-07",type:"mc",q:"Bạn khuyết tật đến lớp mới. Em làm gì?",emoji:"🧑‍🦽",explain:"Em yêu quý, giúp đỡ mọi bạn, không phân biệt.",options:["Trêu chọc bạn mới đến","Tránh xa, không chơi với bạn","Làm quen, giúp đỡ bạn"],answer:2},{id:"dd2-yeu-quy-ban-be-08",type:"tf",q:"Nói xấu bạn sau lưng là việc làm của bạn tốt.",emoji:"🤐",explain:"Nói xấu bạn làm tình bạn rạn vỡ.",answer:!1},{id:"dd2-yeu-quy-ban-be-09",type:"mc",q:"Bạn hỏi mượn truyện. Em làm gì?",emoji:"📕",explain:"Cho mượn và nhắc nhẹ nhàng là biết chia sẻ.",options:["Từ chối thẳng thừng, không giải thích","Cho bạn mượn và nhắc bạn giữ gìn","Giấu truyện đi rồi nói là không có"],answer:1}]},{questions:[{id:"dd2-yeu-quy-ban-be-10",type:"match",q:"Nối tình huống với cách làm của bạn tốt.",emoji:"💞",explain:"Bạn tốt luôn quan tâm, chia sẻ.",pairs:[["Bạn bị ốm","Thăm hỏi, chép bài giúp bạn"],["Bạn được khen","Chúc mừng bạn"],["Bạn làm rơi đồ","Nhặt giúp bạn"],["Bạn buồn","An ủi bạn"]]},{id:"dd2-yeu-quy-ban-be-11",type:"multi",q:"Việc nào thể hiện em yêu quý bạn bè?",emoji:"😊",explain:"Đặt biệt danh xấu làm bạn buồn.",options:["Giúp bạn hiểu bài","Khen bạn khi bạn làm tốt","Đặt biệt danh xấu cho bạn","Rủ bạn lẻ loi chơi cùng"],answers:[0,1,3]},{id:"dd2-yeu-quy-ban-be-12",type:"mc",q:"Vì sao em cần yêu quý bạn bè?",emoji:"🌈",explain:"Tình bạn giúp em vui và tiến bộ.",options:["Để có bạn làm bài tập hộ mình mỗi ngày","Để cùng học tốt, chơi vui, giúp nhau tiến bộ","Để có người sai vặt, chạy việc cho mình"],answer:1},{id:"dd2-yeu-quy-ban-be-13",type:"tf",q:"Giúp bạn bằng cách cho bạn chép bài kiểm tra là bạn tốt.",emoji:"📝",explain:"Giúp bạn hiểu bài mới là giúp thật sự.",answer:!1},{id:"dd2-yeu-quy-ban-be-14",type:"order",q:"Sắp xếp các bước khi em và bạn hiểu lầm nhau.",emoji:"🤝",explain:"Bình tĩnh, lắng nghe, nói rõ rồi làm lành.",items:["Bình tĩnh","Nghe bạn nói","Nói điều mình nghĩ","Cùng làm lành"]},{id:"dd2-yeu-quy-ban-be-15",type:"mc",q:"Bạn mới đến lớp nói giọng khác vùng. Em làm gì?",emoji:"🗣️",explain:"Mỗi vùng có giọng nói riêng, em tôn trọng bạn.",options:["Làm quen, chơi cùng bạn","Nhại lại giọng nói của bạn","Không chơi, không nói với bạn"],answer:0},{id:"dd2-yeu-quy-ban-be-16",type:"tf",q:"Tôn trọng sở thích khác của bạn là biết yêu quý bạn.",emoji:"🎨",explain:"Mỗi bạn có sở thích riêng, em tôn trọng.",answer:!0},{id:"dd2-yeu-quy-ban-be-17",type:"mc",q:"Bạn làm em buồn. Em nên làm gì?",emoji:"💬",explain:"Nói nhẹ nhàng giúp bạn hiểu và sửa.",options:["Đánh lại bạn","Nói xấu bạn với cả lớp","Nói nhẹ nhàng cho bạn biết"],answer:2},{id:"dd2-yeu-quy-ban-be-18",type:"mc",q:"Bạn quên mang áo mưa khi trời mưa. Em làm gì?",emoji:"☂️",explain:"Giúp bạn lúc khó khăn là bạn tốt.",options:["Cười bạn vì bạn quên mang áo mưa","Lặng lẽ đi về một mình","Rủ bạn che chung hoặc báo cô"],answer:2}]},{questions:[{id:"dd2-yeu-quy-ban-be-19",type:"mc",q:"Một nhóm bạn trêu chọc Thảo vì Thảo đeo kính. Em làm gì?",emoji:"👓",explain:"Trêu chọc ngoại hình làm bạn tổn thương.",options:["Khuyên các bạn dừng lại, chơi cùng Thảo","Trêu cùng các bạn vì thấy mọi người đều trêu","Đứng xem, không nói gì rồi đi chỗ khác"],answer:0},{id:"dd2-yeu-quy-ban-be-20",type:"mc",q:"Bạn Dũng hay bị điểm thấp môn Toán. Em có thể giúp Dũng thế nào?",emoji:"➗",explain:"Cùng ôn bài giúp Dũng tiến bộ.",options:["Làm hết bài tập hộ Dũng","Cùng Dũng ôn bài giờ ra chơi","Chê Dũng học kém ngay trước cả lớp"],answer:1},{id:"dd2-yeu-quy-ban-be-21",type:"tf",q:"Ngọc giữ bí mật bạn tin tưởng kể, trừ khi điều đó làm bạn gặp nguy hiểm.",emoji:"🤫",explain:"Giữ lời là bạn tốt; khi bạn gặp nguy hiểm thì cần báo người lớn.",answer:!0},{id:"dd2-yeu-quy-ban-be-22",type:"multi",q:"Bạn bị ốm nghỉ học mấy ngày. Em có thể làm gì?",emoji:"🤒",explain:"Quan tâm, giúp bạn theo kịp bài là bạn tốt.",options:["Hỏi thăm bạn","Chép bài giúp bạn","Kể xấu bạn vắng mặt","Giảng lại bài khi bạn đi học"],answers:[0,1,3]},{id:"dd2-yeu-quy-ban-be-23",type:"mc",q:"Hai bạn thân của em giận nhau. Em làm gì?",emoji:"💔",explain:"Giúp bạn làm lành là quý bạn.",options:["Giúp hai bạn nói chuyện, làm lành","Chọn chơi với một bạn, bỏ bạn kia","Kể chuyện hai bạn giận nhau cho cả lớp"],answer:0},{id:"dd2-yeu-quy-ban-be-24",type:"order",q:"Sắp xếp việc em làm khi lỡ làm bạn buồn.",emoji:"🙇",explain:"Nhận lỗi, xin lỗi, hỏi han rồi làm lành.",items:["Nhận ra lỗi","Xin lỗi bạn","Hỏi bạn có ổn không","Cùng bạn chơi vui trở lại"]},{id:"dd2-yeu-quy-ban-be-25",type:"tf",q:"Bạn mặc áo cũ, An chê bạn trước lớp. An làm vậy là đúng.",emoji:"👕",explain:"Chê bai làm bạn tủi thân, An nên tôn trọng bạn.",answer:!1},{id:"dd2-yeu-quy-ban-be-26",type:"mc",q:"Bạn rủ em bỏ tiết đi chơi. Bạn tốt sẽ làm gì?",emoji:"🙅",explain:"Bạn tốt khuyên nhau điều đúng.",options:["Đi chơi cùng bạn cho vui","Giấu cô giáo giúp bạn","Từ chối, khuyên bạn vào lớp"],answer:2},{id:"dd2-yeu-quy-ban-be-27",type:"fill",q:"Bạn buồn, em hỏi han và … ủi bạn.",emoji:"🫂",explain:"Bạn buồn, em hỏi han và an ủi bạn.",answer:["an"],loose:!0}]}],challenge:{questions:[{id:"dd2-yeu-quy-ban-be-28",type:"match",q:"Nối việc làm với nhận xét.",emoji:"🌟",explain:"Em chọn cách làm của người bạn tốt.",pairs:[["Rủ bạn lẻ loi chơi cùng","Hòa đồng"],["Trêu chọc ngoại hình của bạn","Làm bạn tổn thương"],["Giúp bạn ôn bài","Giúp nhau tiến bộ"]]},{id:"dd2-yeu-quy-ban-be-29",type:"mc",q:"Trong giờ ra chơi, Khoa thấy bạn nhỏ lớp dưới bị lấy mất mũ và khóc. Khoa nên làm gì?",emoji:"🧢",explain:"Báo người lớn để bảo vệ bạn bị bắt nạt.",options:["Cười bạn rồi đi chỗ khác chơi","Báo thầy cô hoặc bác bảo vệ giúp bạn","Lấy thêm đồ của bạn ấy để trêu cho vui"],answer:1},{id:"dd2-yeu-quy-ban-be-19",type:"mc",q:"Một nhóm bạn trêu chọc Thảo vì Thảo đeo kính. Em làm gì?",emoji:"👓",explain:"Trêu chọc ngoại hình làm bạn tổn thương.",options:["Khuyên các bạn dừng lại, chơi cùng Thảo","Trêu cùng các bạn vì thấy mọi người đều trêu","Đứng xem, không nói gì rồi đi chỗ khác"],answer:0},{id:"dd2-yeu-quy-ban-be-20",type:"mc",q:"Bạn Dũng hay bị điểm thấp môn Toán. Em có thể giúp Dũng thế nào?",emoji:"➗",explain:"Cùng ôn bài giúp Dũng tiến bộ.",options:["Làm hết bài tập hộ Dũng","Cùng Dũng ôn bài giờ ra chơi","Chê Dũng học kém ngay trước cả lớp"],answer:1},{id:"dd2-yeu-quy-ban-be-22",type:"multi",q:"Bạn bị ốm nghỉ học mấy ngày. Em có thể làm gì?",emoji:"🤒",explain:"Quan tâm, giúp bạn theo kịp bài là bạn tốt.",options:["Hỏi thăm bạn","Chép bài giúp bạn","Kể xấu bạn vắng mặt","Giảng lại bài khi bạn đi học"],answers:[0,1,3]},{id:"dd2-yeu-quy-ban-be-25",type:"tf",q:"Bạn mặc áo cũ, An chê bạn trước lớp. An làm vậy là đúng.",emoji:"👕",explain:"Chê bai làm bạn tủi thân, An nên tôn trọng bạn.",answer:!1}]},summary:["Em yêu quý, quan tâm, giúp đỡ bạn bè.","Em chia sẻ niềm vui, nỗi buồn với bạn.","Em không chê bai, bắt nạt, phân biệt bạn."]}]},{id:"quy-trong-thoi-gian",title:"Quý trọng thời gian",lessons:[{id:"dd2-quy-trong-thoi-gian",title:"Bài 5: Quý trọng thời gian",weeks:[11,12],learn:[{title:"Thời gian quý giá",text:"Thời gian trôi qua không quay lại. Biết dùng thời gian giúp em học tốt, chơi vui.",example:"⏰ ⌛"},{title:"Quý trọng thời gian",text:"Em làm việc đúng giờ, không để việc hôm nay sang ngày mai, không la cà.",example:"✅ 🕐"},{title:"Không lãng phí",text:"Không mải chơi điện tử, xem ti vi quá lâu mà bỏ quên việc cần làm.",example:"📺 🎮 ⏳"}],practice:[{questions:[{id:"dd2-quy-trong-thoi-gian-01",type:"tf",q:"Thời gian đã trôi qua thì không quay lại được.",emoji:"⌛",explain:"Vì vậy em cần quý trọng thời gian.",answer:!0},{id:"dd2-quy-trong-thoi-gian-02",type:"mc",q:"Bạn nào biết quý trọng thời gian?",emoji:"⏰",explain:"Làm xong việc rồi mới chơi là quý trọng thời gian.",options:["Bạn Nam la cà trên đường đi học","Bạn Minh làm bài xong rồi mới chơi","Bạn Bình xem ti vi cả buổi chiều"],answer:1},{id:"dd2-quy-trong-thoi-gian-03",type:"tf",q:"Việc hôm nay để ngày mai làm cũng được.",emoji:"📅",explain:"Việc hôm nay em làm xong trong hôm nay.",answer:!1},{id:"dd2-quy-trong-thoi-gian-04",type:"mc",q:"La cà trên đường đi học có thể làm em thế nào?",emoji:"🚸",explain:"La cà làm mất thời gian, dễ muộn học.",options:["Bị muộn học","Đến lớp sớm hơn","Học giỏi hơn"],answer:0},{id:"dd2-quy-trong-thoi-gian-05",type:"mc",q:"Đồ vật nào giúp em biết giờ?",emoji:"🕰️",explain:"Đồng hồ cho em biết giờ để làm việc đúng giờ.",options:["Cái bát","Quả bóng","Đồng hồ"],answer:2},{id:"dd2-quy-trong-thoi-gian-06",type:"tf",q:"Chơi điện tử quá lâu là lãng phí thời gian.",emoji:"🎮",explain:"Em dành thời gian cho học tập, nghỉ ngơi, vận động.",answer:!0},{id:"dd2-quy-trong-thoi-gian-07",type:"mc",q:"Đi học đúng giờ giúp em điều gì?",emoji:"🏫",explain:"Đúng giờ giúp em theo kịp bài.",options:["Bị cô nhắc nhở","Mệt hơn","Không lỡ bài học"],answer:2},{id:"dd2-quy-trong-thoi-gian-08",type:"tf",q:"Dậy muộn rồi vội vàng là quý trọng thời gian.",emoji:"😴",explain:"Dậy đúng giờ giúp em không phải vội vàng.",answer:!1},{id:"dd2-quy-trong-thoi-gian-09",type:"mc",q:"Quý trọng thời gian là thế nào?",emoji:"✅",explain:"Biết dùng thời gian hợp lý là quý trọng thời gian.",options:["Làm việc đúng giờ, không lãng phí","Làm việc lúc nào thích cũng được","Chỉ chơi suốt ngày, không học bài"],answer:0}]},{questions:[{id:"dd2-quy-trong-thoi-gian-10",type:"match",q:"Nối việc làm với kết quả.",emoji:"⏱️",explain:"Dùng thời gian hợp lý mang lại kết quả tốt.",pairs:[["Làm bài đúng giờ","Có thời gian vui chơi"],["La cà khi đi học","Bị muộn học"],["Xem ti vi quá lâu","Không kịp học bài"]]},{id:"dd2-quy-trong-thoi-gian-11",type:"multi",q:"Việc nào là lãng phí thời gian?",emoji:"⌛",explain:"Ôn bài trước khi kiểm tra là dùng thời gian hợp lý.",options:["Mải chơi điện tử, quên học bài","Ngồi đợi mà không làm gì khi có việc cần làm","Ôn bài trước khi kiểm tra","La cà sau giờ tan học"],answers:[0,1,3]},{id:"dd2-quy-trong-thoi-gian-12",type:"mc",q:"Vì sao cần quý trọng thời gian?",emoji:"⏳",explain:"Thời gian rất quý, đã qua thì không quay lại.",options:["Vì chiếc đồng hồ ở nhà rất đắt tiền","Vì thời gian trôi qua không lấy lại được","Vì cô giáo bắt phải nói như vậy"],answer:1},{id:"dd2-quy-trong-thoi-gian-13",type:"tf",q:"Đến giờ hẹn với bạn, em đến đúng giờ.",emoji:"🤝",explain:"Đúng giờ là tôn trọng bạn và quý trọng thời gian.",answer:!0},{id:"dd2-quy-trong-thoi-gian-14",type:"order",q:"Sắp xếp thời gian buổi tối cho hợp lý.",emoji:"🌙",explain:"Ăn tối, học bài, chuẩn bị đồ dùng rồi ngủ đúng giờ.",items:["Ăn tối cùng gia đình","Học bài","Chuẩn bị đồ dùng ngày mai","Đi ngủ đúng giờ"]},{id:"dd2-quy-trong-thoi-gian-15",type:"mc",q:"Có 10 phút chờ xe buýt, em có thể làm gì có ích?",emoji:"🚌",explain:"Tận dụng thời gian chờ để ôn bài là quý thời gian.",options:["Đọc lại bài thơ vừa học","Xả rác ra khắp bến xe","Chạy ra lòng đường chơi"],answer:0},{id:"dd2-quy-trong-thoi-gian-16",type:"tf",q:"Quý trọng thời gian nghĩa là học suốt ngày, không nghỉ.",emoji:"⚖️",explain:"Em cần cả học, chơi và nghỉ ngơi hợp lý.",answer:!1},{id:"dd2-quy-trong-thoi-gian-17",type:"mc",q:"Bạn hẹn em 8 giờ đi thư viện. Em làm gì?",emoji:"📚",explain:"Đúng hẹn là giữ lời và tôn trọng bạn.",options:["Đến lúc nào cũng được","Quên luôn","Đến đúng 8 giờ"],answer:2},{id:"dd2-quy-trong-thoi-gian-18",type:"mc",q:"Làm nhiều việc một lúc, em nên làm gì?",emoji:"📋",explain:"Làm việc quan trọng trước giúp em không bị quên việc.",options:["Làm việc thích nhất trước rồi bỏ dở","Làm việc quan trọng trước","Không làm việc nào"],answer:1}]},{questions:[{id:"dd2-quy-trong-thoi-gian-19",type:"mc",q:"Hà đang làm bài thì bạn gọi đi chơi. Hà nên làm gì?",emoji:"📞",explain:"Làm xong việc rồi mới chơi là quý thời gian.",options:["Bỏ bài đi chơi ngay","Hẹn bạn làm xong bài sẽ chơi","Vừa làm vừa nói chuyện điện thoại"],answer:1},{id:"dd2-quy-trong-thoi-gian-20",type:"mc",q:"Tùng hay xem phim đến khuya nên sáng dậy muộn. Lời khuyên nào tốt?",emoji:"📺",explain:"Ngủ đúng giờ giúp Tùng dậy đúng giờ.",options:["Tắt ti vi đúng giờ để đi ngủ","Xem thêm vài tập phim nữa","Nghỉ học buổi sáng để ngủ bù"],answer:0},{id:"dd2-quy-trong-thoi-gian-21",type:"tf",q:"Lan làm xong bài sớm và dùng thời gian còn lại để đọc truyện, giúp mẹ việc nhà.",emoji:"📖",explain:"Lan biết dùng thời gian hợp lý.",answer:!0},{id:"dd2-quy-trong-thoi-gian-22",type:"multi",q:"Sáng chủ nhật, em có thể dùng thời gian thế nào cho có ích?",emoji:"☀️",explain:"Chơi điện thoại cả buổi là lãng phí thời gian.",options:["Giúp bố mẹ dọn nhà","Đọc sách","Chơi điện thoại cả buổi","Tập thể dục"],answers:[0,1,3]},{id:"dd2-quy-trong-thoi-gian-23",type:"mc",q:"Khoa hẹn bạn 3 giờ đá bóng nhưng đến 4 giờ mới tới. Khoa nên làm gì?",emoji:"⚽",explain:"Xin lỗi và sửa lỗi lần sau.",options:["Không nói gì, vào sân đá luôn","Trách bạn sao đến sớm thế","Xin lỗi bạn, lần sau đến đúng giờ"],answer:2},{id:"dd2-quy-trong-thoi-gian-24",type:"order",q:"Sắp xếp việc Vy làm buổi sáng để đi học đúng giờ.",emoji:"⏰",explain:"Dậy đúng giờ, vệ sinh, ăn sáng rồi đi học.",items:["Dậy khi chuông báo thức kêu","Vệ sinh cá nhân","Ăn sáng","Đi học"]},{id:"dd2-quy-trong-thoi-gian-25",type:"tf",q:"Phúc ngồi chơi điện thoại trong giờ học nhóm. Phúc đang quý trọng thời gian.",emoji:"📱",explain:"Phúc làm mất thời gian của cả nhóm.",answer:!1},{id:"dd2-quy-trong-thoi-gian-26",type:"mc",q:"Bài tập hôm nay nhiều, Chi nên làm gì?",emoji:"📚",explain:"Làm sớm, lần lượt giúp hoàn thành đúng giờ.",options:["Để dành sang ngày mai mới làm","Chơi trước, chờ đến khuya mới làm","Bắt đầu làm sớm, làm lần lượt từng bài"],answer:2},{id:"dd2-quy-trong-thoi-gian-27",type:"fill",q:"Em làm việc đúng … , không để việc hôm nay sang ngày mai.",emoji:"🕐",explain:"Em làm việc đúng giờ.",answer:["giờ","gio"],loose:!0}]}],challenge:{questions:[{id:"dd2-quy-trong-thoi-gian-28",type:"match",q:"Nối câu với ý nghĩa.",emoji:"💡",explain:"Câu nói hay nhắc em quý trọng thời gian.",pairs:[["Việc hôm nay chớ để ngày mai","Làm xong việc đúng ngày"],["Đúng hẹn","Giữ lời, tôn trọng người khác"],["La cà","Mất thời gian vô ích"]]},{id:"dd2-quy-trong-thoi-gian-29",type:"mc",q:"Nhóm của Minh hẹn làm bài lúc 2 giờ. Minh đến muộn khiến cả nhóm phải chờ. Điều gì xảy ra?",emoji:"👥",explain:"Đến muộn làm mất thời gian của người khác.",options:["Cả nhóm mất thời gian chờ đợi","Cả nhóm làm bài nhanh hơn","Không ảnh hưởng ai"],answer:0},{id:"dd2-quy-trong-thoi-gian-19",type:"mc",q:"Hà đang làm bài thì bạn gọi đi chơi. Hà nên làm gì?",emoji:"📞",explain:"Làm xong việc rồi mới chơi là quý thời gian.",options:["Bỏ bài đi chơi ngay","Hẹn bạn làm xong bài sẽ chơi","Vừa làm vừa nói chuyện điện thoại"],answer:1},{id:"dd2-quy-trong-thoi-gian-20",type:"mc",q:"Tùng hay xem phim đến khuya nên sáng dậy muộn. Lời khuyên nào tốt?",emoji:"📺",explain:"Ngủ đúng giờ giúp Tùng dậy đúng giờ.",options:["Tắt ti vi đúng giờ để đi ngủ","Xem thêm vài tập phim nữa","Nghỉ học buổi sáng để ngủ bù"],answer:0},{id:"dd2-quy-trong-thoi-gian-23",type:"mc",q:"Khoa hẹn bạn 3 giờ đá bóng nhưng đến 4 giờ mới tới. Khoa nên làm gì?",emoji:"⚽",explain:"Xin lỗi và sửa lỗi lần sau.",options:["Không nói gì, vào sân đá luôn","Trách bạn sao đến sớm thế","Xin lỗi bạn, lần sau đến đúng giờ"],answer:2},{id:"dd2-quy-trong-thoi-gian-25",type:"tf",q:"Phúc ngồi chơi điện thoại trong giờ học nhóm. Phúc đang quý trọng thời gian.",emoji:"📱",explain:"Phúc làm mất thời gian của cả nhóm.",answer:!1}]},summary:["Thời gian trôi qua không quay lại.","Em làm việc đúng giờ, việc hôm nay không để ngày mai.","Quý trọng thời gian giúp em học tốt và có thời gian vui chơi."]},{id:"dd2-thoi-gian-bieu",title:"Bài 6: Em làm việc theo thời gian biểu",weeks:[13,14],learn:[{title:"Thời gian biểu",text:"Thời gian biểu là bảng ghi giờ làm các việc trong ngày.",example:"🕖 ăn sáng  ·  🕗 đi học  ·  🕘 học bài"},{title:"Lập thời gian biểu",text:"Em ghi các việc cần làm và giờ làm mỗi việc. Có giờ học, giờ chơi, giờ nghỉ.",example:"📝 ⏰"},{title:"Làm theo thời gian biểu",text:"Em làm đúng giờ đã ghi. Nếu có việc đột xuất, em sắp xếp lại cho hợp lý.",example:"✅ 🔁"}],practice:[{questions:[{id:"dd2-thoi-gian-bieu-01",type:"mc",q:"Thời gian biểu là gì?",emoji:"📝",explain:"Thời gian biểu ghi giờ làm từng việc.",options:["Một quyển truyện tranh có nhiều hình","Bảng ghi giờ làm các việc trong ngày","Một trò chơi trên điện thoại"],answer:1},{id:"dd2-thoi-gian-bieu-02",type:"tf",q:"Thời gian biểu giúp em làm việc đúng giờ.",emoji:"⏰",explain:"Có thời gian biểu, em biết lúc nào làm gì.",answer:!0},{id:"dd2-thoi-gian-bieu-03",type:"tf",q:"Thời gian biểu chỉ có giờ học, không có giờ chơi.",emoji:"🎈",explain:"Thời gian biểu cần có cả giờ học, giờ chơi, giờ nghỉ.",answer:!1},{id:"dd2-thoi-gian-bieu-04",type:"mc",q:"Việc nào nên có trong thời gian biểu của em?",emoji:"📚",explain:"Giờ học bài là việc cần có.",options:["Giờ học bài","Giờ thức khuya xem phim","Giờ chơi điện tử cả tối"],answer:0},{id:"dd2-thoi-gian-bieu-05",type:"mc",q:"Ai nên lập thời gian biểu cho em?",emoji:"👨‍👩‍👧",explain:"Em tự lập và nhờ bố mẹ góp ý cho hợp lý.",options:["Bạn cùng lớp lập hộ em","Không ai cả, không cần lập","Em tự lập, nhờ bố mẹ góp ý"],answer:2},{id:"dd2-thoi-gian-bieu-06",type:"tf",q:"Lập thời gian biểu xong thì để đó, không cần làm theo.",emoji:"📋",explain:"Lập xong phải làm theo mới có ích.",answer:!1},{id:"dd2-thoi-gian-bieu-07",type:"mc",q:"Thời gian biểu nên dán ở đâu?",emoji:"📌",explain:"Dán chỗ dễ thấy giúp em nhớ làm theo.",options:["Trong ngăn kéo khóa kín","Ở góc học tập, dễ nhìn thấy","Dưới gầm giường"],answer:1},{id:"dd2-thoi-gian-bieu-08",type:"tf",q:"Làm theo thời gian biểu giúp em không quên việc.",emoji:"✅",explain:"Thời gian biểu nhắc em việc cần làm.",answer:!0},{id:"dd2-thoi-gian-bieu-09",type:"mc",q:"Buổi tối em nên đi ngủ lúc nào?",emoji:"🌙",explain:"Ngủ đúng giờ giúp em đủ giấc.",options:["Khi nào thấy buồn ngủ quá thì ngủ","Đúng giờ ghi trong thời gian biểu","Sau nửa đêm, khi xem xong phim"],answer:1}]},{questions:[{id:"dd2-thoi-gian-bieu-10",type:"order",q:"Sắp xếp các việc buổi sáng trong thời gian biểu.",emoji:"🌅",explain:"Buổi sáng: dậy, vệ sinh, ăn sáng, đi học.",items:["Thức dậy","Vệ sinh cá nhân","Ăn sáng","Đến trường"]},{id:"dd2-thoi-gian-bieu-11",type:"match",q:"Nối giờ với việc làm phù hợp.",emoji:"🕐",explain:"Mỗi việc làm vào giờ phù hợp.",pairs:[["6 giờ sáng","Thức dậy"],["Buổi trưa","Ăn trưa, nghỉ trưa"],["Tối","Học bài"],["9 giờ tối","Đi ngủ"]]},{id:"dd2-thoi-gian-bieu-12",type:"multi",q:"Một thời gian biểu tốt có gì?",emoji:"📝",explain:"Chơi điện thoại đến khuya làm thiếu ngủ.",options:["Giờ học","Giờ vui chơi, vận động","Giờ ngủ đủ giấc","Giờ chơi điện thoại đến khuya"],answers:[0,1,2]},{id:"dd2-thoi-gian-bieu-13",type:"mc",q:"Vì sao thời gian biểu cần có giờ nghỉ ngơi?",emoji:"😌",explain:"Nghỉ ngơi hợp lý giúp em khỏe và học tốt.",options:["Để em không mệt, học tốt hơn","Để em lười hơn, ngủ nhiều hơn","Để em không phải học bài nữa"],answer:0},{id:"dd2-thoi-gian-bieu-14",type:"tf",q:"Hôm nay có khách đến chơi, em có thể sắp xếp lại giờ học cho hợp lý.",emoji:"🔁",explain:"Có việc đột xuất, em linh hoạt sắp xếp lại.",answer:!0},{id:"dd2-thoi-gian-bieu-15",type:"mc",q:"Bạn Nam không có thời gian biểu, thường quên làm bài. Nam nên làm gì?",emoji:"📋",explain:"Thời gian biểu giúp Nam nhớ việc cần làm.",options:["Nhờ bạn làm bài tập hộ mỗi ngày","Thôi không cần làm bài nữa","Lập thời gian biểu và làm theo"],answer:2},{id:"dd2-thoi-gian-bieu-16",type:"tf",q:"Thời gian biểu của mọi bạn đều phải giống hệt nhau.",emoji:"👫",explain:"Mỗi bạn có thể có thời gian biểu khác nhau cho phù hợp.",answer:!1},{id:"dd2-thoi-gian-bieu-17",type:"mc",q:"Theo thời gian biểu là giờ học nhưng phim hoạt hình đang chiếu. Em làm gì?",emoji:"📺",explain:"Làm đúng thời gian biểu là tự giác.",options:["Xem hết phim rồi tính","Vừa xem vừa học","Tắt ti vi để học bài"],answer:2},{id:"dd2-thoi-gian-bieu-18",type:"mc",q:"Cuối tuần, thời gian biểu của em có thể có thêm gì?",emoji:"🏞️",explain:"Cuối tuần có thể có việc nhà, vui chơi cùng gia đình.",options:["Giúp việc nhà, đi chơi cùng gia đình","Ngủ cả ngày, không làm việc gì","Ngồi xem điện thoại suốt từ sáng đến tối"],answer:0}]},{questions:[{id:"dd2-thoi-gian-bieu-19",type:"mc",q:"Vy lập thời gian biểu nhưng chỉ làm theo được hai ngày. Vy nên làm gì?",emoji:"💪",explain:"Kiên trì giúp hình thành thói quen tốt.",options:["Xé thời gian biểu đi cho xong","Kiên trì làm theo, nhờ bố mẹ nhắc","Lập cái khác rồi lại bỏ giữa chừng"],answer:1},{id:"dd2-thoi-gian-bieu-20",type:"mc",q:"Thời gian biểu của Bình ghi: 7 giờ tối học bài. Nhưng 7 giờ Bình vẫn còn xem ti vi. Bình nên làm gì?",emoji:"📺",explain:"Làm đúng giờ đã ghi giúp Bình học tốt.",options:["Tắt ti vi, ngồi vào bàn học","Xem tiếp, 10 giờ đêm mới học","Bỏ luôn bài học hôm nay"],answer:0},{id:"dd2-thoi-gian-bieu-21",type:"tf",q:"Ngọc làm theo thời gian biểu nên luôn hoàn thành bài và có thời gian chơi.",emoji:"🌟",explain:"Thời gian biểu giúp Ngọc sắp xếp việc hợp lý.",answer:!0},{id:"dd2-thoi-gian-bieu-22",type:"multi",q:"Khoa muốn lập thời gian biểu. Khoa cần làm gì?",emoji:"📝",explain:"Mỗi người có thời gian biểu phù hợp riêng, không chép của bạn.",options:["Liệt kê các việc trong ngày","Ghi giờ cho từng việc","Nhờ bố mẹ góp ý","Chép thời gian biểu của bạn"],answers:[0,1,2]},{id:"dd2-thoi-gian-bieu-23",type:"order",q:"Sắp xếp các bước lập thời gian biểu.",emoji:"📌",explain:"Liệt kê, ghi giờ, góp ý rồi làm theo.",items:["Liệt kê việc cần làm","Ghi giờ cho mỗi việc","Nhờ người lớn góp ý","Dán lên góc học tập và làm theo"]},{id:"dd2-thoi-gian-bieu-24",type:"mc",q:"Hôm nay ông bà đến chơi đúng giờ học bài. Cách nào hợp lý?",emoji:"👴",explain:"Linh hoạt sắp xếp lại nhưng vẫn hoàn thành việc học.",options:["Không chào ông bà, đi vào phòng học ngay","Bỏ luôn việc học bài của ngày hôm nay","Chào ông bà, trò chuyện rồi học bài sau đó"],answer:2},{id:"dd2-thoi-gian-bieu-25",type:"tf",q:"Thời gian biểu có giờ ngủ trưa giúp em đỡ mệt buổi chiều.",emoji:"💤",explain:"Nghỉ trưa giúp em khỏe hơn.",answer:!0},{id:"dd2-thoi-gian-bieu-26",type:"tf",q:"Dũng ghi thời gian biểu: chơi điện tử từ 7 giờ đến 10 giờ tối. Đó là thời gian biểu hợp lý.",emoji:"🎮",explain:"Chơi điện tử quá lâu làm mất giờ học và giờ ngủ.",answer:!1},{id:"dd2-thoi-gian-bieu-27",type:"fill",q:"Bảng ghi giờ làm các việc trong ngày gọi là thời gian …",emoji:"📝",explain:"Đó là thời gian biểu.",answer:["biểu","bieu"],loose:!0}]}],challenge:{questions:[{id:"dd2-thoi-gian-bieu-28",type:"match",q:"Nối tình huống với cách làm phù hợp.",emoji:"📋",explain:"Em làm theo thời gian biểu và linh hoạt khi cần.",pairs:[["Đến giờ học, phim đang chiếu","Tắt ti vi đi học"],["Có khách đến chơi","Sắp xếp lại giờ học"],["Quên làm theo thời gian biểu","Nhờ bố mẹ nhắc"]]},{id:"dd2-thoi-gian-bieu-29",type:"mc",q:"Phúc thấy mình luôn thiếu thời gian chơi. Phúc nên làm gì?",emoji:"🔍",explain:"Bớt việc lãng phí giúp có thêm thời gian chơi.",options:["Bỏ giờ học bài để có thêm giờ chơi","Xem lại thời gian biểu, bớt việc lãng phí","Bỏ bớt giờ ngủ, thức thật khuya để chơi"],answer:1},{id:"dd2-thoi-gian-bieu-19",type:"mc",q:"Vy lập thời gian biểu nhưng chỉ làm theo được hai ngày. Vy nên làm gì?",emoji:"💪",explain:"Kiên trì giúp hình thành thói quen tốt.",options:["Xé thời gian biểu đi cho xong","Kiên trì làm theo, nhờ bố mẹ nhắc","Lập cái khác rồi lại bỏ giữa chừng"],answer:1},{id:"dd2-thoi-gian-bieu-20",type:"mc",q:"Thời gian biểu của Bình ghi: 7 giờ tối học bài. Nhưng 7 giờ Bình vẫn còn xem ti vi. Bình nên làm gì?",emoji:"📺",explain:"Làm đúng giờ đã ghi giúp Bình học tốt.",options:["Tắt ti vi, ngồi vào bàn học","Xem tiếp, 10 giờ đêm mới học","Bỏ luôn bài học hôm nay"],answer:0},{id:"dd2-thoi-gian-bieu-22",type:"multi",q:"Khoa muốn lập thời gian biểu. Khoa cần làm gì?",emoji:"📝",explain:"Mỗi người có thời gian biểu phù hợp riêng, không chép của bạn.",options:["Liệt kê các việc trong ngày","Ghi giờ cho từng việc","Nhờ bố mẹ góp ý","Chép thời gian biểu của bạn"],answers:[0,1,2]},{id:"dd2-thoi-gian-bieu-24",type:"mc",q:"Hôm nay ông bà đến chơi đúng giờ học bài. Cách nào hợp lý?",emoji:"👴",explain:"Linh hoạt sắp xếp lại nhưng vẫn hoàn thành việc học.",options:["Không chào ông bà, đi vào phòng học ngay","Bỏ luôn việc học bài của ngày hôm nay","Chào ông bà, trò chuyện rồi học bài sau đó"],answer:2}]},summary:["Thời gian biểu giúp em làm việc đúng giờ.","Thời gian biểu có giờ học, giờ chơi, giờ nghỉ.","Em làm theo thời gian biểu mỗi ngày."]}]},{id:"nhan-loi-sua-loi",title:"Nhận lỗi và sửa lỗi",lessons:[{id:"dd2-biet-nhan-loi",title:"Bài 7: Biết nhận lỗi",weeks:[15,16],learn:[{title:"Ai cũng có lúc mắc lỗi",text:"Ai cũng có thể mắc lỗi. Điều quan trọng là biết nhận lỗi.",example:"🙂 🙇"},{title:"Nhận lỗi thế nào?",text:"Em nói thật điều mình đã làm sai và xin lỗi người bị ảnh hưởng.",example:"💬 “Mình xin lỗi, mình đã làm rơi bút của bạn.”"},{title:"Không đổ lỗi",text:"Em không đổ lỗi cho người khác, không nói dối để che giấu lỗi.",example:"🙅 👉"}],practice:[{questions:[{id:"dd2-biet-nhan-loi-01",type:"tf",q:"Ai cũng có thể mắc lỗi.",emoji:"🙂",explain:"Mắc lỗi không đáng sợ, quan trọng là biết nhận lỗi.",answer:!0},{id:"dd2-biet-nhan-loi-02",type:"mc",q:"Khi mắc lỗi, em nên làm gì?",emoji:"🙇",explain:"Nhận lỗi, xin lỗi là việc làm đúng.",options:["Đổ lỗi cho bạn khác","Nhận lỗi và xin lỗi","Giấu đi, không nói ai"],answer:1},{id:"dd2-biet-nhan-loi-03",type:"tf",q:"Đổ lỗi cho em nhỏ để mình không bị nhắc là đúng.",emoji:"👉",explain:"Lỗi của mình thì mình nhận.",answer:!1},{id:"dd2-biet-nhan-loi-04",type:"mc",q:"Câu nào là lời xin lỗi?",emoji:"💬",explain:"Lời xin lỗi kèm lời hứa sửa lỗi.",options:["Mình xin lỗi, mình sẽ cẩn thận hơn","Tại bạn để đồ ở đấy chứ bộ","Có gì đâu mà bạn phải buồn thế"],answer:0},{id:"dd2-biet-nhan-loi-05",type:"mc",q:"Biết nhận lỗi giúp em thế nào?",emoji:"❤️",explain:"Nhận lỗi giúp em tiến bộ và được tin yêu.",options:["Bị mọi người xa lánh, không ai chơi","Chẳng thay đổi gì, vẫn như cũ thôi","Được mọi người tin yêu, tiến bộ hơn"],answer:2},{id:"dd2-biet-nhan-loi-06",type:"tf",q:"Che giấu lỗi bằng cách nói dối sẽ làm mọi người mất lòng tin.",emoji:"🤥",explain:"Nói dối làm mất lòng tin của mọi người.",answer:!0},{id:"dd2-biet-nhan-loi-07",type:"mc",q:"Em làm hỏng đồ chơi của em trai. Em nói gì?",emoji:"🧸",explain:"Nhận lỗi và hứa sửa lỗi là đúng.",options:["Đồ chơi của em tự hỏng đấy, không phải anh","Ai bảo em để đồ chơi ở đó","Anh xin lỗi em, anh sẽ sửa lại cho em"],answer:2},{id:"dd2-biet-nhan-loi-08",type:"tf",q:"Người dám nhận lỗi là người dũng cảm.",emoji:"🦁",explain:"Cần dũng cảm mới nhận lỗi được.",answer:!0},{id:"dd2-biet-nhan-loi-09",type:"mc",q:"Bạn nào biết nhận lỗi?",emoji:"👕",explain:"Xin lỗi là biết nhận lỗi.",options:["Bạn Vy xin lỗi vì làm bẩn áo bạn","Bạn Khoa nói bạn tự làm bẩn áo","Bạn Dũng giả vờ không biết"],answer:0}]},{questions:[{id:"dd2-biet-nhan-loi-10",type:"match",q:"Nối lỗi với lời xin lỗi phù hợp.",emoji:"💬",explain:"Lời xin lỗi phù hợp với từng người, từng lỗi.",pairs:[["Đến lớp muộn","Em xin lỗi cô vì đến muộn ạ"],["Va vào bạn","Mình xin lỗi, bạn có đau không?"],["Làm vỡ cốc của mẹ","Con xin lỗi mẹ, con sẽ cẩn thận hơn ạ"]]},{id:"dd2-biet-nhan-loi-11",type:"multi",q:"Việc nào là biết nhận lỗi?",emoji:"✅",explain:"Đổ lỗi cho người khác không phải là nhận lỗi.",options:["Nói thật điều mình làm sai","Xin lỗi người bị ảnh hưởng","Đổ lỗi cho người khác","Hứa không mắc lại"],answers:[0,1,3]},{id:"dd2-biet-nhan-loi-12",type:"mc",q:"Vì sao không nên đổ lỗi cho người khác?",emoji:"😢",explain:"Đổ lỗi làm người khác bị oan.",options:["Vì đổ lỗi sẽ được khen","Vì người khác bị oan, buồn","Vì đằng nào cũng không ai biết"],answer:1},{id:"dd2-biet-nhan-loi-13",type:"tf",q:"Chỉ cần nhận lỗi khi có người nhìn thấy.",emoji:"👀",explain:"Dù không ai thấy, em vẫn nhận lỗi.",answer:!1},{id:"dd2-biet-nhan-loi-14",type:"order",q:"Sắp xếp các bước nhận lỗi.",emoji:"🙇",explain:"Nhận ra, nói thật, xin lỗi và hứa sửa.",items:["Nhận ra mình sai","Nói thật điều đã xảy ra","Xin lỗi người bị ảnh hưởng","Hứa sửa lỗi"]},{id:"dd2-biet-nhan-loi-15",type:"mc",q:"Xin lỗi thế nào cho chân thành?",emoji:"👀",explain:"Lời xin lỗi chân thành giúp bạn cảm nhận được.",options:["Nhìn vào bạn, nói rõ ràng, nhẹ nhàng","Nói thật nhỏ một câu rồi chạy đi","Vừa nói vừa cười trêu, nhìn chỗ khác"],answer:0},{id:"dd2-biet-nhan-loi-16",type:"tf",q:"Nhận lỗi muộn vẫn tốt hơn không nhận lỗi.",emoji:"🕰️",explain:"Biết nhận lỗi, dù muộn, vẫn là điều tốt.",answer:!0},{id:"dd2-biet-nhan-loi-17",type:"mc",q:"Nếu lỡ làm hỏng đồ của bạn, ngoài xin lỗi em nên làm gì?",emoji:"🔧",explain:"Xin lỗi và sửa chữa là có trách nhiệm.",options:["Không làm gì thêm nữa","Làm hỏng thêm cho đều","Tìm cách sửa hoặc đền bù"],answer:2},{id:"dd2-biet-nhan-loi-18",type:"tf",q:"Bị nhắc vì làm sai, em giận dỗi, đóng cửa không nói chuyện là biết nhận lỗi.",emoji:"🚪",explain:"Em lắng nghe, nhận lỗi và sửa lỗi.",answer:!1}]},{questions:[{id:"dd2-biet-nhan-loi-19",type:"mc",q:"Nam đá bóng làm vỡ chậu hoa trước lớp. Không ai thấy. Nam nên làm gì?",emoji:"🪴",explain:"Nhận lỗi dù không ai thấy là trung thực.",options:["Lặng lẽ bỏ đi","Báo cô và xin lỗi","Nói do gió làm đổ"],answer:1},{id:"dd2-biet-nhan-loi-20",type:"mc",q:"Lan mượn truyện của Hà và làm rách bìa. Lan nên nói gì?",emoji:"📕",explain:"Nói thật, xin lỗi và sửa lỗi.",options:["Truyện này cũ rồi mà, rách thêm một chút có sao đâu","Mình xin lỗi, mình làm rách bìa, mình sẽ dán lại cho bạn","Không nói gì, lặng lẽ trả lại truyện cho Hà là xong"],answer:1},{id:"dd2-biet-nhan-loi-21",type:"tf",q:"Mẹ hỏi ai làm đổ nước, Tùng nói thật là mình làm và lấy khăn lau. Tùng làm đúng.",emoji:"💧",explain:"Nói thật và sửa lỗi là đúng.",answer:!0},{id:"dd2-biet-nhan-loi-22",type:"multi",q:"Em lỡ nói điều làm bạn buồn. Em có thể làm gì?",emoji:"💔",explain:"Xin lỗi, hỏi han và làm lành là đúng.",options:["Xin lỗi bạn","Hỏi bạn có buồn không","Nói tiếp cho bạn buồn hơn","Rủ bạn chơi cùng để làm lành"],answers:[0,1,3]},{id:"dd2-biet-nhan-loi-23",type:"mc",q:"Cả nhóm bị cô nhắc vì làm ồn, trong đó có em. Em làm gì?",emoji:"🤫",explain:"Nhận phần lỗi của mình là trung thực.",options:["Nhận phần lỗi của mình, giữ trật tự","Nói chỉ các bạn khác làm ồn","Im lặng rồi tiếp tục nói chuyện"],answer:0},{id:"dd2-biet-nhan-loi-24",type:"order",q:"Sắp xếp việc Khoa làm khi lỡ va vào bạn làm bạn ngã.",emoji:"🤕",explain:"Đỡ bạn, xin lỗi, hỏi han, báo cô khi cần.",items:["Đỡ bạn dậy","Xin lỗi bạn","Hỏi bạn có đau không","Báo cô nếu bạn bị đau"]},{id:"dd2-biet-nhan-loi-25",type:"tf",q:"Ngọc làm sai nhưng sợ bị nhắc nên nói là bạn bên cạnh làm. Ngọc làm vậy là đúng.",emoji:"😟",explain:"Đổ lỗi cho bạn làm bạn bị oan.",answer:!1},{id:"dd2-biet-nhan-loi-26",type:"mc",q:"Bạn xin lỗi em vì làm rơi bút của em. Em nên làm gì?",emoji:"🤗",explain:"Tha thứ khi bạn biết nhận lỗi.",options:["Bắt bạn đền bút mới ngay","Mách cô và không chơi với bạn","Tha lỗi và cảm ơn bạn đã xin lỗi"],answer:2},{id:"dd2-biet-nhan-loi-27",type:"fill",q:"Biết nhận … là nói thật và xin lỗi khi mình làm sai.",emoji:"🙇",explain:"Biết nhận lỗi là nói thật và xin lỗi.",answer:["lỗi","loi"],loose:!0}]}],challenge:{questions:[{id:"dd2-biet-nhan-loi-28",type:"match",q:"Nối việc làm với nhận xét.",emoji:"⚖️",explain:"Trung thực và rộng lượng là điều tốt.",pairs:[["Nhận lỗi dù không ai thấy","Trung thực"],["Đổ lỗi cho bạn","Làm bạn bị oan"],["Tha lỗi cho bạn","Rộng lượng"]]},{id:"dd2-biet-nhan-loi-29",type:"mc",q:"Minh hứa trả sách cho bạn hôm thứ hai nhưng quên. Minh nên làm gì?",emoji:"📚",explain:"Nhận lỗi và sửa ngay là đúng.",options:["Không trả nữa, giữ luôn sách","Nói bạn nhớ nhầm ngày hẹn","Xin lỗi và trả ngay hôm sau"],answer:2},{id:"dd2-biet-nhan-loi-19",type:"mc",q:"Nam đá bóng làm vỡ chậu hoa trước lớp. Không ai thấy. Nam nên làm gì?",emoji:"🪴",explain:"Nhận lỗi dù không ai thấy là trung thực.",options:["Lặng lẽ bỏ đi","Báo cô và xin lỗi","Nói do gió làm đổ"],answer:1},{id:"dd2-biet-nhan-loi-20",type:"mc",q:"Lan mượn truyện của Hà và làm rách bìa. Lan nên nói gì?",emoji:"📕",explain:"Nói thật, xin lỗi và sửa lỗi.",options:["Truyện này cũ rồi mà, rách thêm một chút có sao đâu","Mình xin lỗi, mình làm rách bìa, mình sẽ dán lại cho bạn","Không nói gì, lặng lẽ trả lại truyện cho Hà là xong"],answer:1},{id:"dd2-biet-nhan-loi-22",type:"multi",q:"Em lỡ nói điều làm bạn buồn. Em có thể làm gì?",emoji:"💔",explain:"Xin lỗi, hỏi han và làm lành là đúng.",options:["Xin lỗi bạn","Hỏi bạn có buồn không","Nói tiếp cho bạn buồn hơn","Rủ bạn chơi cùng để làm lành"],answers:[0,1,3]},{id:"dd2-biet-nhan-loi-25",type:"tf",q:"Ngọc làm sai nhưng sợ bị nhắc nên nói là bạn bên cạnh làm. Ngọc làm vậy là đúng.",emoji:"😟",explain:"Đổ lỗi cho bạn làm bạn bị oan.",answer:!1}]},summary:["Ai cũng có thể mắc lỗi.","Biết nhận lỗi là nói thật và xin lỗi.","Em không đổ lỗi, không che giấu lỗi."]},{id:"dd2-sua-loi",title:"Bài 8: Sửa lỗi để tiến bộ",weeks:[17,18],learn:[{title:"Sửa lỗi",text:"Nhận lỗi rồi, em sửa lỗi bằng việc làm cụ thể.",example:"🔧 💪"},{title:"Không lặp lại",text:"Em ghi nhớ để không mắc lại lỗi cũ.",example:"🧠 ✅"},{title:"Tha thứ",text:"Khi bạn biết nhận lỗi và sửa lỗi, em vui vẻ tha thứ cho bạn.",example:"🤗 💞"}],practice:[{questions:[{id:"dd2-sua-loi-01",type:"tf",q:"Nhận lỗi xong cần sửa lỗi.",emoji:"🔧",explain:"Sửa lỗi giúp em tiến bộ.",answer:!0},{id:"dd2-sua-loi-02",type:"mc",q:"Làm bẩn bàn học của bạn, em sửa lỗi thế nào?",emoji:"🧽",explain:"Lau sạch là sửa lỗi.",options:["Lau sạch bàn cho bạn","Để nguyên bàn bẩn đó","Đổi sang chỗ ngồi khác"],answer:0},{id:"dd2-sua-loi-03",type:"tf",q:"Đã xin lỗi rồi thì mắc lại lỗi đó cũng không sao.",emoji:"🔁",explain:"Em cố gắng không mắc lại lỗi cũ.",answer:!1},{id:"dd2-sua-loi-04",type:"mc",q:"Quên làm bài tập, em sửa lỗi bằng cách nào?",emoji:"📝",explain:"Làm bù và ghi nhớ là sửa lỗi đúng.",options:["Chép vội bài của bạn trước giờ học","Làm bù và ghi nhớ làm bài đúng giờ","Nói dối với cô là em đã làm rồi"],answer:1},{id:"dd2-sua-loi-05",type:"mc",q:"Sửa lỗi giúp em thế nào?",emoji:"📈",explain:"Biết sửa lỗi giúp em tiến bộ.",options:["Tiến bộ hơn mỗi ngày","Kém đi","Bị mọi người ghét"],answer:0},{id:"dd2-sua-loi-06",type:"tf",q:"Bạn đã xin lỗi, em vui vẻ tha thứ cho bạn.",emoji:"🤗",explain:"Tha thứ giúp tình bạn tốt đẹp.",answer:!0},{id:"dd2-sua-loi-07",type:"mc",q:"Làm vỡ lọ hoa của cô, em có thể sửa lỗi thế nào?",emoji:"🏺",explain:"Xin lỗi và làm theo hướng dẫn của cô để an toàn.",options:["Vội vàng nhặt mảnh vỡ bằng tay không cho nhanh","Giấu mảnh vỡ dưới gầm bàn để cô không biết","Xin lỗi cô, cùng dọn dẹp an toàn theo hướng dẫn"],answer:2},{id:"dd2-sua-loi-08",type:"tf",q:"Chỉ người lớn mới cần sửa lỗi.",emoji:"🧒",explain:"Ai mắc lỗi cũng cần sửa lỗi.",answer:!1},{id:"dd2-sua-loi-09",type:"mc",q:"Lỡ nói lời làm bạn buồn, em sửa lỗi bằng cách nào?",emoji:"💬",explain:"Lời tử tế giúp hàn gắn tình bạn.",options:["Tiếp tục trêu cho bạn buồn thêm","Xin lỗi và nói lời tử tế với bạn","Tránh mặt bạn mãi, không nói gì với bạn"],answer:1}]},{questions:[{id:"dd2-sua-loi-10",type:"match",q:"Nối lỗi với cách sửa lỗi.",emoji:"🔧",explain:"Mỗi lỗi có cách sửa phù hợp.",pairs:[["Làm rách sách bạn","Dán lại sách cho bạn"],["Đến lớp muộn","Dậy sớm hơn"],["Vứt rác bừa bãi","Nhặt rác bỏ vào thùng"],["Nói to trong thư viện","Nói nhỏ, giữ yên lặng"]]},{id:"dd2-sua-loi-11",type:"multi",q:"Việc nào giúp em không mắc lại lỗi cũ?",emoji:"🧠",explain:"Ghi nhớ, nhờ nhắc, đặt lời nhắc giúp em không mắc lại.",options:["Ghi nhớ điều đã sai","Nhờ người thân nhắc nhở","Quên ngay chuyện đã xảy ra","Đặt lời nhắc ở góc học tập"],answers:[0,1,3]},{id:"dd2-sua-loi-12",type:"mc",q:"Vì sao cần sửa lỗi sau khi nhận lỗi?",emoji:"💡",explain:"Sửa lỗi mới khắc phục được điều sai.",options:["Để được bố mẹ thưởng quà","Để khắc phục điều sai và tiến bộ","Để lần sau khỏi phải xin lỗi ai nữa"],answer:1},{id:"dd2-sua-loi-13",type:"tf",q:"Tha thứ cho bạn khi bạn biết lỗi là việc làm tốt.",emoji:"🕊️",explain:"Tha thứ giúp bạn có cơ hội sửa sai.",answer:!0},{id:"dd2-sua-loi-14",type:"order",q:"Sắp xếp các bước từ mắc lỗi đến tiến bộ.",emoji:"📈",explain:"Nhận lỗi, sửa lỗi, không mắc lại thì em tiến bộ.",items:["Mắc lỗi","Nhận lỗi","Sửa lỗi","Không mắc lại","Tiến bộ hơn"]},{id:"dd2-sua-loi-15",type:"mc",q:"Bạn đã sửa lỗi nhưng em vẫn nhắc mãi lỗi cũ của bạn. Như vậy là thế nào?",emoji:"😞",explain:"Em nên tha thứ và động viên bạn.",options:["Chưa tốt, làm bạn buồn","Rất tốt, nên nhắc mãi","Giúp bạn vui hơn mỗi ngày"],answer:0},{id:"dd2-sua-loi-16",type:"tf",q:"Mỗi lần mắc lỗi là một lần em học được điều mới.",emoji:"🌱",explain:"Biết sửa lỗi giúp em lớn lên.",answer:!0},{id:"dd2-sua-loi-17",type:"mc",q:"Chữ viết cẩu thả bị cô nhắc. Em sửa lỗi thế nào?",emoji:"✍️",explain:"Kiên trì luyện viết sẽ tiến bộ.",options:["Viết nhanh hơn nữa cho xong bài","Thôi không viết nữa cho đỡ mỏi tay","Luyện viết cẩn thận hơn mỗi ngày"],answer:2},{id:"dd2-sua-loi-18",type:"tf",q:"Sửa lỗi cần làm ngay, càng để lâu càng tốt.",emoji:"⏰",explain:"Sửa lỗi càng sớm càng tốt.",answer:!1}]},{questions:[{id:"dd2-sua-loi-19",type:"mc",q:"Thảo hay quên mang vở bài tập. Thảo có thể sửa lỗi thế nào?",emoji:"🎒",explain:"Soạn cặp từ tối giúp Thảo không quên vở.",options:["Ngày nào cũng mượn vở của bạn","Nói dối là để quên vở ở nhà bà","Soạn cặp từ tối theo thời gian biểu"],answer:2},{id:"dd2-sua-loi-20",type:"mc",q:"Dũng làm bẩn tường lớp khi vẽ bậy. Dũng nhận lỗi rồi. Dũng sửa lỗi thế nào?",emoji:"🧽",explain:"Lau sạch tường là sửa lỗi.",options:["Lau sạch tường cùng các bạn","Vẽ thêm thật nhiều để che đi","Không làm gì, chờ bác lao công"],answer:0},{id:"dd2-sua-loi-21",type:"tf",q:"Phúc xin lỗi bạn vì trêu bạn, nhưng hôm sau lại trêu tiếp. Phúc đã sửa lỗi.",emoji:"🔁",explain:"Sửa lỗi là không lặp lại việc sai.",answer:!1},{id:"dd2-sua-loi-22",type:"multi",q:"Bạn làm hỏng bút của em rồi xin lỗi và hứa đền. Em có thể làm gì?",emoji:"🖊️",explain:"Tha thứ nhẹ nhàng, không mắng bạn trước lớp.",options:["Tha lỗi cho bạn","Nói bạn không cần đền nếu bút rẻ","Mắng bạn trước lớp","Nhắc bạn lần sau cẩn thận"],answers:[0,1,3]},{id:"dd2-sua-loi-23",type:"mc",q:"Bình nói chuyện riêng trong giờ học, cô nhắc. Bình nên làm gì?",emoji:"🤫",explain:"Sửa lỗi bằng cách tập trung nghe giảng.",options:["Vẫn nói chuyện nhưng nói nhỏ hơn","Xin lỗi cô, tập trung nghe giảng","Giận cô, không thèm nghe giảng"],answer:1},{id:"dd2-sua-loi-24",type:"order",q:"Sắp xếp việc Vy làm khi lỡ làm vỡ bát ở nhà.",emoji:"🥣",explain:"An toàn trước, nhận lỗi rồi rút kinh nghiệm.",items:["Đứng yên, không giẫm mảnh vỡ","Báo mẹ và xin lỗi","Để mẹ dọn mảnh vỡ","Lần sau bưng bát bằng hai tay"]},{id:"dd2-sua-loi-25",type:"tf",q:"Chi ghi vào sổ nhỏ những lỗi mình hay mắc để nhắc mình sửa. Chi làm vậy là tốt.",emoji:"📒",explain:"Ghi nhớ lỗi giúp Chi sửa lỗi.",answer:!0},{id:"dd2-sua-loi-26",type:"mc",q:"Lớp em có bạn mắc lỗi và đã sửa. Cả lớp nên làm gì?",emoji:"👏",explain:"Động viên giúp bạn cố gắng hơn.",options:["Động viên, khen bạn tiến bộ","Nhắc mãi lỗi cũ của bạn","Không chơi với bạn"],answer:0},{id:"dd2-sua-loi-27",type:"fill",q:"Nhận lỗi xong, em cần … lỗi.",emoji:"🔧",explain:"Nhận lỗi xong, em cần sửa lỗi.",answer:["sửa","sua"],loose:!0}]}],challenge:{questions:[{id:"dd2-sua-loi-28",type:"match",q:"Nối việc làm với điều nó thể hiện.",emoji:"🌟",explain:"Biết sửa lỗi và tha thứ giúp em lớn lên.",pairs:[["Sửa lỗi ngay","Có trách nhiệm"],["Không mắc lại","Tiến bộ"],["Tha thứ cho bạn","Rộng lượng"]]},{id:"dd2-sua-loi-29",type:"mc",q:"Khoa hứa với mẹ không xem ti vi quá giờ nhưng lại quên. Khoa nên làm gì?",emoji:"⏰",explain:"Xin lỗi và tìm cách nhắc mình là sửa lỗi thật sự.",options:["Hứa lại với mẹ rồi lại quên tiếp","Giấu điều khiển để mẹ khỏi tắt ti vi","Xin lỗi mẹ và đặt chuông nhắc giờ"],answer:2},{id:"dd2-sua-loi-19",type:"mc",q:"Thảo hay quên mang vở bài tập. Thảo có thể sửa lỗi thế nào?",emoji:"🎒",explain:"Soạn cặp từ tối giúp Thảo không quên vở.",options:["Ngày nào cũng mượn vở của bạn","Nói dối là để quên vở ở nhà bà","Soạn cặp từ tối theo thời gian biểu"],answer:2},{id:"dd2-sua-loi-21",type:"tf",q:"Phúc xin lỗi bạn vì trêu bạn, nhưng hôm sau lại trêu tiếp. Phúc đã sửa lỗi.",emoji:"🔁",explain:"Sửa lỗi là không lặp lại việc sai.",answer:!1},{id:"dd2-sua-loi-22",type:"multi",q:"Bạn làm hỏng bút của em rồi xin lỗi và hứa đền. Em có thể làm gì?",emoji:"🖊️",explain:"Tha thứ nhẹ nhàng, không mắng bạn trước lớp.",options:["Tha lỗi cho bạn","Nói bạn không cần đền nếu bút rẻ","Mắng bạn trước lớp","Nhắc bạn lần sau cẩn thận"],answers:[0,1,3]},{id:"dd2-sua-loi-25",type:"tf",q:"Chi ghi vào sổ nhỏ những lỗi mình hay mắc để nhắc mình sửa. Chi làm vậy là tốt.",emoji:"📒",explain:"Ghi nhớ lỗi giúp Chi sửa lỗi.",answer:!0}]},summary:["Nhận lỗi rồi thì sửa lỗi.","Em cố gắng không mắc lại lỗi cũ.","Em tha thứ khi người khác biết nhận lỗi."]}]},{id:"bao-quan-do-dung",title:"Bảo quản đồ dùng cá nhân và gia đình",lessons:[{id:"dd2-bao-quan-do-ca-nhan",title:"Bài 9: Bảo quản đồ dùng cá nhân",weeks:[19,20],learn:[{title:"Đồ dùng cá nhân",text:"Sách vở, cặp, bút, quần áo, giày dép là đồ dùng của riêng em.",example:"📚 🎒 ✏️ 👕 👟"},{title:"Bảo quản đồ dùng",text:"Em dùng cẩn thận, để đúng chỗ, giữ sạch sẽ, bọc sách vở.",example:"📘 🧽 🗂️"},{title:"Vì sao cần bảo quản?",text:"Bảo quản tốt giúp đồ bền, đẹp, tiết kiệm tiền của bố mẹ.",example:"✨ 💰"}],practice:[{questions:[{id:"dd2-bao-quan-do-ca-nhan-01",type:"mc",q:"Đồ dùng nào là đồ dùng cá nhân của em?",emoji:"🎒",explain:"Cặp sách là đồ dùng riêng của em.",options:["Bàn ghế ở lớp","Cặp sách của em","Cây xanh ở sân trường"],answer:1},{id:"dd2-bao-quan-do-ca-nhan-02",type:"tf",q:"Bọc sách vở giúp sách vở sạch, không bị rách.",emoji:"📘",explain:"Bọc sách là cách bảo quản sách vở.",answer:!0},{id:"dd2-bao-quan-do-ca-nhan-03",type:"tf",q:"Vẽ bậy lên sách giáo khoa là giữ gìn sách.",emoji:"🖍️",explain:"Vẽ bậy làm sách bẩn, hỏng.",answer:!1},{id:"dd2-bao-quan-do-ca-nhan-04",type:"mc",q:"Dùng bút xong, em để đâu?",emoji:"✏️",explain:"Để bút vào hộp giúp bút không mất, không hỏng.",options:["Vứt trên sàn","Vào hộp bút","Ném vào cặp lẫn với đồ ăn"],answer:1},{id:"dd2-bao-quan-do-ca-nhan-05",type:"mc",q:"Giày bị dính bùn, em làm gì?",emoji:"👟",explain:"Giữ giày sạch giúp giày bền.",options:["Rửa sạch, phơi khô","Để nguyên rồi đi tiếp","Vứt đi"],answer:0},{id:"dd2-bao-quan-do-ca-nhan-06",type:"tf",q:"Bảo quản đồ dùng tốt giúp tiết kiệm tiền của bố mẹ.",emoji:"💰",explain:"Đồ dùng bền thì không phải mua mới.",answer:!0},{id:"dd2-bao-quan-do-ca-nhan-07",type:"mc",q:"Bạn nào biết bảo quản đồ dùng?",emoji:"📚",explain:"Cất gọn gàng là biết bảo quản.",options:["Bạn Minh xé vở ra để gấp máy bay giấy","Bạn Tùng ném cặp sách xuống đất","Bạn Hà cất sách vở gọn gàng vào cặp"],answer:2},{id:"dd2-bao-quan-do-ca-nhan-08",type:"tf",q:"Đồ dùng cũ rồi thì không cần giữ gìn.",emoji:"🎒",explain:"Đồ cũ còn dùng được vẫn cần giữ gìn.",answer:!1},{id:"dd2-bao-quan-do-ca-nhan-09",type:"mc",q:"Áo đồng phục, em giữ thế nào?",emoji:"👔",explain:"Giữ sạch, treo gọn giúp áo bền đẹp.",options:["Vo tròn lại rồi vứt ở một góc nhà","Lau tay bẩn vào áo cho nhanh","Giữ sạch, treo gọn sau khi mặc"],answer:2}]},{questions:[{id:"dd2-bao-quan-do-ca-nhan-10",type:"match",q:"Nối đồ dùng với cách bảo quản.",emoji:"🧰",explain:"Mỗi đồ dùng có cách bảo quản riêng.",pairs:[["Sách vở","Bọc bìa, không vẽ bậy"],["Bút chì","Gọt vừa phải, cất vào hộp"],["Giày dép","Giữ sạch, để trên kệ"],["Cặp sách","Không ném, không kéo lê"]]},{id:"dd2-bao-quan-do-ca-nhan-11",type:"multi",q:"Việc nào là bảo quản đồ dùng cá nhân?",emoji:"🏷️",explain:"Dùng thước đánh nhau làm hỏng thước và nguy hiểm.",options:["Ghi tên lên đồ dùng","Cất đồ đúng chỗ sau khi dùng","Dùng thước để đánh nhau","Giặt sạch khăn mặt"],answers:[0,1,3]},{id:"dd2-bao-quan-do-ca-nhan-12",type:"mc",q:"Vì sao nên ghi tên lên đồ dùng?",emoji:"🏷️",explain:"Ghi tên giúp tìm lại đồ khi bị thất lạc.",options:["Để dễ nhận lại khi để quên","Để đồ dùng trông đẹp hơn","Để bạn khác dễ lấy mất"],answer:0},{id:"dd2-bao-quan-do-ca-nhan-13",type:"tf",q:"Làm mất đồ dùng nhiều lần là biết bảo quản đồ dùng.",emoji:"❓",explain:"Em cần cất giữ cẩn thận để không làm mất.",answer:!1},{id:"dd2-bao-quan-do-ca-nhan-14",type:"order",q:"Sắp xếp việc em làm khi soạn cặp sách.",emoji:"🎒",explain:"Xem thời khóa biểu, lấy đúng sách, xếp gọn rồi kéo khóa.",items:["Xem thời khóa biểu","Lấy đúng sách vở cần mang","Xếp sách to ở dưới, sách nhỏ ở trên","Kéo khóa cặp cẩn thận"]},{id:"dd2-bao-quan-do-ca-nhan-15",type:"mc",q:"Gọt bút chì quá nhiều lần sẽ thế nào?",emoji:"✏️",explain:"Gọt vừa đủ giúp bút dùng được lâu.",options:["Bút dài ra","Bút nhanh hết","Bút đẹp hơn"],answer:1},{id:"dd2-bao-quan-do-ca-nhan-16",type:"tf",q:"Cất sách vở xa chỗ ẩm ướt giúp sách không bị mốc.",emoji:"💧",explain:"Sách bị ẩm dễ mốc, hỏng.",answer:!0},{id:"dd2-bao-quan-do-ca-nhan-17",type:"mc",q:"Áo bị rách một chút ở vai. Em làm gì?",emoji:"🧵",explain:"Khâu lại giúp áo dùng tiếp được.",options:["Nhờ bố mẹ khâu lại","Xé to thêm cho vui","Vứt luôn áo đi"],answer:0},{id:"dd2-bao-quan-do-ca-nhan-18",type:"mc",q:"Khăn mặt của em cần giữ thế nào?",emoji:"🧼",explain:"Khăn sạch, khô giúp không bị bệnh.",options:["Dùng chung với nhiều người","Để ẩm cả ngày","Giặt sạch, phơi khô"],answer:2}]},{questions:[{id:"dd2-bao-quan-do-ca-nhan-19",type:"mc",q:"Ngọc thấy bìa vở bị quăn mép. Ngọc nên làm gì?",emoji:"📒",explain:"Bọc lại bìa giúp vở bền.",options:["Xé luôn bìa vở đi","Vuốt phẳng và bọc lại bìa","Mặc kệ, cứ để bìa vở quăn tiếp"],answer:1},{id:"dd2-bao-quan-do-ca-nhan-20",type:"mc",q:"Nam để quên áo khoác ở sân trường. Lần sau Nam nên làm gì?",emoji:"🧥",explain:"Ghi tên và chú ý giúp không để quên đồ.",options:["Đòi bố mẹ mua áo khoác mới","Ghi tên lên áo và nhớ mang về","Không mặc áo khoác nữa"],answer:1},{id:"dd2-bao-quan-do-ca-nhan-21",type:"tf",q:"Hộp bút của An bị hỏng khóa, An dùng dây chun buộc lại để dùng tiếp.",emoji:"🖊️",explain:"An biết sửa để dùng tiếp đồ dùng.",answer:!0},{id:"dd2-bao-quan-do-ca-nhan-22",type:"multi",q:"Vy được tặng bộ bút màu mới. Vy có thể làm gì để giữ bút bền?",emoji:"🖍️",explain:"Đậy nắp, cất hộp, ghi tên giúp bút bền và không thất lạc.",options:["Đậy nắp sau khi dùng","Cất vào hộp","Ghi tên lên hộp bút","Cho em bé cắn chơi"],answers:[0,1,2]},{id:"dd2-bao-quan-do-ca-nhan-23",type:"mc",q:"Bình đòi mẹ mua cặp mới dù cặp cũ còn tốt. Lời khuyên nào hợp lý?",emoji:"🎒",explain:"Dùng đồ còn tốt là biết tiết kiệm.",options:["Dùng tiếp cặp cũ còn tốt","Vứt cặp cũ đi","Làm hỏng cặp cũ để mua mới"],answer:0},{id:"dd2-bao-quan-do-ca-nhan-24",type:"order",q:"Sắp xếp việc Khoa làm khi đi mưa về, giày bị ướt.",emoji:"👟",explain:"Rửa, phơi khô rồi mới cất giày.",items:["Tháo giày ra","Rửa sạch bùn đất","Phơi giày ở chỗ thoáng","Cất giày khi đã khô"]},{id:"dd2-bao-quan-do-ca-nhan-25",type:"tf",q:"Phúc hay dùng bút bi vẽ lên tay, lên bàn. Phúc biết giữ gìn đồ dùng.",emoji:"🖊️",explain:"Phúc nên dùng bút đúng mục đích.",answer:!1},{id:"dd2-bao-quan-do-ca-nhan-26",type:"mc",q:"Vở viết xong còn nhiều trang trắng. Em làm gì?",emoji:"📓",explain:"Tận dụng trang trắng là tiết kiệm.",options:["Xé vứt đi","Gấp máy bay giấy hết","Dùng làm vở nháp"],answer:2},{id:"dd2-bao-quan-do-ca-nhan-27",type:"fill",q:"Em … sách vở để sách không bị rách, bẩn.",emoji:"📘",explain:"Em bọc sách vở để sách bền, sạch.",answer:["bọc","boc"],loose:!0}]}],challenge:{questions:[{id:"dd2-bao-quan-do-ca-nhan-28",type:"match",q:"Nối việc làm với kết quả.",emoji:"✨",explain:"Bảo quản tốt giúp đồ dùng bền lâu.",pairs:[["Bọc sách vở","Sách sạch, không rách"],["Ném cặp xuống đất","Cặp nhanh hỏng"],["Ghi tên lên đồ dùng","Dễ tìm lại khi để quên"]]},{id:"dd2-bao-quan-do-ca-nhan-29",type:"mc",q:"Chi để quên hộp bút ở lớp. Sáng hôm sau, Chi nên làm gì?",emoji:"🔍",explain:"Tìm lại đồ dùng trước khi nghĩ đến mua mới.",options:["Đòi mẹ mua ngay hộp bút mới","Lấy hộp bút của bạn ngồi bên cạnh","Đến hỏi cô hoặc tìm ở chỗ ngồi"],answer:2},{id:"dd2-bao-quan-do-ca-nhan-19",type:"mc",q:"Ngọc thấy bìa vở bị quăn mép. Ngọc nên làm gì?",emoji:"📒",explain:"Bọc lại bìa giúp vở bền.",options:["Xé luôn bìa vở đi","Vuốt phẳng và bọc lại bìa","Mặc kệ, cứ để bìa vở quăn tiếp"],answer:1},{id:"dd2-bao-quan-do-ca-nhan-20",type:"mc",q:"Nam để quên áo khoác ở sân trường. Lần sau Nam nên làm gì?",emoji:"🧥",explain:"Ghi tên và chú ý giúp không để quên đồ.",options:["Đòi bố mẹ mua áo khoác mới","Ghi tên lên áo và nhớ mang về","Không mặc áo khoác nữa"],answer:1},{id:"dd2-bao-quan-do-ca-nhan-23",type:"mc",q:"Bình đòi mẹ mua cặp mới dù cặp cũ còn tốt. Lời khuyên nào hợp lý?",emoji:"🎒",explain:"Dùng đồ còn tốt là biết tiết kiệm.",options:["Dùng tiếp cặp cũ còn tốt","Vứt cặp cũ đi","Làm hỏng cặp cũ để mua mới"],answer:0},{id:"dd2-bao-quan-do-ca-nhan-26",type:"mc",q:"Vở viết xong còn nhiều trang trắng. Em làm gì?",emoji:"📓",explain:"Tận dụng trang trắng là tiết kiệm.",options:["Xé vứt đi","Gấp máy bay giấy hết","Dùng làm vở nháp"],answer:2}]},summary:["Em dùng đồ dùng cá nhân cẩn thận.","Em để đồ đúng chỗ, giữ sạch sẽ.","Bảo quản đồ dùng giúp đồ bền lâu, tiết kiệm."]},{id:"dd2-bao-quan-do-gia-dinh",title:"Bài 10: Bảo quản đồ dùng gia đình",weeks:[21,22],learn:[{title:"Đồ dùng gia đình",text:"Bàn ghế, ti vi, quạt, bát đĩa, tủ lạnh là đồ dùng chung của cả nhà.",example:"🪑 📺 🌀 🍽️"},{title:"Dùng cẩn thận",text:"Em dùng nhẹ nhàng, đúng cách, xong thì cất đúng chỗ. Đồ điện thì cần người lớn hướng dẫn.",example:"🙌 ✅ 🔌"},{title:"Tiết kiệm",text:"Tắt đèn, quạt khi không dùng. Đóng tủ lạnh ngay sau khi lấy đồ.",example:"💡 🌀 ❄️"}],practice:[{questions:[{id:"dd2-bao-quan-do-gia-dinh-01",type:"mc",q:"Đồ dùng nào là đồ dùng chung của gia đình?",emoji:"📺",explain:"Ti vi là đồ dùng chung của cả nhà.",options:["Ti vi","Cặp sách của em","Bàn chải đánh răng của em"],answer:0},{id:"dd2-bao-quan-do-gia-dinh-02",type:"tf",q:"Tắt quạt khi ra khỏi phòng là tiết kiệm điện.",emoji:"🌀",explain:"Tắt đồ điện khi không dùng giúp tiết kiệm.",answer:!0},{id:"dd2-bao-quan-do-gia-dinh-03",type:"tf",q:"Nhảy lên ghế sô pha để chơi là giữ gìn đồ dùng.",emoji:"🛋️",explain:"Nhảy lên ghế làm ghế nhanh hỏng và dễ ngã.",answer:!1},{id:"dd2-bao-quan-do-gia-dinh-04",type:"mc",q:"Lấy đồ trong tủ lạnh xong, em làm gì?",emoji:"🧊",explain:"Đóng tủ lạnh ngay giúp tiết kiệm điện, giữ thức ăn tươi.",options:["Để mở cửa tủ","Đóng cửa tủ lạnh ngay","Ngồi trước tủ cho mát"],answer:1},{id:"dd2-bao-quan-do-gia-dinh-05",type:"mc",q:"Bê bát đĩa, em làm thế nào?",emoji:"🍽️",explain:"Cẩn thận để không làm vỡ bát đĩa.",options:["Cầm chắc bằng hai tay, đi chậm","Vừa bê vừa chạy thật nhanh vào bếp","Cầm một tay, vừa đi vừa tung lên"],answer:0},{id:"dd2-bao-quan-do-gia-dinh-06",type:"tf",q:"Đồ dùng gia đình là của chung, mọi người cùng giữ gìn.",emoji:"🏠",explain:"Ai trong nhà cũng cần giữ gìn đồ dùng chung.",answer:!0},{id:"dd2-bao-quan-do-gia-dinh-07",type:"mc",q:"Rửa tay xong, em làm gì với vòi nước?",emoji:"🚰",explain:"Khóa vòi để tiết kiệm nước.",options:["Để nước chảy","Mở to hơn","Khóa vòi lại"],answer:2},{id:"dd2-bao-quan-do-gia-dinh-08",type:"tf",q:"Ném điều khiển ti vi lên ghế cho nhanh là giữ gìn đồ dùng.",emoji:"📺",explain:"Ném đồ dễ làm rơi, hỏng; em đặt điều khiển nhẹ nhàng vào đúng chỗ.",answer:!1},{id:"dd2-bao-quan-do-gia-dinh-09",type:"mc",q:"Bạn nào giữ gìn đồ dùng gia đình?",emoji:"🧽",explain:"Lau bàn sạch sẽ là giữ gìn đồ dùng.",options:["Bạn Bình viết lên tường nhà","Bạn Lan lau bàn sạch sau khi ăn","Bạn Tùng đá vào cửa tủ"],answer:1}]},{questions:[{id:"dd2-bao-quan-do-gia-dinh-10",type:"match",q:"Nối đồ dùng với cách bảo quản.",emoji:"🏠",explain:"Mỗi đồ dùng có cách giữ gìn riêng.",pairs:[["Bát đĩa","Cầm chắc, rửa sạch, úp lên giá"],["Ti vi","Không đập, tắt khi không xem"],["Tủ lạnh","Đóng cửa ngay sau khi lấy đồ"],["Bàn ghế","Không đứng, nhảy lên"]]},{id:"dd2-bao-quan-do-gia-dinh-11",type:"multi",q:"Việc nào giúp tiết kiệm điện, nước ở nhà?",emoji:"💡",explain:"Mở ti vi khi không xem là lãng phí điện.",options:["Tắt đèn khi ra khỏi phòng","Khóa vòi nước khi đánh răng","Mở ti vi khi không ai xem","Rút sạc khi pin đã đầy"],answers:[0,1,3]},{id:"dd2-bao-quan-do-gia-dinh-12",type:"mc",q:"Vì sao cần bảo quản đồ dùng gia đình?",emoji:"💰",explain:"Đồ dùng bền giúp gia đình tiết kiệm.",options:["Để đồ dùng nhanh hỏng, mua cái mới","Để đồ dùng bền, tiết kiệm tiền của gia đình","Vì ở nhà không có việc gì khác để làm"],answer:1},{id:"dd2-bao-quan-do-gia-dinh-13",type:"tf",q:"Đồ điện như nồi cơm điện, bàn là, em cần người lớn hướng dẫn mới dùng.",emoji:"🔌",explain:"Đồ điện có thể nguy hiểm, cần có người lớn.",answer:!0},{id:"dd2-bao-quan-do-gia-dinh-14",type:"order",q:"Sắp xếp việc em làm khi giúp mẹ rửa bát.",emoji:"🥣",explain:"Đổ thức ăn thừa, rửa, tráng sạch rồi úp lên giá.",items:["Đổ thức ăn thừa","Rửa bằng nước rửa bát","Tráng lại bằng nước sạch","Úp bát lên giá"]},{id:"dd2-bao-quan-do-gia-dinh-15",type:"mc",q:"Ghế bị lung lay chân. Em làm gì?",emoji:"🪑",explain:"Báo người lớn để sửa ghế cho an toàn.",options:["Báo bố mẹ sửa","Ngồi đung đưa tiếp","Đẩy cho đổ hẳn"],answer:0},{id:"dd2-bao-quan-do-gia-dinh-16",type:"tf",q:"Đóng mở cửa thật mạnh không làm hỏng cửa.",emoji:"🚪",explain:"Đóng sầm cửa làm cửa nhanh hỏng.",answer:!1},{id:"dd2-bao-quan-do-gia-dinh-17",type:"mc",q:"Xem ti vi xong, em làm gì với điều khiển?",emoji:"🎛️",explain:"Để đúng chỗ, cả nhà dễ tìm.",options:["Giấu vào gối","Ném lên nóc tủ","Để vào đúng chỗ"],answer:2},{id:"dd2-bao-quan-do-gia-dinh-18",type:"mc",q:"Đồ chơi chung của anh chị em, em giữ thế nào?",emoji:"🧩",explain:"Đồ chung thì cùng giữ gìn.",options:["Giành về một mình","Làm hỏng cho người khác không chơi được","Chơi nhẹ nhàng, cùng cất gọn"],answer:2}]},{questions:[{id:"dd2-bao-quan-do-gia-dinh-19",type:"mc",q:"Ở nhà một mình, Hà thấy đèn bàn bị hỏng chập chờn. Hà nên làm gì?",emoji:"💡",explain:"Đồ điện hỏng cần người lớn sửa.",options:["Tắt công tắc nếu an toàn và báo bố mẹ","Tự tháo đèn ra sửa dù chưa biết cách","Dùng tay ướt sờ vào bóng đèn cho biết"],answer:0},{id:"dd2-bao-quan-do-gia-dinh-20",type:"mc",q:"Em trai lấy bút vẽ lên tường nhà. Em làm gì?",emoji:"🖍️",explain:"Hướng em vẽ lên giấy là cách tốt.",options:["Lấy bút vẽ lên tường cùng em","Nhẹ nhàng đưa em giấy để vẽ và báo mẹ","Mắng em thật to rồi giật lấy bút của em"],answer:1},{id:"dd2-bao-quan-do-gia-dinh-21",type:"tf",q:"Đánh răng xong, Minh khóa vòi nước rồi mới lau mặt.",emoji:"🚰",explain:"Khóa vòi khi không dùng là tiết kiệm nước.",answer:!0},{id:"dd2-bao-quan-do-gia-dinh-22",type:"multi",q:"Lỡ làm vỡ chiếc cốc ở nhà, em làm gì?",emoji:"🥛",explain:"Mảnh vỡ sắc, để người lớn dọn.",options:["Báo bố mẹ","Xin lỗi","Tự nhặt mảnh vỡ bằng tay không","Lần sau cầm cẩn thận hơn"],answers:[0,1,3]},{id:"dd2-bao-quan-do-gia-dinh-23",type:"mc",q:"Cả nhà ra ngoài, quạt và đèn phòng khách vẫn bật. Khoa nên làm gì?",emoji:"🌀",explain:"Tắt điện khi ra ngoài là tiết kiệm và an toàn.",options:["Tắt quạt, tắt đèn trước khi đi","Để nguyên, lúc về tắt sau","Bật thêm ti vi cho nhà sáng"],answer:0},{id:"dd2-bao-quan-do-gia-dinh-24",type:"order",q:"Sắp xếp việc em làm khi dọn bàn sau bữa ăn.",emoji:"🍽️",explain:"Cất thức ăn, dọn bát, lau bàn rồi xếp ghế.",items:["Cất thức ăn thừa","Mang bát đũa vào chỗ rửa","Lau sạch bàn","Xếp ghế gọn gàng"]},{id:"dd2-bao-quan-do-gia-dinh-25",type:"tf",q:"Chơi bóng trong phòng khách làm vỡ đồ là chuyện bình thường, không cần nhận lỗi.",emoji:"⚽",explain:"Em không chơi bóng trong nhà, làm vỡ đồ thì nhận lỗi.",answer:!1},{id:"dd2-bao-quan-do-gia-dinh-26",type:"mc",q:"Bố đang sửa quạt, Phúc muốn giúp. Phúc có thể làm gì?",emoji:"🔧",explain:"Giúp việc vừa sức và an toàn.",options:["Cắm điện thử quạt khi bố chưa sửa xong","Thò tay nghịch cánh quạt khi bố đang sửa","Đưa dụng cụ khi bố nhờ, đứng ở chỗ an toàn"],answer:2},{id:"dd2-bao-quan-do-gia-dinh-27",type:"fill",q:"Ra khỏi phòng, em tắt … để tiết kiệm điện.",emoji:"💡",explain:"Ra khỏi phòng, em tắt đèn, tắt quạt.",answer:["đèn","den","quạt","quat"],loose:!0}]}],challenge:{questions:[{id:"dd2-bao-quan-do-gia-dinh-28",type:"match",q:"Nối tình huống với việc làm đúng.",emoji:"🏠",explain:"Em giữ gìn đồ dùng gia đình mỗi ngày.",pairs:[["Ra khỏi phòng","Tắt đèn, quạt"],["Ghế bị lung lay","Báo bố mẹ sửa"],["Lấy đồ trong tủ lạnh","Đóng cửa tủ ngay"]]},{id:"dd2-bao-quan-do-gia-dinh-29",type:"mc",q:"Vy làm đổ nước lên bàn gỗ. Vy nên làm gì?",emoji:"💧",explain:"Lau khô ngay giúp bàn gỗ bền.",options:["Để nước tự khô, không cần lau đi","Lau khô ngay để bàn không hỏng","Đặt thêm đồ lên chỗ nước đổ"],answer:1},{id:"dd2-bao-quan-do-gia-dinh-19",type:"mc",q:"Ở nhà một mình, Hà thấy đèn bàn bị hỏng chập chờn. Hà nên làm gì?",emoji:"💡",explain:"Đồ điện hỏng cần người lớn sửa.",options:["Tắt công tắc nếu an toàn và báo bố mẹ","Tự tháo đèn ra sửa dù chưa biết cách","Dùng tay ướt sờ vào bóng đèn cho biết"],answer:0},{id:"dd2-bao-quan-do-gia-dinh-20",type:"mc",q:"Em trai lấy bút vẽ lên tường nhà. Em làm gì?",emoji:"🖍️",explain:"Hướng em vẽ lên giấy là cách tốt.",options:["Lấy bút vẽ lên tường cùng em","Nhẹ nhàng đưa em giấy để vẽ và báo mẹ","Mắng em thật to rồi giật lấy bút của em"],answer:1},{id:"dd2-bao-quan-do-gia-dinh-23",type:"mc",q:"Cả nhà ra ngoài, quạt và đèn phòng khách vẫn bật. Khoa nên làm gì?",emoji:"🌀",explain:"Tắt điện khi ra ngoài là tiết kiệm và an toàn.",options:["Tắt quạt, tắt đèn trước khi đi","Để nguyên, lúc về tắt sau","Bật thêm ti vi cho nhà sáng"],answer:0},{id:"dd2-bao-quan-do-gia-dinh-26",type:"mc",q:"Bố đang sửa quạt, Phúc muốn giúp. Phúc có thể làm gì?",emoji:"🔧",explain:"Giúp việc vừa sức và an toàn.",options:["Cắm điện thử quạt khi bố chưa sửa xong","Thò tay nghịch cánh quạt khi bố đang sửa","Đưa dụng cụ khi bố nhờ, đứng ở chỗ an toàn"],answer:2}]},summary:["Đồ dùng gia đình là tài sản chung của cả nhà.","Em dùng đồ cẩn thận, cất đúng chỗ.","Em tắt điện, khóa nước khi không dùng."]}]},{id:"the-hien-cam-xuc",title:"Thể hiện cảm xúc bản thân",lessons:[{id:"dd2-cam-xuc-cua-em",title:"Bài 11: Cảm xúc của em",weeks:[23,24],learn:[{title:"Các cảm xúc",text:"Em có thể vui, buồn, sợ hãi, tức giận, ngạc nhiên. Cảm xúc nào cũng bình thường.",example:"😊 😢 😨 😠 😲"},{title:"Cảm xúc tích cực và tiêu cực",text:"Vui vẻ, yêu thương là tích cực. Buồn bã, tức giận, sợ hãi là tiêu cực.",example:"😊 🥰  ·  😢 😠"},{title:"Thể hiện cảm xúc phù hợp",text:"Em nói ra cảm xúc của mình một cách nhẹ nhàng, đúng lúc, đúng chỗ.",example:"💬 “Mình đang buồn.”"}],practice:[{questions:[{id:"dd2-cam-xuc-cua-em-01",type:"mc",q:"Khi được tặng quà, em thường cảm thấy thế nào?",emoji:"🎁",explain:"Được tặng quà, em vui.",options:["Tức giận","Vui","Sợ hãi"],answer:1},{id:"dd2-cam-xuc-cua-em-02",type:"tf",q:"Buồn, tức giận cũng là cảm xúc bình thường.",emoji:"😢",explain:"Ai cũng có lúc buồn, lúc giận.",answer:!0},{id:"dd2-cam-xuc-cua-em-03",type:"mc",q:"Cảm xúc nào là tích cực?",emoji:"😊",explain:"Vui vẻ là cảm xúc tích cực.",options:["Vui vẻ","Tức giận","Sợ hãi"],answer:0},{id:"dd2-cam-xuc-cua-em-04",type:"mc",q:"Cảm xúc nào là tiêu cực?",emoji:"😞",explain:"Buồn bã là cảm xúc tiêu cực.",options:["Vui vẻ","Yêu thương","Buồn bã"],answer:2},{id:"dd2-cam-xuc-cua-em-05",type:"tf",q:"Đang buồn, em nên giấu kín, không nói với ai.",emoji:"🤐",explain:"Em có thể chia sẻ với người thân để được giúp.",answer:!1},{id:"dd2-cam-xuc-cua-em-06",type:"mc",q:"Gương mặt này thể hiện cảm xúc gì?",emoji:"😲",explain:"Mắt mở to, miệng tròn là ngạc nhiên.",options:["Đang buồn ngủ","Đang đau răng","Ngạc nhiên"],answer:2},{id:"dd2-cam-xuc-cua-em-07",type:"tf",q:"Cười to giữa lúc cả lớp đang chào cờ là phù hợp.",emoji:"🇻🇳",explain:"Em thể hiện cảm xúc phù hợp nơi chốn.",answer:!1},{id:"dd2-cam-xuc-cua-em-08",type:"mc",q:"Khi vui, em có thể thể hiện thế nào?",emoji:"😄",explain:"Mỉm cười là cách thể hiện niềm vui phù hợp.",options:["Mỉm cười, nói lời vui vẻ","Đập phá đồ đạc trong nhà","Hét thật to vào tai bạn"],answer:0},{id:"dd2-cam-xuc-cua-em-09",type:"tf",q:"Cảm xúc tích cực giúp em vui khỏe, học tốt hơn.",emoji:"🌈",explain:"Vui vẻ giúp em có thêm sức học và chơi.",answer:!0}]},{questions:[{id:"dd2-cam-xuc-cua-em-10",type:"match",q:"Nối tình huống với cảm xúc thường gặp.",emoji:"🎭",explain:"Mỗi tình huống có thể gây ra cảm xúc khác nhau.",pairs:[["Được cô khen","Vui"],["Bị mất đồ chơi yêu thích","Buồn"],["Nghe tiếng sấm to","Sợ hãi"],["Bị bạn giật đồ","Tức giận"]]},{id:"dd2-cam-xuc-cua-em-11",type:"multi",q:"Cách nào thể hiện cảm xúc phù hợp?",emoji:"💬",explain:"Ném đồ khi tức giận là không phù hợp.",options:["Nói: “Mình đang buồn”","Ôm mẹ khi vui","Ném đồ khi tức giận","Kể cho bạn thân nghe khi lo lắng"],answers:[0,1,3]},{id:"dd2-cam-xuc-cua-em-12",type:"mc",q:"Vì sao nên nói ra cảm xúc của mình?",emoji:"🗣️",explain:"Nói ra giúp mọi người hiểu em.",options:["Để làm cho người khác buồn","Để người khác hiểu và giúp em","Để được mọi người cho thật nhiều quà"],answer:1},{id:"dd2-cam-xuc-cua-em-13",type:"tf",q:"Bạn đang buồn, em cười trêu bạn là phù hợp.",emoji:"😢",explain:"Em quan tâm, an ủi khi bạn buồn.",answer:!1},{id:"dd2-cam-xuc-cua-em-14",type:"order",q:"Sắp xếp các bước khi em thấy buồn.",emoji:"🌤️",explain:"Nhận ra, bình tĩnh, chia sẻ rồi làm việc mình thích.",items:["Nhận ra mình đang buồn","Hít thở chậm","Nói với người tin cậy","Làm việc mình thích để vui lên"]},{id:"dd2-cam-xuc-cua-em-15",type:"mc",q:"Bạn kể chuyện vui với em. Em làm gì?",emoji:"😊",explain:"Chia sẻ niềm vui với bạn là thân thiện.",options:["Lắng nghe và cùng vui với bạn","Quay đi chỗ khác, không thèm nghe","Nói chuyện của bạn chán lắm"],answer:0},{id:"dd2-cam-xuc-cua-em-16",type:"tf",q:"Nhìn nét mặt, em có thể đoán được cảm xúc của bạn.",emoji:"👀",explain:"Nét mặt cho biết bạn vui, buồn hay giận.",answer:!0},{id:"dd2-cam-xuc-cua-em-17",type:"mc",q:"Gương mặt này thể hiện cảm xúc gì?",emoji:"😠",explain:"Lông mày nhíu, mặt đỏ là tức giận.",options:["Vui sướng","Buồn ngủ","Tức giận"],answer:2},{id:"dd2-cam-xuc-cua-em-18",type:"tf",q:"Chỉ bạn gái mới được khóc khi buồn.",emoji:"🧒",explain:"Bạn trai hay bạn gái đều có thể khóc khi buồn.",answer:!1}]},{questions:[{id:"dd2-cam-xuc-cua-em-19",type:"mc",q:"Hôm nay Tùng được điểm tốt. Tùng thể hiện niềm vui thế nào cho phù hợp?",emoji:"💯",explain:"Chia sẻ niềm vui mà không làm người khác buồn.",options:["Chê các bạn bị điểm kém","Kể với bố mẹ, mỉm cười vui vẻ","Hét thật to ngay trong giờ học"],answer:1},{id:"dd2-cam-xuc-cua-em-20",type:"mc",q:"Chi thấy bạn ngồi một mình, mặt buồn. Chi nên làm gì?",emoji:"😔",explain:"Quan tâm khi bạn buồn là tốt.",options:["Mặc kệ, đi chơi một mình","Đến hỏi han, rủ bạn chơi","Kể cho cả lớp biết bạn buồn"],answer:1},{id:"dd2-cam-xuc-cua-em-21",type:"tf",q:"Nam sợ bóng tối nên nói với mẹ để mẹ để đèn ngủ. Nam đã thể hiện cảm xúc phù hợp.",emoji:"🌙",explain:"Nói ra nỗi sợ giúp Nam được giúp đỡ.",answer:!0},{id:"dd2-cam-xuc-cua-em-22",type:"multi",q:"Em lo lắng trước giờ kiểm tra. Em có thể làm gì?",emoji:"😟",explain:"Bình tĩnh, tự động viên và chia sẻ giúp bớt lo.",options:["Hít thở sâu","Tự nhủ: Mình đã ôn bài kỹ","Nói với cô hoặc bố mẹ","Bỏ không đi học"],answers:[0,1,2]},{id:"dd2-cam-xuc-cua-em-23",type:"mc",q:"Ngọc rất vui vì được đi chơi công viên nhưng em trai bị ốm phải ở nhà. Ngọc nên làm gì?",emoji:"🎡",explain:"Thể hiện niềm vui mà vẫn quan tâm em.",options:["Vui vừa phải, hỏi thăm và kể chuyện cho em nghe","Khoe mãi chuyện đi chơi công viên cho em tức","Chê em yếu nên mới bị ốm, phải ở nhà"],answer:0},{id:"dd2-cam-xuc-cua-em-24",type:"order",q:"Sắp xếp việc em làm khi bạn chia sẻ nỗi buồn.",emoji:"🫂",explain:"Lắng nghe, hỏi han rồi động viên.",items:["Lắng nghe bạn","Hỏi bạn cần giúp gì","An ủi, động viên bạn"]},{id:"dd2-cam-xuc-cua-em-25",type:"tf",q:"Bạn nói đang buồn, Khoa bảo: “Có gì đâu mà buồn, đừng nói nữa.” Khoa làm vậy là quan tâm bạn.",emoji:"🙉",explain:"Khoa nên lắng nghe và an ủi bạn.",answer:!1},{id:"dd2-cam-xuc-cua-em-26",type:"mc",q:"Em được chọn đi thi văn nghệ, vừa vui vừa run. Điều đó thế nào?",emoji:"🎤",explain:"Có thể có nhiều cảm xúc cùng lúc.",options:["Rất xấu, không được có cảm xúc như vậy","Không thể có, chỉ được vui hoặc lo thôi","Bình thường, ai cũng có thể vừa vui vừa lo"],answer:2},{id:"dd2-cam-xuc-cua-em-27",type:"fill",q:"Vui vẻ, yêu thương là cảm xúc tích …",emoji:"😊",explain:"Vui vẻ, yêu thương là cảm xúc tích cực.",answer:["cực","cuc"],loose:!0}]}],challenge:{questions:[{id:"dd2-cam-xuc-cua-em-28",type:"match",q:"Nối cảm xúc với cách thể hiện phù hợp.",emoji:"🎭",explain:"Thể hiện cảm xúc phù hợp giúp em và mọi người dễ chịu.",pairs:[["Vui","Mỉm cười, chia sẻ với người thân"],["Buồn","Kể cho người tin cậy nghe"],["Sợ hãi","Nói với người lớn để được giúp"]]},{id:"dd2-cam-xuc-cua-em-29",type:"mc",q:"Vy đang rất vui vì được quà nhưng bạn bên cạnh vừa bị mất đồ. Vy nên làm gì?",emoji:"🎁",explain:"Thể hiện cảm xúc cần nghĩ đến người xung quanh.",options:["Khoe quà thật to cho cả lớp cùng nghe","Cười bạn vì bạn làm mất đồ của mình","Giúp bạn tìm đồ trước, chia sẻ niềm vui sau"],answer:2},{id:"dd2-cam-xuc-cua-em-19",type:"mc",q:"Hôm nay Tùng được điểm tốt. Tùng thể hiện niềm vui thế nào cho phù hợp?",emoji:"💯",explain:"Chia sẻ niềm vui mà không làm người khác buồn.",options:["Chê các bạn bị điểm kém","Kể với bố mẹ, mỉm cười vui vẻ","Hét thật to ngay trong giờ học"],answer:1},{id:"dd2-cam-xuc-cua-em-21",type:"tf",q:"Nam sợ bóng tối nên nói với mẹ để mẹ để đèn ngủ. Nam đã thể hiện cảm xúc phù hợp.",emoji:"🌙",explain:"Nói ra nỗi sợ giúp Nam được giúp đỡ.",answer:!0},{id:"dd2-cam-xuc-cua-em-22",type:"multi",q:"Em lo lắng trước giờ kiểm tra. Em có thể làm gì?",emoji:"😟",explain:"Bình tĩnh, tự động viên và chia sẻ giúp bớt lo.",options:["Hít thở sâu","Tự nhủ: Mình đã ôn bài kỹ","Nói với cô hoặc bố mẹ","Bỏ không đi học"],answers:[0,1,2]},{id:"dd2-cam-xuc-cua-em-25",type:"tf",q:"Bạn nói đang buồn, Khoa bảo: “Có gì đâu mà buồn, đừng nói nữa.” Khoa làm vậy là quan tâm bạn.",emoji:"🙉",explain:"Khoa nên lắng nghe và an ủi bạn.",answer:!1}]},summary:["Ai cũng có nhiều cảm xúc khác nhau.","Em nhận biết cảm xúc tích cực và tiêu cực.","Em thể hiện cảm xúc nhẹ nhàng, phù hợp."]},{id:"dd2-kiem-che-cam-xuc",title:"Bài 12: Kiềm chế cảm xúc tiêu cực",weeks:[25,26],learn:[{title:"Khi tức giận",text:"Tức giận dễ làm em nói lời khó nghe, làm hỏng đồ hoặc làm đau người khác.",example:"😠 💥"},{title:"Cách bình tĩnh",text:"Em hít thở sâu, đếm chậm từ 1 đến 10, uống nước, đi ra chỗ khác một lúc.",example:"🌬️ 1️⃣…🔟 💧"},{title:"Nói ra nhẹ nhàng",text:"Khi đã bình tĩnh, em nói điều làm mình không vui và cùng tìm cách giải quyết.",example:"💬 🤝"}],practice:[{questions:[{id:"dd2-kiem-che-cam-xuc-01",type:"tf",q:"Hít thở sâu giúp em bình tĩnh khi tức giận.",emoji:"🌬️",explain:"Hít thở chậm giúp cơn giận dịu đi.",answer:!0},{id:"dd2-kiem-che-cam-xuc-02",type:"mc",q:"Khi tức giận, em nên làm gì?",emoji:"🔟",explain:"Đếm chậm giúp em bình tĩnh lại.",options:["Đếm chậm từ 1 đến 10","Ném đồ xuống đất","Đánh bạn cho hả giận"],answer:0},{id:"dd2-kiem-che-cam-xuc-03",type:"tf",q:"Tức giận thì được phép đánh bạn.",emoji:"👊",explain:"Dù tức giận, em không làm đau người khác.",answer:!1},{id:"dd2-kiem-che-cam-xuc-04",type:"mc",q:"Bạn nào biết kiềm chế cơn giận?",emoji:"😌",explain:"Hít thở sâu rồi nói nhẹ nhàng là biết kiềm chế.",options:["Bạn Bình tức quá nên đá đổ ghế trong lớp","Bạn An hít thở sâu rồi nói chuyện nhẹ nhàng","Bạn Dũng hét thật to vào mặt bạn mình"],answer:1},{id:"dd2-kiem-che-cam-xuc-05",type:"mc",q:"Cảm xúc nào cần được kiềm chế?",emoji:"😡",explain:"Tức giận quá mức dễ làm em hành động sai.",options:["Tức giận quá mức","Yêu thương mọi người","Biết ơn thầy cô"],answer:0},{id:"dd2-kiem-che-cam-xuc-06",type:"tf",q:"Khi buồn, em có thể nghe nhạc nhẹ, vẽ tranh để vui lên.",emoji:"🎨",explain:"Làm việc mình thích giúp bớt buồn.",answer:!0},{id:"dd2-kiem-che-cam-xuc-07",type:"mc",q:"Tức giận mà nói lời khó nghe thì sẽ thế nào?",emoji:"🗯️",explain:"Lời nói khó nghe làm tổn thương người khác.",options:["Mọi người sẽ vui hơn và thích mình hơn","Không sao cả, ai rồi cũng quên thôi","Làm người khác buồn, mọi chuyện tệ hơn"],answer:2},{id:"dd2-kiem-che-cam-xuc-08",type:"tf",q:"Đóng sầm cửa khi giận là cách bình tĩnh tốt.",emoji:"🚪",explain:"Đóng sầm cửa làm hỏng đồ và làm mọi người giật mình.",answer:!1},{id:"dd2-kiem-che-cam-xuc-09",type:"mc",q:"Bình tĩnh lại rồi, em làm gì tiếp?",emoji:"💬",explain:"Nói nhẹ nhàng giúp giải quyết vấn đề.",options:["Tiếp tục giận, không nói với ai","Nói nhẹ nhàng điều làm mình không vui","Tìm cách trả thù bạn cho bằng được"],answer:1}]},{questions:[{id:"dd2-kiem-che-cam-xuc-10",type:"order",q:"Sắp xếp các bước khi em tức giận.",emoji:"🛑",explain:"Dừng lại, bình tĩnh, suy nghĩ rồi nói nhẹ nhàng.",items:["Dừng lại","Hít thở sâu, đếm đến 10","Nghĩ xem vì sao mình giận","Nói ra nhẹ nhàng"]},{id:"dd2-kiem-che-cam-xuc-11",type:"match",q:"Nối cảm xúc tiêu cực với cách làm dịu.",emoji:"🌈",explain:"Mỗi cảm xúc có cách làm dịu phù hợp.",pairs:[["Tức giận","Hít thở sâu, đếm chậm"],["Buồn bã","Tâm sự với người thân"],["Lo lắng","Chuẩn bị kỹ, tự động viên mình"],["Sợ hãi","Nhờ người lớn ở bên"]]},{id:"dd2-kiem-che-cam-xuc-12",type:"multi",q:"Việc nào giúp em bình tĩnh?",emoji:"🧸",explain:"Đập bàn không giúp bình tĩnh mà còn làm hỏng đồ.",options:["Uống một cốc nước","Đi ra chỗ khác một lúc","Đập bàn thật mạnh","Ôm gấu bông"],answers:[0,1,3]},{id:"dd2-kiem-che-cam-xuc-13",type:"mc",q:"Vì sao cần kiềm chế cảm xúc tiêu cực?",emoji:"💡",explain:"Kiềm chế giúp em không làm điều sai khi đang giận.",options:["Để không bao giờ được buồn hay khóc","Để không làm tổn thương mình và người khác","Để người khác sợ mình, nghe lời mình"],answer:1},{id:"dd2-kiem-che-cam-xuc-14",type:"tf",q:"Kiềm chế cảm xúc nghĩa là không bao giờ được buồn hay giận.",emoji:"🙂",explain:"Buồn, giận là bình thường; em học cách thể hiện cho đúng.",answer:!1},{id:"dd2-kiem-che-cam-xuc-15",type:"mc",q:"Bạn lỡ làm đổ màu lên tranh của em. Em nên nói gì?",emoji:"🎨",explain:"Nói nhẹ nhàng cảm xúc của mình là phù hợp.",options:["Mình hơi buồn, lần sau bạn cẩn thận nhé","Bạn thật đáng ghét, đi chỗ khác đi!","Mình sẽ làm hỏng tranh của bạn lại!"],answer:0},{id:"dd2-kiem-che-cam-xuc-16",type:"tf",q:"Kể cho bố mẹ nghe chuyện làm em buồn giúp em nhẹ lòng hơn.",emoji:"👨‍👩‍👧",explain:"Chia sẻ với người thân giúp em được an ủi.",answer:!0},{id:"dd2-kiem-che-cam-xuc-17",type:"mc",q:"Thua trong trò chơi, em nên làm gì?",emoji:"🏁",explain:"Thua không sao, em vui vẻ và cố gắng hơn.",options:["Giận dỗi, bỏ về nhà không chơi nữa","Cãi là bạn ăn gian nên mới thắng","Chúc mừng bạn thắng, lần sau cố gắng"],answer:2},{id:"dd2-kiem-che-cam-xuc-18",type:"mc",q:"Em bé làm đổ tháp xếp hình em vừa xếp xong. Em làm gì?",emoji:"🧱",explain:"Bình tĩnh và nhẹ nhàng với em nhỏ.",options:["Giận em, không cho em chơi cùng nữa","Hét lên thật to cho cả nhà nghe thấy","Hít thở, nói với em nhẹ nhàng rồi xếp lại"],answer:2}]},{questions:[{id:"dd2-kiem-che-cam-xuc-19",type:"mc",q:"Đang chơi, Minh bị bạn giành mất bóng. Minh rất tức. Minh nên làm gì?",emoji:"⚽",explain:"Bình tĩnh và nói rõ ràng giúp giải quyết.",options:["Hít thở sâu, rồi nói: Mình đang chơi, bạn chờ lượt nhé","Đẩy bạn ra thật mạnh để giành lại bóng cho bằng được","Nói những lời khó nghe với bạn rồi bỏ đi không chơi"],answer:0},{id:"dd2-kiem-che-cam-xuc-20",type:"mc",q:"Lan bị điểm chưa tốt, rất buồn. Cách nào giúp Lan?",emoji:"📄",explain:"Chia sẻ và tìm cách cố gắng giúp Lan vui lên.",options:["Xé bài kiểm tra đi để không ai nhìn thấy","Kể với mẹ, cùng xem lại bài để cố gắng","Khóc cả ngày, không chịu ăn cơm"],answer:1},{id:"dd2-kiem-che-cam-xuc-21",type:"tf",q:"Khoa giận em trai nên đi ra ban công hít thở một lúc rồi mới quay lại nói chuyện. Khoa biết kiềm chế.",emoji:"🌬️",explain:"Đi ra chỗ khác một lúc giúp bình tĩnh.",answer:!0},{id:"dd2-kiem-che-cam-xuc-22",type:"multi",q:"Bạn trêu chọc làm em tức giận. Em có thể làm gì?",emoji:"🙅",explain:"Em không đánh bạn; nói rõ, tránh đi hoặc nhờ cô giúp.",options:["Nói rõ: Mình không thích bạn trêu như vậy","Đi ra chỗ khác","Báo cô nếu bạn vẫn trêu","Đánh bạn"],answers:[0,1,2]},{id:"dd2-kiem-che-cam-xuc-23",type:"mc",q:"Hà đang khóc to vì không được mua đồ chơi ở siêu thị. Hà nên làm gì?",emoji:"🛒",explain:"Bình tĩnh nói chuyện, không làm ồn nơi công cộng.",options:["Bình tĩnh, nói chuyện với mẹ khi về nhà","Nằm lăn ra sàn siêu thị, khóc to hơn nữa","Lấy hàng trên kệ ném xuống đất"],answer:0},{id:"dd2-kiem-che-cam-xuc-24",type:"order",q:"Sắp xếp việc Tùng làm khi bị bạn hiểu lầm.",emoji:"🤝",explain:"Bình tĩnh, lắng nghe, giải thích rồi làm lành.",items:["Bình tĩnh","Lắng nghe bạn nói","Giải thích nhẹ nhàng","Cùng bạn làm lành"]},{id:"dd2-kiem-che-cam-xuc-25",type:"tf",q:"Phúc giận bạn nên viết lời xấu về bạn lên bảng. Phúc kiềm chế tốt.",emoji:"✏️",explain:"Viết lời xấu làm bạn tổn thương, đó không phải kiềm chế.",answer:!1},{id:"dd2-kiem-che-cam-xuc-26",type:"mc",q:"Thấy bạn đang rất giận, em có thể làm gì?",emoji:"🫂",explain:"Giúp bạn bình tĩnh là quan tâm bạn.",options:["Trêu thêm cho bạn giận hơn nữa","Kể chuyện bạn giận cho cả lớp nghe","Nhẹ nhàng nói: Bạn hít thở sâu nhé"],answer:2},{id:"dd2-kiem-che-cam-xuc-27",type:"fill",q:"Khi tức giận, em hít thở sâu để bình …",emoji:"🌬️",explain:"Hít thở sâu giúp em bình tĩnh.",answer:["tĩnh","tinh"],loose:!0}]}],challenge:{questions:[{id:"dd2-kiem-che-cam-xuc-28",type:"match",q:"Nối việc làm với kết quả.",emoji:"🌤️",explain:"Kiềm chế cảm xúc giúp mọi chuyện tốt hơn.",pairs:[["Hít thở, đếm đến 10","Bình tĩnh lại"],["Ném đồ khi giận","Làm hỏng đồ"],["Nói nhẹ nhàng","Giải quyết được vấn đề"]]},{id:"dd2-kiem-che-cam-xuc-29",type:"mc",q:"Ngọc giận vì bạn không cho mượn bút màu. Cách nào phù hợp nhất?",emoji:"🖍️",explain:"Bình tĩnh tìm cách khác là phù hợp.",options:["Giật lấy hộp bút màu của bạn rồi chạy đi chỗ khác","Bình tĩnh hỏi lý do, mượn bạn khác hoặc dùng màu khác","Giận luôn, nói từ nay không chơi với bạn nữa"],answer:1},{id:"dd2-kiem-che-cam-xuc-19",type:"mc",q:"Đang chơi, Minh bị bạn giành mất bóng. Minh rất tức. Minh nên làm gì?",emoji:"⚽",explain:"Bình tĩnh và nói rõ ràng giúp giải quyết.",options:["Hít thở sâu, rồi nói: Mình đang chơi, bạn chờ lượt nhé","Đẩy bạn ra thật mạnh để giành lại bóng cho bằng được","Nói những lời khó nghe với bạn rồi bỏ đi không chơi"],answer:0},{id:"dd2-kiem-che-cam-xuc-20",type:"mc",q:"Lan bị điểm chưa tốt, rất buồn. Cách nào giúp Lan?",emoji:"📄",explain:"Chia sẻ và tìm cách cố gắng giúp Lan vui lên.",options:["Xé bài kiểm tra đi để không ai nhìn thấy","Kể với mẹ, cùng xem lại bài để cố gắng","Khóc cả ngày, không chịu ăn cơm"],answer:1},{id:"dd2-kiem-che-cam-xuc-22",type:"multi",q:"Bạn trêu chọc làm em tức giận. Em có thể làm gì?",emoji:"🙅",explain:"Em không đánh bạn; nói rõ, tránh đi hoặc nhờ cô giúp.",options:["Nói rõ: Mình không thích bạn trêu như vậy","Đi ra chỗ khác","Báo cô nếu bạn vẫn trêu","Đánh bạn"],answers:[0,1,2]},{id:"dd2-kiem-che-cam-xuc-25",type:"tf",q:"Phúc giận bạn nên viết lời xấu về bạn lên bảng. Phúc kiềm chế tốt.",emoji:"✏️",explain:"Viết lời xấu làm bạn tổn thương, đó không phải kiềm chế.",answer:!1}]},summary:["Em nhận ra khi mình đang tức giận, buồn bực.","Em hít thở sâu, đếm chậm để bình tĩnh.","Bình tĩnh rồi, em nói nhẹ nhàng để giải quyết."]}]},{id:"tim-kiem-ho-tro",title:"Tìm kiếm sự hỗ trợ",lessons:[{id:"dd2-ho-tro-o-truong",title:"Bài 13: Tìm kiếm sự hỗ trợ ở trường",weeks:[27,28],learn:[{title:"Khi nào cần hỗ trợ?",text:"Khi bị ốm, bị ngã, bị bắt nạt, mất đồ hay gặp bài khó, em cần tìm người giúp.",example:"🤒 🤕 😟 ❓"},{title:"Ai giúp em ở trường?",text:"Thầy cô, cô y tế, bác bảo vệ, các anh chị và bạn bè có thể giúp em.",example:"👩‍🏫 👩‍⚕️ 💂 👫"},{title:"Nhờ giúp thế nào?",text:"Em nói rõ: em là ai, chuyện gì xảy ra, em cần giúp gì. Được giúp xong, em cảm ơn.",example:"💬 🙏"}],practice:[{questions:[{id:"dd2-ho-tro-o-truong-01",type:"tf",q:"Gặp khó khăn, em có thể nhờ người khác giúp đỡ.",emoji:"🙋",explain:"Nhờ giúp đỡ khi cần là việc làm đúng.",answer:!0},{id:"dd2-ho-tro-o-truong-02",type:"mc",q:"Bị đau bụng ở lớp, em báo ai?",emoji:"🤢",explain:"Cô giáo sẽ giúp em hoặc đưa em đến phòng y tế.",options:["Không báo ai","Cô giáo","Bạn nhỏ lớp dưới"],answer:1},{id:"dd2-ho-tro-o-truong-03",type:"tf",q:"Bị bạn bắt nạt, em nên giấu kín không nói với ai.",emoji:"😟",explain:"Em cần báo thầy cô hoặc bố mẹ để được giúp.",answer:!1},{id:"dd2-ho-tro-o-truong-04",type:"mc",q:"Bị ngã trầy chân ở sân trường, em đến đâu?",emoji:"🩹",explain:"Cô y tế sẽ rửa và băng vết thương.",options:["Phòng y tế trường","Căng tin của trường","Thư viện của trường"],answer:0},{id:"dd2-ho-tro-o-truong-05",type:"mc",q:"Chưa hiểu bài, em nhờ ai?",emoji:"❓",explain:"Hỏi thầy cô, bạn bè giúp em hiểu bài.",options:["Không hỏi ai, tự bỏ qua","Người lạ ngoài cổng trường","Thầy cô hoặc bạn học tốt"],answer:2},{id:"dd2-ho-tro-o-truong-06",type:"tf",q:"Được giúp đỡ xong, em nói lời cảm ơn.",emoji:"🙏",explain:"Cảm ơn thể hiện lòng biết ơn.",answer:!0},{id:"dd2-ho-tro-o-truong-07",type:"mc",q:"Ai trông coi cổng trường và giúp giữ an toàn?",emoji:"💂",explain:"Bác bảo vệ giúp giữ an toàn ở trường.",options:["Bạn cùng bàn","Cô bán hàng rong","Bác bảo vệ"],answer:2},{id:"dd2-ho-tro-o-truong-08",type:"tf",q:"Chỉ những bạn yếu mới cần nhờ giúp đỡ.",emoji:"🤝",explain:"Ai cũng có lúc cần sự giúp đỡ.",answer:!1},{id:"dd2-ho-tro-o-truong-09",type:"mc",q:"Bạn nào biết tìm sự hỗ trợ?",emoji:"🖊️",explain:"Nhờ cô giúp là biết tìm sự hỗ trợ.",options:["Bạn Hà mất bút, nhờ cô giáo giúp tìm","Bạn Tùng mất bút, ngồi khóc mãi","Bạn Bình mất bút, lấy bút của bạn"],answer:0}]},{questions:[{id:"dd2-ho-tro-o-truong-10",type:"match",q:"Nối tình huống với người có thể giúp em ở trường.",emoji:"🏫",explain:"Biết nhờ đúng người giúp việc được giải quyết nhanh.",pairs:[["Bị ngã chảy máu","Cô y tế"],["Chưa hiểu bài","Thầy cô giáo"],["Thấy người lạ trèo vào trường","Bác bảo vệ"],["Quên bút chì","Bạn cùng bàn"]]},{id:"dd2-ho-tro-o-truong-11",type:"order",q:"Sắp xếp các bước nhờ giúp đỡ.",emoji:"🙋",explain:"Tìm người, nói rõ, lắng nghe và cảm ơn.",items:["Tìm người có thể giúp","Chào và nói rõ điều cần giúp","Lắng nghe hướng dẫn","Cảm ơn"]},{id:"dd2-ho-tro-o-truong-12",type:"multi",q:"Lời nhờ giúp nào rõ ràng, lễ phép?",emoji:"💬",explain:"Lời nhờ giúp cần lễ phép và nói rõ chuyện gì.",options:["Thưa cô, em bị đau đầu, em cần xuống phòng y tế ạ","Cô ơi, em làm mất cặp ở sân trường, cô giúp em tìm với ạ","Này, giúp tôi đi","Ê, đưa đây"],answers:[0,1]},{id:"dd2-ho-tro-o-truong-13",type:"mc",q:"Vì sao cần tìm sự hỗ trợ khi gặp khó khăn?",emoji:"🛟",explain:"Được hỗ trợ đúng lúc giúp em an toàn, vượt qua khó khăn.",options:["Để được nghỉ học ở nhà chơi cả ngày","Để vấn đề được giải quyết, em được an toàn","Để người khác làm hộ hết mọi việc cho em"],answer:1},{id:"dd2-ho-tro-o-truong-14",type:"tf",q:"Nếu người đầu tiên chưa giúp được, em có thể nhờ người khác.",emoji:"🔁",explain:"Em kiên trì tìm người có thể giúp.",answer:!0},{id:"dd2-ho-tro-o-truong-15",type:"mc",q:"Nghe chuông báo cháy ở trường, em làm gì?",emoji:"🔔",explain:"Làm theo hướng dẫn của thầy cô để thoát ra an toàn.",options:["Làm theo hướng dẫn của thầy cô","Chạy ngược về lớp lấy cặp sách","Trốn vào nhà vệ sinh một mình"],answer:0},{id:"dd2-ho-tro-o-truong-16",type:"tf",q:"Nhờ giúp đỡ cả những việc mình tự làm được là đúng.",emoji:"🙅",explain:"Việc tự làm được thì em tự làm.",answer:!1},{id:"dd2-ho-tro-o-truong-17",type:"mc",q:"Thấy bạn bị ngã chảy máu, em làm gì?",emoji:"🤕",explain:"Báo người lớn để bạn được giúp kịp thời.",options:["Đứng xem rồi kể cho các bạn","Sợ quá nên bỏ chạy đi chỗ khác","Báo ngay thầy cô hoặc cô y tế"],answer:2},{id:"dd2-ho-tro-o-truong-18",type:"mc",q:"Bị mất đồ ở trường, em nên làm gì?",emoji:"🎒",explain:"Cô giáo sẽ giúp em tìm lại đồ.",options:["Lấy đồ của bạn khác thay","Báo cô giáo để được giúp","Im lặng"],answer:1}]},{questions:[{id:"dd2-ho-tro-o-truong-19",type:"mc",q:"Có anh lớp trên chặn đường đòi lấy tiền của Nam. Nam nên làm gì?",emoji:"🛡️",explain:"Báo người lớn để được bảo vệ an toàn.",options:["Đưa tiền cho anh rồi giấu, không kể với ai","Tránh đi và báo ngay thầy cô hoặc bác bảo vệ","Đánh nhau với anh để giữ tiền lại"],answer:1},{id:"dd2-ho-tro-o-truong-20",type:"mc",q:"Tan học, chưa thấy bố mẹ đến đón, Lan nên làm gì?",emoji:"🏫",explain:"Ở lại trường và nhờ người lớn ở trường liên lạc với bố mẹ.",options:["Ở lại trường, báo cô giáo hoặc bác bảo vệ","Đi theo người lạ khi người đó mời đưa về","Tự đi bộ về nhà một mình"],answer:0},{id:"dd2-ho-tro-o-truong-21",type:"tf",q:"Vy bị bạn trêu nhiều lần, Vy kể với cô giáo và bố mẹ. Vy làm đúng.",emoji:"👧",explain:"Kể với người lớn giúp Vy được bảo vệ.",answer:!0},{id:"dd2-ho-tro-o-truong-22",type:"multi",q:"Trong giờ học, Khoa thấy chóng mặt. Khoa nên làm gì?",emoji:"😵",explain:"Báo cô ngay để được chăm sóc.",options:["Giơ tay báo cô","Nói rõ mình chóng mặt","Cố ngồi im chịu đựng","Nhờ bạn báo cô nếu không đứng dậy được"],answers:[0,1,3]},{id:"dd2-ho-tro-o-truong-23",type:"mc",q:"Bạn kể với em đang bị một bạn khác bắt nạt và rất sợ. Em làm gì?",emoji:"😨",explain:"Cùng bạn tìm thầy cô là giúp bạn đúng cách.",options:["Bảo bạn im lặng, đừng kể với ai","Kể cho cả lớp nghe để trêu bạn","Động viên bạn và cùng bạn báo thầy cô"],answer:2},{id:"dd2-ho-tro-o-truong-24",type:"order",q:"Thấy hai bạn đánh nhau ở sân trường, sắp xếp việc em làm.",emoji:"🏃",explain:"Em không lao vào; gọi và chỉ chỗ cho người lớn.",items:["Không lao vào đánh cùng","Gọi thầy cô hoặc bác bảo vệ","Chỉ chỗ cho người lớn đến"]},{id:"dd2-ho-tro-o-truong-25",type:"tf",q:"Chi làm bài chưa được nhưng ngại hỏi cô nên chép bài của bạn. Chi làm vậy là đúng.",emoji:"📝",explain:"Chi nên mạnh dạn hỏi cô để hiểu bài.",answer:!1},{id:"dd2-ho-tro-o-truong-26",type:"mc",q:"Dũng nhờ cô giúp nhưng cô đang bận giảng bài. Dũng nên làm gì?",emoji:"✋",explain:"Chờ đúng lúc, việc gấp thì giơ tay báo cô.",options:["Chạy lên kéo áo cô liên tục cho cô chú ý","Thôi bỏ, không hỏi cô nữa cho đỡ ngại","Chờ cô giảng xong rồi hỏi, nếu gấp thì giơ tay"],answer:2},{id:"dd2-ho-tro-o-truong-27",type:"fill",q:"Bị ngã trầy chân ở trường, em đến phòng … tế.",emoji:"🩹",explain:"Em đến phòng y tế để được rửa và băng vết thương.",answer:["y"],loose:!0}]}],challenge:{questions:[{id:"dd2-ho-tro-o-truong-28",type:"match",q:"Nối tình huống với việc nên làm.",emoji:"🛟",explain:"Biết tìm sự hỗ trợ giúp em và bạn an toàn.",pairs:[["Bị bắt nạt","Báo thầy cô, bố mẹ"],["Chưa có người đón","Ở lại trường, báo cô"],["Thấy bạn bị thương","Gọi cô y tế, thầy cô"]]},{id:"dd2-ho-tro-o-truong-29",type:"mc",q:"Phúc bị mất áo khoác trong lớp, cô đã giúp tìm nhưng chưa thấy. Phúc nên làm gì tiếp?",emoji:"🧥",explain:"Kiên trì nhờ thêm người giúp.",options:["Kể với bố mẹ và nhờ cô báo cả trường","Lấy áo khoác của bạn khác mặc về","Thôi không nói với ai nữa, bỏ qua"],answer:0},{id:"dd2-ho-tro-o-truong-19",type:"mc",q:"Có anh lớp trên chặn đường đòi lấy tiền của Nam. Nam nên làm gì?",emoji:"🛡️",explain:"Báo người lớn để được bảo vệ an toàn.",options:["Đưa tiền cho anh rồi giấu, không kể với ai","Tránh đi và báo ngay thầy cô hoặc bác bảo vệ","Đánh nhau với anh để giữ tiền lại"],answer:1},{id:"dd2-ho-tro-o-truong-20",type:"mc",q:"Tan học, chưa thấy bố mẹ đến đón, Lan nên làm gì?",emoji:"🏫",explain:"Ở lại trường và nhờ người lớn ở trường liên lạc với bố mẹ.",options:["Ở lại trường, báo cô giáo hoặc bác bảo vệ","Đi theo người lạ khi người đó mời đưa về","Tự đi bộ về nhà một mình"],answer:0},{id:"dd2-ho-tro-o-truong-23",type:"mc",q:"Bạn kể với em đang bị một bạn khác bắt nạt và rất sợ. Em làm gì?",emoji:"😨",explain:"Cùng bạn tìm thầy cô là giúp bạn đúng cách.",options:["Bảo bạn im lặng, đừng kể với ai","Kể cho cả lớp nghe để trêu bạn","Động viên bạn và cùng bạn báo thầy cô"],answer:2},{id:"dd2-ho-tro-o-truong-26",type:"mc",q:"Dũng nhờ cô giúp nhưng cô đang bận giảng bài. Dũng nên làm gì?",emoji:"✋",explain:"Chờ đúng lúc, việc gấp thì giơ tay báo cô.",options:["Chạy lên kéo áo cô liên tục cho cô chú ý","Thôi bỏ, không hỏi cô nữa cho đỡ ngại","Chờ cô giảng xong rồi hỏi, nếu gấp thì giơ tay"],answer:2}]},summary:["Gặp khó khăn, em mạnh dạn tìm người giúp.","Ở trường, thầy cô, cô y tế, bác bảo vệ luôn sẵn sàng giúp em.","Em nói rõ điều cần giúp và cảm ơn người giúp mình."]},{id:"dd2-ho-tro-o-nha-noi-cong-cong",title:"Bài 14: Tìm kiếm sự hỗ trợ ở nhà và nơi công cộng",weeks:[29,30],learn:[{title:"Ở nhà",text:"Gặp khó khăn ở nhà, em nhờ ông bà, bố mẹ, anh chị hoặc hàng xóm tin cậy.",example:"👨‍👩‍👧 🏠"},{title:"Nơi công cộng",text:"Bị lạc, em đứng yên ở chỗ an toàn, nhờ chú công an, nhân viên bảo vệ, cô bán hàng giúp.",example:"👮 🏬"},{title:"Số điện thoại cần nhớ",text:"Em nhớ số điện thoại của bố mẹ. 113: công an. 114: cứu hỏa. 115: cấp cứu. 111: bảo vệ trẻ em.",example:"📞 113 · 114 · 115 · 111"}],practice:[{questions:[{id:"dd2-ho-tro-o-nha-noi-cong-cong-01",type:"mc",q:"Bị lạc ở siêu thị, em nhờ ai?",emoji:"🏬",explain:"Nhân viên, bảo vệ sẽ giúp em tìm bố mẹ.",options:["Người lạ mời đi chơi","Nhân viên siêu thị hoặc bảo vệ","Không nhờ ai, tự đi tìm khắp nơi"],answer:1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-02",type:"tf",q:"Em cần nhớ số điện thoại của bố mẹ.",emoji:"📞",explain:"Nhớ số điện thoại giúp người khác liên lạc với bố mẹ khi em cần.",answer:!0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-03",type:"tf",q:"Người lạ cho kẹo và rủ đi, em đi theo.",emoji:"🍬",explain:"Em không đi theo người lạ.",answer:!1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-04",type:"mc",q:"Số điện thoại gọi cứu hỏa là số nào?",emoji:"🚒",explain:"114 là số gọi cứu hỏa.",options:["114","115","113"],answer:0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-05",type:"mc",q:"Số điện thoại gọi cấp cứu là số nào?",emoji:"🚑",explain:"115 là số gọi cấp cứu.",options:["114","113","115"],answer:2},{id:"dd2-ho-tro-o-nha-noi-cong-cong-06",type:"mc",q:"Số điện thoại gọi công an là số nào?",emoji:"🚓",explain:"113 là số gọi công an.",options:["115","113","114"],answer:1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-07",type:"tf",q:"Ở nhà, khi không làm được bài, em có thể nhờ bố mẹ, anh chị hướng dẫn.",emoji:"📚",explain:"Người thân sẵn sàng giúp em.",answer:!0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-08",type:"mc",q:"Bị lạc, em nên đứng ở đâu?",emoji:"📍",explain:"Đứng yên chỗ an toàn giúp bố mẹ dễ tìm.",options:["Giữa lòng đường, nơi xe cộ qua lại","Chỗ an toàn, dễ thấy, gần nơi bị lạc","Trong một góc tối, khuất sau tường"],answer:1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-09",type:"tf",q:"Nhờ giúp đỡ, em cần nói to và rõ ràng.",emoji:"🗣️",explain:"Nói rõ giúp người khác hiểu em cần gì.",answer:!0}]},{questions:[{id:"dd2-ho-tro-o-nha-noi-cong-cong-10",type:"match",q:"Nối số điện thoại với nơi giúp đỡ.",emoji:"📞",explain:"Các số điện thoại khẩn cấp em cần nhớ.",pairs:[["113","Công an"],["114","Cứu hỏa"],["115","Cấp cứu"],["111","Bảo vệ trẻ em"]]},{id:"dd2-ho-tro-o-nha-noi-cong-cong-11",type:"order",q:"Bị lạc ở công viên, sắp xếp việc em làm.",emoji:"🏞️",explain:"Bình tĩnh, nhờ người tin cậy, nói thông tin và chờ.",items:["Bình tĩnh, đứng yên chỗ an toàn","Tìm chú bảo vệ hoặc công an","Nói tên em và số điện thoại của bố mẹ","Chờ bố mẹ đến đón"]},{id:"dd2-ho-tro-o-nha-noi-cong-cong-12",type:"multi",q:"Người nào em có thể nhờ giúp khi bị lạc?",emoji:"👮",explain:"Em không lên xe, không đi theo người lạ.",options:["Chú công an","Nhân viên bảo vệ","Người lạ rủ lên xe đi","Cô nhân viên bán hàng trong cửa hàng"],answers:[0,1,3]},{id:"dd2-ho-tro-o-nha-noi-cong-cong-13",type:"mc",q:"Vì sao em cần nhớ địa chỉ nhà?",emoji:"🏠",explain:"Nhớ địa chỉ giúp em được giúp đỡ khi bị lạc.",options:["Để người khác giúp đưa em về khi cần","Để khoe với các bạn trong lớp","Không cần nhớ, vì đã có bố mẹ nhớ hộ"],answer:0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-14",type:"tf",q:"Gọi số khẩn cấp để trêu đùa là việc vui, không sao.",emoji:"🚫",explain:"Gọi trêu làm mất thời gian của người đang cần cứu giúp.",answer:!1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-15",type:"mc",q:"Ở nhà một mình, có người lạ gõ cửa xin vào. Em làm gì?",emoji:"🚪",explain:"Không mở cửa cho người lạ khi ở nhà một mình.",options:["Mở cửa mời người lạ vào nhà","Nói với người lạ là nhà không có ai","Không mở cửa, gọi điện cho bố mẹ"],answer:2},{id:"dd2-ho-tro-o-nha-noi-cong-cong-16",type:"tf",q:"Thấy nhà hàng xóm bốc khói, em báo ngay người lớn.",emoji:"🔥",explain:"Báo người lớn để gọi 114 kịp thời.",answer:!0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-17",type:"mc",q:"Bố mẹ đi vắng, em bị sốt cao. Em nên làm gì?",emoji:"🤒",explain:"Nhờ người lớn giúp, không tự uống thuốc.",options:["Nằm im một mình trong phòng, không nói với ai","Tự tìm thuốc trong tủ uống lung tung","Gọi điện cho bố mẹ hoặc nhờ hàng xóm tin cậy"],answer:2},{id:"dd2-ho-tro-o-nha-noi-cong-cong-18",type:"mc",q:"Muốn nhờ cô bán hàng giúp khi bị lạc, em nói gì?",emoji:"🛍️",explain:"Nói lễ phép, rõ ràng giúp cô hiểu và giúp em.",options:["Cô ơi, cháu bị lạc mẹ, cô giúp cháu với ạ","Ê, mẹ tôi đâu rồi? Chỉ cho tôi xem!","Không nói gì, chỉ đứng khóc mãi thôi"],answer:0}]},{questions:[{id:"dd2-ho-tro-o-nha-noi-cong-cong-19",type:"mc",q:"Đi chợ cùng mẹ, Hà bị lạc. Một người lạ nói: “Đi theo cô, cô đưa về.” Hà nên làm gì?",emoji:"🧺",explain:"Không đi theo người lạ, nhờ người ở chỗ cố định giúp.",options:["Đi theo người lạ ngay, không hỏi gì","Không đi, nhờ cô bán hàng gần đó gọi cho mẹ","Chạy một mình ra đường lớn để tìm mẹ ngay"],answer:1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-20",type:"mc",q:"Em thấy một bạn nhỏ đứng khóc một mình ở công viên. Em làm gì?",emoji:"😭",explain:"Báo người lớn là cách giúp an toàn nhất.",options:["Báo bố mẹ hoặc chú bảo vệ để giúp bạn","Dắt bạn đi tìm khắp nơi một mình","Mặc kệ"],answer:0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-21",type:"tf",q:"Ông bị ngã ở nhà, không dậy được. Minh gọi bố mẹ và hàng xóm đến giúp. Minh làm đúng.",emoji:"👴",explain:"Tìm người lớn giúp kịp thời là đúng.",answer:!0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-22",type:"multi",q:"Bé Chi bị lạc ở siêu thị. Chi cần nói gì với nhân viên?",emoji:"🛒",explain:"Thông tin giúp tìm bố mẹ nhanh: tên, số điện thoại, đi cùng ai.",options:["Tên của Chi","Số điện thoại của bố mẹ","Mặc áo màu gì, đi cùng ai","Món đồ chơi Chi thích nhất"],answers:[0,1,2]},{id:"dd2-ho-tro-o-nha-noi-cong-cong-23",type:"mc",q:"Có người lạ nhắn tin rủ Tùng gặp riêng và dặn không nói với bố mẹ. Tùng nên làm gì?",emoji:"📱",explain:"Người lạ dặn giữ bí mật là dấu hiệu nguy hiểm.",options:["Đi gặp một mình như đã hẹn","Giữ bí mật, không kể với ai","Không đi, kể ngay với bố mẹ"],answer:2},{id:"dd2-ho-tro-o-nha-noi-cong-cong-24",type:"order",q:"Nhà có cháy nhỏ, sắp xếp việc em làm.",emoji:"🔥",explain:"Báo động, thoát ra an toàn và gọi cứu hỏa.",items:["Hô to báo mọi người","Thoát ra ngoài theo lối an toàn","Nhờ người lớn gọi 114"]},{id:"dd2-ho-tro-o-nha-noi-cong-cong-25",type:"tf",q:"Bị lạc, Bình chạy thật nhanh khắp nơi để tìm mẹ. Đó là cách tốt nhất.",emoji:"🏃",explain:"Chạy khắp nơi khiến mẹ khó tìm; Bình nên đứng yên và nhờ người tin cậy.",answer:!1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-26",type:"mc",q:"Em bị một người lạ chạm vào người làm em sợ. Em làm gì?",emoji:"🛑",explain:"Nói không, tránh xa và kể với người tin cậy.",options:["Im lặng, không dám kể với ai cả","Nói “Không!”, chạy đi và kể với bố mẹ","Đi theo người đó khi được rủ"],answer:1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-27",type:"fill",q:"Số điện thoại gọi cấp cứu là …",emoji:"🚑",explain:"Số gọi cấp cứu là 115.",answer:["115","một trăm mười lăm","mot tram muoi lam"],loose:!0}]}],challenge:{questions:[{id:"dd2-ho-tro-o-nha-noi-cong-cong-28",type:"match",q:"Nối tình huống với cách tìm hỗ trợ.",emoji:"🛟",explain:"Biết tìm hỗ trợ đúng cách giúp em an toàn.",pairs:[["Bị lạc ở siêu thị","Nhờ nhân viên, bảo vệ"],["Thấy cháy nhà","Báo người lớn gọi 114"],["Người lạ gõ cửa","Không mở, gọi bố mẹ"],["Người thân bị ngất","Nhờ người lớn gọi 115"]]},{id:"dd2-ho-tro-o-nha-noi-cong-cong-29",type:"mc",q:"Đi biển cùng gia đình, Ngọc lạc mất bố mẹ. Cách nào an toàn nhất?",emoji:"🏖️",explain:"Nhân viên cứu hộ, bảo vệ sẽ giúp em tìm bố mẹ.",options:["Đi xuống nước tìm","Đến chỗ nhân viên cứu hộ hoặc chòi bảo vệ","Theo một nhóm người lạ về khách sạn"],answer:1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-19",type:"mc",q:"Đi chợ cùng mẹ, Hà bị lạc. Một người lạ nói: “Đi theo cô, cô đưa về.” Hà nên làm gì?",emoji:"🧺",explain:"Không đi theo người lạ, nhờ người ở chỗ cố định giúp.",options:["Đi theo người lạ ngay, không hỏi gì","Không đi, nhờ cô bán hàng gần đó gọi cho mẹ","Chạy một mình ra đường lớn để tìm mẹ ngay"],answer:1},{id:"dd2-ho-tro-o-nha-noi-cong-cong-20",type:"mc",q:"Em thấy một bạn nhỏ đứng khóc một mình ở công viên. Em làm gì?",emoji:"😭",explain:"Báo người lớn là cách giúp an toàn nhất.",options:["Báo bố mẹ hoặc chú bảo vệ để giúp bạn","Dắt bạn đi tìm khắp nơi một mình","Mặc kệ"],answer:0},{id:"dd2-ho-tro-o-nha-noi-cong-cong-23",type:"mc",q:"Có người lạ nhắn tin rủ Tùng gặp riêng và dặn không nói với bố mẹ. Tùng nên làm gì?",emoji:"📱",explain:"Người lạ dặn giữ bí mật là dấu hiệu nguy hiểm.",options:["Đi gặp một mình như đã hẹn","Giữ bí mật, không kể với ai","Không đi, kể ngay với bố mẹ"],answer:2},{id:"dd2-ho-tro-o-nha-noi-cong-cong-26",type:"mc",q:"Em bị một người lạ chạm vào người làm em sợ. Em làm gì?",emoji:"🛑",explain:"Nói không, tránh xa và kể với người tin cậy.",options:["Im lặng, không dám kể với ai cả","Nói “Không!”, chạy đi và kể với bố mẹ","Đi theo người đó khi được rủ"],answer:1}]},summary:["Em nhớ số điện thoại và địa chỉ nhà mình.","Bị lạc, em đứng yên ở chỗ an toàn và nhờ người đáng tin giúp.","Em không đi theo người lạ."]}]},{id:"quy-dinh-noi-cong-cong",title:"Tuân thủ quy định nơi công cộng",lessons:[{id:"dd2-quy-dinh-noi-cong-cong",title:"Bài 15: Quy định nơi công cộng",weeks:[31,32],learn:[{title:"Nơi công cộng",text:"Công viên, thư viện, bệnh viện, rạp chiếu phim, xe buýt là nơi công cộng, nhiều người cùng dùng.",example:"🏞️ 📚 🏥 🎬 🚌"},{title:"Một số quy định",text:"Xếp hàng, giữ trật tự, không xả rác, không bẻ cây hái hoa, đi đúng lối.",example:"🚶‍♂️🚶‍♀️ 🤫 🗑️ 🌷"},{title:"Vì sao cần tuân thủ?",text:"Tuân thủ quy định giúp nơi công cộng an toàn, sạch đẹp, mọi người đều thoải mái.",example:"😊 ✨"}],practice:[{questions:[{id:"dd2-quy-dinh-noi-cong-cong-01",type:"mc",q:"Nơi nào là nơi công cộng?",emoji:"🏞️",explain:"Công viên là nơi nhiều người cùng đến.",options:["Công viên","Phòng ngủ của em","Tủ quần áo"],answer:0},{id:"dd2-quy-dinh-noi-cong-cong-02",type:"tf",q:"Trong thư viện, em cần giữ yên lặng.",emoji:"📚",explain:"Giữ yên lặng để mọi người đọc sách.",answer:!0},{id:"dd2-quy-dinh-noi-cong-cong-03",type:"tf",q:"Ở bệnh viện, em có thể chạy nhảy, nói to.",emoji:"🏥",explain:"Bệnh viện cần yên tĩnh để người bệnh nghỉ ngơi.",answer:!1},{id:"dd2-quy-dinh-noi-cong-cong-04",type:"mc",q:"Mua vé xem phim, em làm gì?",emoji:"🎟️",explain:"Xếp hàng là tuân thủ quy định.",options:["Chen lên trước mọi người","Đứng chắn trước quầy vé","Xếp hàng chờ đến lượt"],answer:2},{id:"dd2-quy-dinh-noi-cong-cong-05",type:"mc",q:"Đi công viên, em bỏ rác ở đâu?",emoji:"🗑️",explain:"Bỏ rác đúng nơi giữ công viên sạch đẹp.",options:["Bãi cỏ xanh","Hồ nước nhỏ","Thùng rác"],answer:2},{id:"dd2-quy-dinh-noi-cong-cong-06",type:"tf",q:"Hái hoa ở vườn hoa công viên là đúng quy định.",emoji:"🌷",explain:"Hoa ở công viên để mọi người cùng ngắm.",answer:!1},{id:"dd2-quy-dinh-noi-cong-cong-07",type:"mc",q:"Trên xe buýt, em nên làm gì?",emoji:"🚌",explain:"Nhường ghế là văn minh nơi công cộng.",options:["Nhường ghế cho người già, em nhỏ","Ngồi chiếm luôn hai ghế cho rộng","Thò tay, thò đầu ra cửa sổ"],answer:0},{id:"dd2-quy-dinh-noi-cong-cong-08",type:"tf",q:"Tuân thủ quy định nơi công cộng giúp mọi người cùng thoải mái.",emoji:"😊",explain:"Ai cũng giữ quy định thì nơi công cộng dễ chịu.",answer:!0},{id:"dd2-quy-dinh-noi-cong-cong-09",type:"mc",q:"Biển báo “Không giẫm lên cỏ” nghĩa là gì?",emoji:"🌱",explain:"Em đi đúng lối để bảo vệ thảm cỏ.",options:["Được chạy nhảy thoải mái trên cỏ","Đi đúng lối, không giẫm lên cỏ","Được hái cỏ, ngắt hoa mang về"],answer:1}]},{questions:[{id:"dd2-quy-dinh-noi-cong-cong-10",type:"match",q:"Nối nơi công cộng với quy định.",emoji:"🏙️",explain:"Mỗi nơi công cộng có quy định riêng.",pairs:[["Thư viện","Giữ yên lặng"],["Bệnh viện","Đi nhẹ, nói khẽ"],["Rạp chiếu phim","Không nói chuyện to khi xem"],["Xe buýt","Nhường ghế cho người cần"]]},{id:"dd2-quy-dinh-noi-cong-cong-11",type:"multi",q:"Việc nào đúng quy định nơi công cộng?",emoji:"✅",explain:"Viết vẽ lên tường làm hỏng của chung.",options:["Xếp hàng chờ đến lượt","Bỏ rác vào thùng","Viết vẽ lên tường bảo tàng","Đi đúng lối đi"],answers:[0,1,3]},{id:"dd2-quy-dinh-noi-cong-cong-12",type:"mc",q:"Vì sao phải xếp hàng?",emoji:"🚶",explain:"Xếp hàng giúp mọi người đến lượt công bằng.",options:["Để công bằng, trật tự, không chen lấn","Để mọi người mất thêm thời gian","Để mình được lên trước người khác"],answer:0},{id:"dd2-quy-dinh-noi-cong-cong-13",type:"tf",q:"Ở nơi công cộng chỉ người lớn mới cần tuân thủ quy định.",emoji:"🧒",explain:"Trẻ em cũng cần tuân thủ quy định.",answer:!1},{id:"dd2-quy-dinh-noi-cong-cong-14",type:"order",q:"Sắp xếp việc em làm khi đi xe buýt.",emoji:"🚌",explain:"Xếp hàng, lên xuống khi xe dừng hẳn, ngồi bám chắc.",items:["Xếp hàng chờ xe","Lên xe khi xe dừng hẳn","Ngồi ngay ngắn hoặc bám chắc tay vịn","Xuống xe khi xe dừng hẳn"]},{id:"dd2-quy-dinh-noi-cong-cong-15",type:"mc",q:"Ở rạp chiếu phim, em có điều muốn nói với mẹ. Em làm gì?",emoji:"🎬",explain:"Nói nhỏ để không làm phiền người khác.",options:["Nói to cho mẹ nghe rõ","Đứng lên nói","Nói thật nhỏ"],answer:2},{id:"dd2-quy-dinh-noi-cong-cong-16",type:"tf",q:"Đọc sách ở thư viện xong, em để sách đúng chỗ hoặc nơi quy định.",emoji:"📖",explain:"Để sách đúng chỗ giúp người sau dễ tìm.",answer:!0},{id:"dd2-quy-dinh-noi-cong-cong-17",type:"mc",q:"Đi tham quan bảo tàng, em làm gì?",emoji:"🏛️",explain:"Hiện vật cần được giữ gìn cẩn thận.",options:["Sờ tay vào từng hiện vật trưng bày cho biết","Ngắm hiện vật, không chạm khi chưa được phép","Chạy đuổi nhau giữa các phòng"],answer:1},{id:"dd2-quy-dinh-noi-cong-cong-18",type:"tf",q:"Thấy biển cấm, em vẫn đi vào vì muốn khám phá.",emoji:"⛔",explain:"Biển cấm báo nguy hiểm hoặc quy định, em làm theo.",answer:!1}]},{questions:[{id:"dd2-quy-dinh-noi-cong-cong-19",type:"mc",q:"Đến lượt mua kem, có bà cụ đứng sau. Em có thể làm gì?",emoji:"🍦",explain:"Nhường người già là việc làm đẹp.",options:["Chen lên mua thật nhanh cho xong","Nhường bà mua trước nếu bà vội","Đứng chắn, không cho bà mua"],answer:1},{id:"dd2-quy-dinh-noi-cong-cong-20",type:"mc",q:"Nam ăn bánh ở công viên nhưng không thấy thùng rác gần đó. Nam nên làm gì?",emoji:"🍪",explain:"Giữ rác lại để bỏ đúng nơi.",options:["Cất vỏ bánh vào túi, tìm thùng rác bỏ sau","Vứt vỏ bánh xuống bãi cỏ, chỗ không ai thấy","Nhét vỏ bánh vào bụi cây gần đó"],answer:0},{id:"dd2-quy-dinh-noi-cong-cong-21",type:"tf",q:"Trên xe buýt, Lan đứng dậy nhường ghế cho cô bế em bé. Lan làm đúng.",emoji:"👩‍🍼",explain:"Nhường ghế cho người cần là văn minh.",answer:!0},{id:"dd2-quy-dinh-noi-cong-cong-22",type:"multi",q:"Em đi thăm bà đang nằm bệnh viện. Em cần làm gì?",emoji:"🏥",explain:"Bệnh viện cần yên tĩnh cho người bệnh.",options:["Đi nhẹ, nói khẽ","Không chạy nhảy ở hành lang","Bật nhạc to cho bà vui","Làm theo hướng dẫn của y tá"],answers:[0,1,3]},{id:"dd2-quy-dinh-noi-cong-cong-23",type:"mc",q:"Bạn rủ Khoa trèo qua rào để vào khu vực có biển cấm ở công viên. Khoa nên làm gì?",emoji:"🚧",explain:"Khu vực cấm có thể nguy hiểm.",options:["Trèo qua rào cùng bạn cho vui","Tranh trèo qua trước bạn","Từ chối, khuyên bạn đi đúng lối"],answer:2},{id:"dd2-quy-dinh-noi-cong-cong-24",type:"order",q:"Sắp xếp việc em làm khi mượn sách ở thư viện.",emoji:"📚",explain:"Chọn sách, xếp hàng mượn, giữ gìn và trả đúng hẹn.",items:["Nhẹ nhàng chọn sách","Xếp hàng đến quầy mượn","Đọc và giữ sách cẩn thận","Trả sách đúng hẹn"]},{id:"dd2-quy-dinh-noi-cong-cong-25",type:"tf",q:"Dũng khắc tên mình lên thân cây trong công viên để làm kỷ niệm. Dũng làm đúng.",emoji:"🌳",explain:"Khắc lên cây làm hại cây, hỏng cảnh quan chung.",answer:!1},{id:"dd2-quy-dinh-noi-cong-cong-26",type:"mc",q:"Xếp hàng vào cổng sở thú, có bạn chen lên trước em. Em làm gì?",emoji:"🦁",explain:"Nhắc nhẹ nhàng giữ trật tự chung.",options:["Đẩy mạnh bạn ra khỏi hàng","Chen lên đứng trước bạn","Nhẹ nhàng nhắc bạn xếp hàng"],answer:2},{id:"dd2-quy-dinh-noi-cong-cong-27",type:"fill",q:"Mua vé xem phim, em … hàng chờ đến lượt.",emoji:"🎟️",explain:"Em xếp hàng chờ đến lượt.",answer:["xếp","xep"],loose:!0}]}],challenge:{questions:[{id:"dd2-quy-dinh-noi-cong-cong-28",type:"match",q:"Nối việc làm với nhận xét.",emoji:"⚖️",explain:"Em chọn cách cư xử văn minh nơi công cộng.",pairs:[["Nhường ghế trên xe buýt","Văn minh"],["Chen lấn khi xếp hàng","Mất trật tự"],["Hái hoa ở công viên","Làm hỏng của chung"]]},{id:"dd2-quy-dinh-noi-cong-cong-29",type:"mc",q:"Đi thư viện, điện thoại của bố Ngọc đổ chuông to. Ngọc có thể nhắc bố điều gì?",emoji:"📱",explain:"Nhắc nhẹ nhàng để không làm phiền người khác.",options:["Bố ơi, mình để điện thoại im lặng nhé","Bố ơi, bố bật chuông to thêm nữa đi","Không cần nhắc, cứ để chuông kêu"],answer:0},{id:"dd2-quy-dinh-noi-cong-cong-19",type:"mc",q:"Đến lượt mua kem, có bà cụ đứng sau. Em có thể làm gì?",emoji:"🍦",explain:"Nhường người già là việc làm đẹp.",options:["Chen lên mua thật nhanh cho xong","Nhường bà mua trước nếu bà vội","Đứng chắn, không cho bà mua"],answer:1},{id:"dd2-quy-dinh-noi-cong-cong-21",type:"tf",q:"Trên xe buýt, Lan đứng dậy nhường ghế cho cô bế em bé. Lan làm đúng.",emoji:"👩‍🍼",explain:"Nhường ghế cho người cần là văn minh.",answer:!0},{id:"dd2-quy-dinh-noi-cong-cong-22",type:"multi",q:"Em đi thăm bà đang nằm bệnh viện. Em cần làm gì?",emoji:"🏥",explain:"Bệnh viện cần yên tĩnh cho người bệnh.",options:["Đi nhẹ, nói khẽ","Không chạy nhảy ở hành lang","Bật nhạc to cho bà vui","Làm theo hướng dẫn của y tá"],answers:[0,1,3]},{id:"dd2-quy-dinh-noi-cong-cong-25",type:"tf",q:"Dũng khắc tên mình lên thân cây trong công viên để làm kỷ niệm. Dũng làm đúng.",emoji:"🌳",explain:"Khắc lên cây làm hại cây, hỏng cảnh quan chung.",answer:!1}]},summary:["Nơi công cộng là nơi nhiều người cùng sử dụng.","Em xếp hàng, giữ trật tự, giữ vệ sinh nơi công cộng.","Tuân thủ quy định giúp mọi người an toàn, thoải mái."]},{id:"dd2-giu-gin-noi-cong-cong",title:"Bài 16: Em giữ gìn nơi công cộng",weeks:[33,35],learn:[{title:"Của chung",text:"Ghế đá, cây xanh, đèn đường, nhà vệ sinh công cộng là của chung, mọi người cùng giữ gìn.",example:"🪑 🌳 💡 🚻"},{title:"Giữ gìn thế nào?",text:"Em không viết vẽ bậy, không làm hỏng, không xả rác, dùng xong để lại sạch sẽ.",example:"🙅 🖍️  ·  🗑️ ✨"},{title:"Nhắc nhở mọi người",text:"Thấy người làm hỏng của chung, em nhẹ nhàng nhắc hoặc báo người lớn.",example:"💬 👨‍👩‍👧"}],practice:[{questions:[{id:"dd2-giu-gin-noi-cong-cong-01",type:"mc",q:"Đồ vật nào là của chung ở công viên?",emoji:"🪑",explain:"Ghế đá là của chung mọi người.",options:["Ba lô của em","Ghế đá","Áo khoác của mẹ"],answer:1},{id:"dd2-giu-gin-noi-cong-cong-02",type:"tf",q:"Viết vẽ lên ghế đá công viên là làm hỏng của chung.",emoji:"🖍️",explain:"Viết vẽ bậy làm bẩn, hỏng của chung.",answer:!0},{id:"dd2-giu-gin-noi-cong-cong-03",type:"tf",q:"Dùng nhà vệ sinh công cộng xong, không cần xả nước.",emoji:"🚻",explain:"Dùng xong, em xả nước để nhà vệ sinh sạch sẽ.",answer:!1},{id:"dd2-giu-gin-noi-cong-cong-04",type:"mc",q:"Thấy vòi nước công cộng bị rò, em làm gì?",emoji:"🚰",explain:"Báo để sửa, tránh lãng phí nước.",options:["Báo người quản lý hoặc người lớn","Mở vòi to thêm cho nước chảy mạnh","Đứng nghịch nước cho vui"],answer:0},{id:"dd2-giu-gin-noi-cong-cong-05",type:"mc",q:"Bạn nào giữ gìn nơi công cộng?",emoji:"♻️",explain:"Nhặt rác bỏ vào thùng là giữ gìn nơi công cộng.",options:["Bạn Nam bẻ cành cây","Bạn Tùng vẽ lên tường nhà chờ xe buýt","Bạn Vy nhặt rác bỏ vào thùng ở công viên"],answer:2},{id:"dd2-giu-gin-noi-cong-cong-06",type:"tf",q:"Của chung thì không ai cần giữ gìn.",emoji:"🤝",explain:"Của chung thì mọi người cùng giữ gìn.",answer:!1},{id:"dd2-giu-gin-noi-cong-cong-07",type:"mc",q:"Chơi cầu trượt ở công viên, em làm thế nào?",emoji:"🛝",explain:"Chơi đúng cách giúp đồ chơi bền, mọi người an toàn.",options:["Đứng lên trên nhún mạnh","Chơi lần lượt, nhẹ nhàng","Bôi bùn lên cầu trượt"],answer:1},{id:"dd2-giu-gin-noi-cong-cong-08",type:"tf",q:"Giữ gìn nơi công cộng là việc của mọi người.",emoji:"🏙️",explain:"Ai cũng góp phần giữ gìn nơi công cộng.",answer:!0},{id:"dd2-giu-gin-noi-cong-cong-09",type:"mc",q:"Đèn đường bị hỏng, ai nên báo cho người sửa?",emoji:"💡",explain:"Em có thể nhắc bố mẹ báo cho nơi quản lý.",options:["Không ai cả, cứ để đó","Người lớn thấy đèn hỏng","Chỉ có chú mèo ở nhà bên cạnh"],answer:1}]},{questions:[{id:"dd2-giu-gin-noi-cong-cong-10",type:"match",q:"Nối của chung với cách giữ gìn.",emoji:"🏞️",explain:"Mỗi của chung có cách giữ gìn riêng.",pairs:[["Ghế đá","Không viết vẽ, không đứng nhảy lên"],["Cây xanh","Không bẻ cành, không khắc tên"],["Nhà vệ sinh công cộng","Dùng xong xả nước, giữ sạch"],["Đồ chơi ở công viên","Chơi đúng cách, lần lượt"]]},{id:"dd2-giu-gin-noi-cong-cong-11",type:"multi",q:"Việc nào giúp giữ gìn nơi công cộng?",emoji:"✅",explain:"Dán giấy lên cột điện làm bẩn nơi công cộng.",options:["Bỏ rác đúng nơi","Nhắc bạn không bẻ cây","Dán giấy quảng cáo lên cột điện","Tham gia dọn vệ sinh khu phố"],answers:[0,1,3]},{id:"dd2-giu-gin-noi-cong-cong-12",type:"mc",q:"Vì sao cần giữ gìn của chung?",emoji:"🏙️",explain:"Của chung được giữ gìn thì ai cũng dùng được lâu.",options:["Để mọi người cùng dùng lâu dài","Để chỉ một mình em được dùng","Để được mọi người khen và thưởng quà"],answer:0},{id:"dd2-giu-gin-noi-cong-cong-13",type:"tf",q:"Đi dã ngoại xong, cả nhà em thu dọn rác trước khi về.",emoji:"🧺",explain:"Để lại nơi dã ngoại sạch sẽ là văn minh.",answer:!0},{id:"dd2-giu-gin-noi-cong-cong-14",type:"order",q:"Sắp xếp việc em làm sau buổi dã ngoại ở công viên.",emoji:"♻️",explain:"Thu gom, phân loại, bỏ đúng nơi và kiểm tra lại.",items:["Thu gom rác vào túi","Phân loại rác nếu có thùng riêng","Bỏ rác vào thùng","Kiểm tra lại chỗ ngồi đã sạch"]},{id:"dd2-giu-gin-noi-cong-cong-15",type:"mc",q:"Thấy bạn đứng nhún nhảy trên ghế đá, em nói gì?",emoji:"🪑",explain:"Nhắc nhẹ nhàng giúp bạn an toàn, giữ gìn của chung.",options:["Nhảy cao hơn nữa đi, cho mình nhảy với!","Không nói gì, đứng xem bạn nhảy tiếp","Bạn ngồi xuống nhé, kẻo hỏng ghế và ngã đấy"],answer:2},{id:"dd2-giu-gin-noi-cong-cong-16",type:"tf",q:"Đồ chơi ở công viên bị hỏng thì cứ chơi tiếp cho hỏng hẳn.",emoji:"⚠️",explain:"Em báo người lớn để sửa, tránh bị thương.",answer:!1},{id:"dd2-giu-gin-noi-cong-cong-17",type:"mc",q:"Em có thể làm gì để khu phố sạch đẹp?",emoji:"🧹",explain:"Giữ sạch trước nhà là góp phần làm khu phố đẹp.",options:["Đổ rác ra giữa lòng đường","Vứt rác qua cửa sổ xuống đường","Cùng gia đình quét dọn trước cửa nhà"],answer:2},{id:"dd2-giu-gin-noi-cong-cong-18",type:"mc",q:"Cây xanh ở công viên giúp gì cho mọi người?",emoji:"🌳",explain:"Cây xanh cho bóng mát, làm không khí trong lành.",options:["Cho bóng mát, không khí trong lành","Làm cho trời nóng bức hơn","Làm bẩn đường vì lá rụng nhiều"],answer:0}]},{questions:[{id:"dd2-giu-gin-noi-cong-cong-19",type:"mc",q:"Ở nhà chờ xe buýt, Minh thấy một bạn đang dùng bút vẽ lên tấm kính. Minh nên làm gì?",emoji:"🚏",explain:"Khuyên bạn để giữ gìn của chung.",options:["Lấy bút vẽ cùng bạn cho vui","Nhẹ nhàng khuyên bạn dừng lại","Chụp ảnh lại và khen bạn vẽ đẹp quá"],answer:1},{id:"dd2-giu-gin-noi-cong-cong-20",type:"mc",q:"Đi tham quan, nhóm của Hà ăn trưa ở bãi cỏ. Ăn xong, nhóm nên làm gì?",emoji:"🧺",explain:"Để lại nơi đã dùng sạch sẽ là văn minh.",options:["Thu gom rác, bỏ vào thùng","Để rác lại cho người dọn","Đốt rác trên cỏ"],answer:0},{id:"dd2-giu-gin-noi-cong-cong-21",type:"tf",q:"Thấy chiếc ghế đá công viên bị gãy chân, Thảo nhờ bố báo cho ban quản lý công viên. Thảo làm đúng.",emoji:"🪑",explain:"Báo để sửa giúp mọi người an toàn.",answer:!0},{id:"dd2-giu-gin-noi-cong-cong-22",type:"multi",q:"Khu phố tổ chức trồng cây. Em có thể góp sức thế nào?",emoji:"🌱",explain:"Bẻ cành cây non làm hại cây.",options:["Tưới nước cho cây","Nhặt rác quanh gốc cây","Bẻ cành cây non","Nhắc mọi người không buộc võng vào cây non"],answers:[0,1,3]},{id:"dd2-giu-gin-noi-cong-cong-23",type:"mc",q:"Bạn nói: “Của chung đâu phải của mình, hỏng cũng chẳng sao.” Em đáp thế nào?",emoji:"💬",explain:"Của chung là của mọi người, trong đó có em.",options:["Đúng rồi, của chung hỏng thì sẽ có người khác sửa thôi","Ừ, vậy mình cứ làm hỏng thêm cũng chẳng sao","Của chung mọi người cùng dùng nên ai cũng phải giữ"],answer:2},{id:"dd2-giu-gin-noi-cong-cong-24",type:"order",q:"Sắp xếp việc em làm khi dùng nhà vệ sinh công cộng.",emoji:"🚻",explain:"Xếp hàng, dùng, xả nước, rửa tay và khóa vòi.",items:["Xếp hàng chờ đến lượt","Dùng nhà vệ sinh","Xả nước","Rửa tay, khóa vòi"]},{id:"dd2-giu-gin-noi-cong-cong-25",type:"tf",q:"Bình hái trộm vài bông hoa ở công viên vì nghĩ một vài bông thì không sao.",emoji:"🌸",explain:"Nếu ai cũng hái vài bông, vườn hoa sẽ không còn hoa.",answer:!1},{id:"dd2-giu-gin-noi-cong-cong-26",type:"mc",q:"Lớp em đi tham quan đền, chùa. Em cư xử thế nào?",emoji:"🛕",explain:"Giữ trật tự, tôn trọng nơi tham quan.",options:["Leo trèo lên tượng để chụp ảnh","Đi nhẹ, nói khẽ, không sờ vào đồ thờ","Nói cười thật to, chạy khắp sân"],answer:1},{id:"dd2-giu-gin-noi-cong-cong-27",type:"fill",q:"Ghế đá, cây xanh ở công viên là của …, mọi người cùng giữ gìn.",emoji:"🪑",explain:"Đó là của chung, mọi người cùng giữ gìn.",answer:["chung"],loose:!0}]}],challenge:{questions:[{id:"dd2-giu-gin-noi-cong-cong-28",type:"match",q:"Nối tình huống với việc em nên làm.",emoji:"🏙️",explain:"Em góp phần giữ gìn nơi công cộng.",pairs:[["Thấy bạn vẽ bậy lên tường","Nhẹ nhàng khuyên bạn"],["Đồ chơi công viên bị hỏng","Báo người lớn"],["Ăn xong ở bãi cỏ","Thu gom rác"],["Vòi nước công cộng bị rò","Báo người quản lý"]]},{id:"dd2-giu-gin-noi-cong-cong-29",type:"mc",q:"Khoa thấy một chú vứt túi rác xuống hồ công viên. Cách nào phù hợp với Khoa?",emoji:"🏞️",explain:"Báo người lớn là cách an toàn, phù hợp với em.",options:["Ném đá xuống hồ về phía chú","Báo bố mẹ hoặc bảo vệ công viên","Vứt thêm rác xuống hồ cho vui"],answer:1},{id:"dd2-giu-gin-noi-cong-cong-19",type:"mc",q:"Ở nhà chờ xe buýt, Minh thấy một bạn đang dùng bút vẽ lên tấm kính. Minh nên làm gì?",emoji:"🚏",explain:"Khuyên bạn để giữ gìn của chung.",options:["Lấy bút vẽ cùng bạn cho vui","Nhẹ nhàng khuyên bạn dừng lại","Chụp ảnh lại và khen bạn vẽ đẹp quá"],answer:1},{id:"dd2-giu-gin-noi-cong-cong-20",type:"mc",q:"Đi tham quan, nhóm của Hà ăn trưa ở bãi cỏ. Ăn xong, nhóm nên làm gì?",emoji:"🧺",explain:"Để lại nơi đã dùng sạch sẽ là văn minh.",options:["Thu gom rác, bỏ vào thùng","Để rác lại cho người dọn","Đốt rác trên cỏ"],answer:0},{id:"dd2-giu-gin-noi-cong-cong-23",type:"mc",q:"Bạn nói: “Của chung đâu phải của mình, hỏng cũng chẳng sao.” Em đáp thế nào?",emoji:"💬",explain:"Của chung là của mọi người, trong đó có em.",options:["Đúng rồi, của chung hỏng thì sẽ có người khác sửa thôi","Ừ, vậy mình cứ làm hỏng thêm cũng chẳng sao","Của chung mọi người cùng dùng nên ai cũng phải giữ"],answer:2},{id:"dd2-giu-gin-noi-cong-cong-25",type:"tf",q:"Bình hái trộm vài bông hoa ở công viên vì nghĩ một vài bông thì không sao.",emoji:"🌸",explain:"Nếu ai cũng hái vài bông, vườn hoa sẽ không còn hoa.",answer:!1}]},summary:["Của chung ở nơi công cộng, mọi người cùng giữ gìn.","Em không viết vẽ bậy, không xả rác, không làm hỏng.","Em nhắc nhở mọi người cùng giữ gìn nơi công cộng."]}]}],c={grade:2,subject:n,title:i,review:h,topics:t};export{c as default,g as grade,h as review,n as subject,i as title,t as topics};
